fn desired_surface_label(surface: &DesiredSurface) -> &'static str {
    match surface {
        DesiredSurface::Web => "web",
        DesiredSurface::Cli => "cli",
        DesiredSurface::Desktop => "desktop",
        DesiredSurface::HelperWeb => "helper_web",
        DesiredSurface::Unknown => "unknown",
    }
}

fn exoskeleton_target_label(target: &ExoskeletonTarget) -> &'static str {
    match target {
        ExoskeletonTarget::None => "none",
        ExoskeletonTarget::ChattyCog => "chatty_cog",
    }
}

fn normalized_failure_class_for_build_failure(
    failure_class: &FailureClass,
    failure_mode: &str,
    summary: &str,
) -> String {
    let lower = summary.to_ascii_lowercase();
    if failure_mode.contains("missing_entrypoint") {
        "missing_expected_files".into()
    } else if failure_mode.contains("cargo_check_failed")
        || failure_mode.contains("cargo_run_failed")
        || failure_mode.contains("python_execution_failed")
        || failure_mode.contains("helper_contract_failed")
        || failure_mode.contains("chattycog_contract_failed")
    {
        "verification_failure".into()
    } else if failure_mode.contains("execution_smoke") {
        "environment_instability".into()
    } else if failure_mode.contains("clarification_required") {
        "route_selection_mismatch".into()
    } else if failure_mode.contains("composition_review_denied") {
        "task_too_broad".into()
    } else if failure_mode.contains("no_deterministic_family_match") {
        "unsupported_substrate_capability".into()
    } else if lower.contains("not supported by a deterministic bounded substrate yet")
        || lower.contains("explicit stack")
    {
        "unsupported_substrate_capability".into()
    } else {
        match failure_class {
            FailureClass::InvalidMetadata => "contract_mismatch".into(),
            FailureClass::MissingExpectedFiles => "missing_expected_files".into(),
            FailureClass::OperatorMismatch => "contract_mismatch".into(),
            FailureClass::DomEligibilityMismatch => "contract_mismatch".into(),
            FailureClass::PolicyViolation => "policy_violation".into(),
            FailureClass::UnsupportedFamilyCapability => "unsupported_substrate_capability".into(),
            FailureClass::ToolchainMismatch => "missing_dependency_or_toolchain".into(),
            FailureClass::StructuredCodeGenerationMismatch => "verification_failure".into(),
            FailureClass::HelperWiringFailure => "verification_failure".into(),
            FailureClass::SyntaxFailure => "verification_failure".into(),
            FailureClass::BuildFailure => "verification_failure".into(),
            FailureClass::RuntimeAssertionFailure => "verification_failure".into(),
            FailureClass::RouteSelectionMismatch => "route_selection_mismatch".into(),
            FailureClass::Unknown => "verification_failure".into(),
        }
    }
}

fn normalized_failure_class_for_task_attempt(
    receipt: &PlanTaskModelAttemptReceipt,
    decomposition: Option<&TaskDecompositionReceipt>,
) -> String {
    if decomposition.is_some() {
        return "task_too_broad".into();
    }
    let findings = receipt.review_findings.join(" ").to_ascii_lowercase();
    if findings.contains("reasoning_fallback") || findings.contains("reasoning spill") {
        return "model_output_format_failure".into();
    }
    if receipt.status == "method_space_exhausted" {
        return "method_space_exhausted".into();
    }
    if receipt.status == "blocked_by_review" {
        return "contract_mismatch".into();
    }
    if findings.contains("omitted") || findings.contains("missing") {
        return "contract_mismatch".into();
    }
    if findings.contains("placeholder") {
        return "semantic_quality_failure".into();
    }
    if receipt.status.contains("decomposition") {
        return "task_too_broad".into();
    }
    "model_output_format_failure".into()
}

fn normalized_failure_class_for_patch_preflight(
    reason: &str,
    patch_constraint_review: &ConstraintReviewReceipt,
) -> String {
    let lower = reason.to_ascii_lowercase();
    if lower.contains("no direct deterministic patch lane matched") {
        "route_selection_mismatch".into()
    } else if lower.contains("superseded")
        || lower.contains("conflict")
        || lower.contains("anchor")
        || !patch_constraint_review.violations.is_empty()
    {
        "contract_mismatch".into()
    } else if lower.contains("clarif") {
        "route_selection_mismatch".into()
    } else {
        "verification_failure".into()
    }
}

fn normalized_failure_class_for_patch_postcheck(
    warnings: &[String],
    out_of_contract_modified_files: &[String],
) -> String {
    let joined = warnings.join(" ").to_ascii_lowercase();
    if !out_of_contract_modified_files.is_empty() {
        "contract_mismatch".into()
    } else if joined.contains("missing") {
        "missing_expected_files".into()
    } else if joined.contains("changed after patch") || joined.contains("did not modify") {
        "verification_failure".into()
    } else if warnings.is_empty() {
        String::new()
    } else {
        "verification_failure".into()
    }
}

fn normalized_failure_class_for_patch_plan_review(
    decision: &str,
    blocked_reasons: &[String],
) -> String {
    if decision == "blocked_pending_replan" {
        if blocked_reasons.iter().any(|reason| {
            let lower = reason.to_ascii_lowercase();
            lower.contains("surface contract")
                || lower.contains("target file")
                || lower.contains("declared patch surface")
        }) {
            "contract_mismatch".into()
        } else {
            "route_selection_mismatch".into()
        }
    } else if decision == "proceed_with_refined_plan" {
        "route_selection_mismatch".into()
    } else {
        String::new()
    }
}

fn patch_plan_review_next_action(
    decision: &str,
    normalized_failure_class: &str,
) -> MechanicalNextAction {
    match decision {
        "proceed_with_original_plan" => MechanicalNextAction {
            action_id: "execute_original_patch_plan".into(),
            recommended_next_step:
                "execute the current patch plan as reviewed; no further routing change is required"
                    .into(),
            rationale: vec![
                "patch self-review preserved the original plan without narrowing or redirection".into(),
            ],
        },
        "proceed_with_refined_plan" => MechanicalNextAction {
            action_id: "execute_refined_patch_plan".into(),
            recommended_next_step:
                "execute the refined patch plan that self-review narrowed or redirected"
                    .into(),
            rationale: vec![
                "patch self-review changed the plan shape before execution".into(),
                "the host should follow the refined reviewed plan rather than the original request wording".into(),
            ],
        },
        _ => select_mechanical_next_action(
            normalized_failure_class,
            Some("bundle"),
            0,
            false,
        ),
    }
}

fn normalized_failure_class_for_patch_constraint_review(
    decision: &str,
    violations: &[ConstraintViolation],
) -> String {
    if decision == "block_execution" {
        if violations.iter().any(|violation| {
            let lower = violation.reason.to_ascii_lowercase();
            lower.contains("missing")
                || lower.contains("anchor")
                || lower.contains("legacy")
                || lower.contains("structural")
        }) {
            "contract_mismatch".into()
        } else {
            "verification_failure".into()
        }
    } else if matches!(
        decision,
        "allow_composed_replacement_bundle" | "allow_refined_patch_kind"
    ) {
        "route_selection_mismatch".into()
    } else {
        String::new()
    }
}

fn patch_constraint_review_next_action(
    decision: &str,
    normalized_failure_class: &str,
) -> MechanicalNextAction {
    match decision {
        "allow_current_plan" => MechanicalNextAction {
            action_id: "execute_current_patch_plan".into(),
            recommended_next_step:
                "execute the current reviewed patch plan; constraint review did not find a forbidden method"
                    .into(),
            rationale: vec![
                "constraint review found no active blocking implementation constraint".into(),
            ],
        },
        "allow_bundle_already_present_skip" => MechanicalNextAction {
            action_id: "skip_historical_patch_as_already_present".into(),
            recommended_next_step:
                "skip the historical patch method because the modern replacement bundle is already present"
                    .into(),
            rationale: vec![
                "constraint review accepted the replacement bundle as already satisfied".into(),
            ],
        },
        "allow_composed_replacement_bundle" => MechanicalNextAction {
            action_id: "execute_composed_replacement_bundle".into(),
            recommended_next_step:
                "execute the modern replacement bundle instead of the blocked historical patch method"
                    .into(),
            rationale: vec![
                "constraint review preserved a composed replacement execution set".into(),
            ],
        },
        "allow_refined_patch_kind" => MechanicalNextAction {
            action_id: "execute_refined_patch_kind".into(),
            recommended_next_step:
                "execute the refined patch kind that survived constraint review instead of the original method"
                    .into(),
            rationale: vec![
                "constraint review rejected the original method but preserved a refined patch kind".into(),
            ],
        },
        _ => select_mechanical_next_action(
            normalized_failure_class,
            Some("leaf_semantic_unit"),
            0,
            false,
        ),
    }
}

fn paired_proof_next_action(
    equivalent_capability_fulfillment: bool,
) -> (String, MechanicalNextAction) {
    if equivalent_capability_fulfillment {
        (
            String::new(),
            MechanicalNextAction {
                action_id: "none_proof_equivalence_passed".into(),
                recommended_next_step:
                    "paired proof passed; keep the receipt as baseline evidence and continue from the proven equivalent state"
                        .into(),
                rationale: vec![
                    "the paired proof satisfied the required capability bundle across both generated projects".into(),
                ],
            },
        )
    } else {
        let normalized_failure_class = "verification_failure".to_string();
        let next_action =
            select_mechanical_next_action(&normalized_failure_class, Some("bundle"), 0, false);
        (normalized_failure_class, next_action)
    }
}

fn normalized_failure_class_for_governance_receipt(
    drift_status: &str,
    baseline_status: &str,
    blockers: &[String],
) -> String {
    if blockers.iter().any(|blocker| {
        let lower = blocker.to_ascii_lowercase();
        lower.contains("missing")
    }) {
        return "missing_expected_files".into();
    }
    if !blockers.is_empty() {
        return "contract_mismatch".into();
    }
    if baseline_status.starts_with("regressed_") {
        return "contract_mismatch".into();
    }
    if drift_status == "drifted_risky" {
        return "verification_failure".into();
    }
    String::new()
}

fn governance_next_action(
    normalized_failure_class: &str,
    stable_guidance: &str,
) -> MechanicalNextAction {
    if normalized_failure_class.is_empty() {
        MechanicalNextAction {
            action_id: "retain_current_governance_state".into(),
            recommended_next_step: stable_guidance.into(),
            rationale: vec![
                "governance refresh found no concrete failure class that requires reroute or repair"
                    .into(),
            ],
        }
    } else {
        select_mechanical_next_action(normalized_failure_class, Some("bundle"), 0, false)
    }
}

fn normalized_failure_class_for_constraint_approval(status: &str) -> String {
    match status {
        "approved" => String::new(),
        _ => "verification_failure".into(),
    }
}

fn constraint_approval_next_action(normalized_failure_class: &str) -> MechanicalNextAction {
    if normalized_failure_class.is_empty() {
        MechanicalNextAction {
            action_id: "keep_constraint_active_and_monitor_matches".into(),
            recommended_next_step:
                "keep the approved constraint active on the shelf and continue monitoring future match evidence"
                    .into(),
            rationale: vec![
                "constraint approval completed successfully and the shelf now contains the approved rule"
                    .into(),
            ],
        }
    } else {
        select_mechanical_next_action(normalized_failure_class, Some("bundle"), 0, false)
    }
}

fn normalized_failure_class_for_constraint_shelf_mutation(action: &str, status: &str) -> String {
    match (action, status) {
        ("approve", "approved_into_shelf")
        | ("activate", "applied")
        | ("deactivate", "applied")
        | ("bulk_deactivate_low_value_active", "deactivated")
        | ("archive", "removed_from_shelf")
        | ("restore", "restored_from_history") => String::new(),
        _ => "verification_failure".into(),
    }
}

fn constraint_shelf_mutation_next_action(
    action: &str,
    normalized_failure_class: &str,
) -> MechanicalNextAction {
    if !normalized_failure_class.is_empty() {
        return select_mechanical_next_action(normalized_failure_class, Some("bundle"), 0, false);
    }

    let (action_id, step, rationale) = match action {
        "approve" => (
            "monitor_newly_approved_constraint",
            "leave the approved rule on the shelf and watch future match evidence before narrowing or retiring it",
            "the rule is now active shelf evidence and should earn its keep through future matches",
        ),
        "activate" => (
            "monitor_reactivated_constraint",
            "leave the constraint active and monitor whether new failures match it cleanly",
            "reactivation succeeded, so the next move is evidence collection rather than further shelf mutation",
        ),
        "deactivate" | "bulk_deactivate_low_value_active" => (
            "leave_constraint_inactive_and_monitor",
            "leave the constraint inactive and monitor whether new evidence justifies reactivation or archival",
            "inactive shelf state is now the host-owned posture until new match evidence arrives",
        ),
        "archive" => (
            "retain_archived_constraint_in_history",
            "leave the constraint archived in shelf history and restore it only if new evidence makes it relevant again",
            "the host moved the rule out of the active shelf without deleting the evidence trail",
        ),
        "restore" => (
            "monitor_restored_constraint",
            "leave the restored constraint on the shelf and watch whether fresh failures actually match it",
            "restore succeeded, so the next move is evidence gathering rather than immediate re-mutation",
        ),
        _ => (
            "retain_current_shelf_state",
            "keep the current shelf state and continue monitoring future evidence",
            "the mutation completed and no further reroute is required immediately",
        ),
    };

    MechanicalNextAction {
        action_id: action_id.into(),
        recommended_next_step: step.into(),
        rationale: vec![rationale.into()],
    }
}

#[derive(Debug, Clone)]
struct MechanicalNextAction {
    action_id: String,
    recommended_next_step: String,
    rationale: Vec<String>,
}

fn select_mechanical_next_action(
    normalized_failure_class: &str,
    current_granularity: Option<&str>,
    repeated_same_failure_count: usize,
    alternate_method_evidence_present: bool,
) -> MechanicalNextAction {
    match normalized_failure_class {
        "task_too_broad" => {
            if matches!(current_granularity, Some("leaf_semantic_unit" | "build_failure_signature")) {
                MechanicalNextAction {
                    action_id: "retry_with_alternate_method_before_promotion".into(),
                    recommended_next_step:
                        "change method or prompt posture before retrying; this task is already at the atomization floor"
                            .into(),
                    rationale: vec![
                        "normalized failure class resolved to `task_too_broad`".into(),
                        "current granularity is already at the atomization floor, so further splitting would risk atomizing into dust".into(),
                    ],
                }
            } else {
                MechanicalNextAction {
                    action_id: "decompose_by_matched_grammar".into(),
                    recommended_next_step:
                        "apply the matched decomposition grammar and retry the narrower child task shape"
                            .into(),
                    rationale: vec![
                        "normalized failure class resolved to `task_too_broad`".into(),
                        "the host should prefer reusable decomposition grammar over bespoke retry behavior".into(),
                    ],
                }
            }
        }
        "method_space_exhausted" => MechanicalNextAction {
            action_id: "escalate_model_ladder".into(),
            recommended_next_step:
                "escalate retry search to the next model candidate after exhausting alternate methods on the current model"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `method_space_exhausted`".into(),
                "the current retry posture set has already been spent for this model candidate".into(),
            ],
        },
        "model_output_format_failure" => MechanicalNextAction {
            action_id: "retry_with_changed_generation_posture".into(),
            recommended_next_step:
                "retry with a changed generation posture, extraction mode, or recovery prompt before widening scope"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `model_output_format_failure`".into(),
                "the model emitted the wrong output shape rather than proving the overall request impossible".into(),
            ],
        },
        "route_selection_mismatch" => MechanicalNextAction {
            action_id: "clarify_and_refreeze_intent".into(),
            recommended_next_step:
                "collect clarification, refreeze intent, and rerun the bounded attempt without silently coercing to a nearby family"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `route_selection_mismatch`".into(),
                "host-owned truth says the current interpretation is not stable enough to execute honestly".into(),
            ],
        },
        "unsupported_substrate_capability" => MechanicalNextAction {
            action_id: "surface_requirement_gap_honestly".into(),
            recommended_next_step:
                "surface the unmet requirement honestly and prepare a bounded substrate attempt instead of coercing to the nearest known family"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `unsupported_substrate_capability`".into(),
                "supported lanes are helpers, not laws, so the factory should record the gap rather than disguise it".into(),
            ],
        },
        "missing_dependency_or_toolchain" => MechanicalNextAction {
            action_id: "repair_toolchain_then_retry".into(),
            recommended_next_step:
                "repair the missing dependency or toolchain contract, then retry the same bounded attempt"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `missing_dependency_or_toolchain`".into(),
                "verification failure points to missing environment structure rather than a wrong project shape".into(),
            ],
        },
        "missing_expected_files" => MechanicalNextAction {
            action_id: "repair_missing_artifacts_then_retry".into(),
            recommended_next_step:
                "repair the missing generated artifacts or entrypoints before retrying verification"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `missing_expected_files`".into(),
                "the bounded attempt is missing contractually required files".into(),
            ],
        },
        "contract_mismatch" => MechanicalNextAction {
            action_id: "repair_contract_then_retry".into(),
            recommended_next_step:
                "repair the failing contract surface and retry without broadening the request"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `contract_mismatch`".into(),
                "host verification found a concrete contract violation rather than a broad planning failure".into(),
            ],
        },
        "environment_instability" => MechanicalNextAction {
            action_id: "stabilize_environment_then_retry".into(),
            recommended_next_step:
                "stabilize the runtime environment or execution smoke path, then retry the bounded attempt"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `environment_instability`".into(),
                "the failure signature points at execution conditions rather than request interpretation".into(),
            ],
        },
        "policy_violation" => MechanicalNextAction {
            action_id: "stop_and_surface_policy_constraint".into(),
            recommended_next_step:
                "stop the current attempt and surface the policy boundary explicitly before any retry"
                    .into(),
            rationale: vec![
                "normalized failure class resolved to `policy_violation`".into(),
                "policy failures should be surfaced, not metabolized as ordinary implementation retries".into(),
            ],
        },
        "verification_failure" | "semantic_quality_failure" => {
            if repeated_same_failure_count >= 1 && alternate_method_evidence_present {
                MechanicalNextAction {
                    action_id: "promote_after_convergent_triangulation".into(),
                    recommended_next_step:
                        "propose a narrow negative constraint because repeated alternate-method retries converged on the same blocker"
                            .into(),
                    rationale: vec![
                        format!(
                            "same normalized failure has already repeated {} time(s)",
                            repeated_same_failure_count + 1
                        ),
                        "alternate-method evidence is present, so promotion can be considered without turning one failure into a rule".into(),
                    ],
                }
            } else {
                MechanicalNextAction {
                    action_id: "retry_with_changed_method".into(),
                    recommended_next_step:
                        "retry with a changed implementation method or recovery posture before promoting any constraint"
                            .into(),
                    rationale: vec![
                        format!(
                            "same normalized failure observations before this attempt: {}",
                            repeated_same_failure_count
                        ),
                        if alternate_method_evidence_present {
                            "alternate-method evidence exists, but convergent repetition is not yet strong enough for promotion".into()
                        } else {
                            "promotion is blocked until the same narrow failure is observed under a changed method or posture".into()
                        },
                    ],
                }
            }
        }
        _ => MechanicalNextAction {
            action_id: "inspect_and_retry_with_changed_method".into(),
            recommended_next_step:
                "inspect the trapped evidence and retry with a changed bounded method before widening scope"
                    .into(),
            rationale: vec![
                format!(
                    "normalized failure class `{normalized_failure_class}` did not match a narrower mechanical route"
                ),
                "defaulting to evidence-first retry posture keeps the host mechanically grounded without silently giving up".into(),
            ],
        },
    }
}

fn explicit_stack_requirement_satisfied(
    explicit_stack: &str,
    substrate_kind: Option<&str>,
    tool_kind: Option<&str>,
) -> bool {
    let stack = explicit_stack.to_ascii_lowercase();
    let substrate = substrate_kind.unwrap_or_default().to_ascii_lowercase();
    let tool = tool_kind.unwrap_or_default().to_ascii_lowercase();

    match stack.as_str() {
        "rust" => {
            substrate == "cli"
                || substrate == "native_window"
                || substrate == "workspace"
                || tool.contains("rust")
                || tool == "dashboard"
        }
        "python" => substrate == "cli" && tool.contains("python"),
        "golang" | "go" => tool.contains("go"),
        "electron" => tool.contains("electron"),
        "flutter" => tool.contains("flutter"),
        "static_web" => {
            substrate == "static_web"
                || substrate == "webview"
                || tool == "dashboard"
                || tool.contains("web")
        }
        other => substrate.contains(other) || tool.contains(other),
    }
}

fn classify_execution_outcome(
    kind: &str,
    freeze: Option<&BuildIntentFreeze>,
    substrate_kind: Option<&str>,
    tool_kind: Option<&str>,
    acceptance_status: Option<&str>,
    route_notes: &[String],
) -> (String, Vec<String>) {
    let mut notes = Vec::new();
    if let Some(freeze) = freeze {
        if let Some(stack) = freeze.explicit_stack.as_deref() {
            if !explicit_stack_requirement_satisfied(stack, substrate_kind, tool_kind) {
                notes.push(format!(
                    "explicit stack requirement `{stack}` was not satisfied by the current bounded artifact"
                ));
                return ("requirement_not_met".into(), notes);
            }
        }
    }

    if kind == "patch_prepare" {
        notes.push(
            "the factory prepared a grounded substrate attempt rather than completing the requested patch"
                .into(),
        );
        return ("partial_success".into(), notes);
    }
    if kind == "patch_skip" {
        notes.push(
            "the host preserved patch truth by skipping direct execution after diagnosis freeze"
                .into(),
        );
        return ("partial_success".into(), notes);
    }
    if route_notes
        .iter()
        .any(|note| note.contains("soft-review tolerance"))
    {
        notes.push(
            "the artifact proceeded through bounded soft review and should be treated as a degraded evidence-shaped next attempt"
                .into(),
        );
        return ("degraded_next_attempt".into(), notes);
    }

    match acceptance_status {
        Some("passed") | Some("equivalent") | Some("ready") => ("full_success".into(), notes),
        Some(status) => {
            notes.push(format!("acceptance status remained `{status}`"));
            ("partial_success".into(), notes)
        }
        None => ("partial_success".into(), notes),
    }
}

fn classify_next_attempt_outcome(
    request: &RequestRecord,
    plan: &RequestPlan,
    summary: &str,
) -> (String, Vec<String>) {
    let mut notes = Vec::new();
    if let Some(stack) = request.explicit_stack.as_deref() {
        if !plan.inferred_substrate_candidates.iter().any(|substrate_kind| {
            explicit_stack_requirement_satisfied(
                stack,
                Some(substrate_kind.as_str()),
                plan.inferred_tool_kind.as_deref(),
            )
        }) {
            notes.push(format!(
                "explicit stack requirement `{stack}` does not currently have an honest bounded result on this route"
            ));
            return ("requirement_not_met".into(), notes);
        }
    }
    notes.push(summary.to_string());
    ("degraded_next_attempt".into(), notes)
}

enum BuilderExecutionBackend {
    StaticWeb,
    PythonCli,
    RustCli,
}

fn select_builder_execution_backend(
    substrate_kind: Option<&SubstrateKind>,
    explicit_stack: Option<&str>,
    tool_kind: Option<&str>,
) -> Result<BuilderExecutionBackend> {
    match substrate_kind {
        Some(SubstrateKind::StaticWeb) | None => Ok(BuilderExecutionBackend::StaticWeb),
        Some(SubstrateKind::Cli) => {
            let stack = explicit_stack.unwrap_or_default().to_ascii_lowercase();
            let tool = tool_kind.unwrap_or_default().to_ascii_lowercase();
            if stack == "python" || tool.contains("python") || tool == "csv_report" {
                Ok(BuilderExecutionBackend::PythonCli)
            } else if stack == "rust" || tool.contains("rust") || tool == "log_summary" {
                Ok(BuilderExecutionBackend::RustCli)
            } else {
                Ok(BuilderExecutionBackend::RustCli)
            }
        }
        Some(other) => Err(anyhow!(
            "selected substrate is not executable by the negative-lane host shell: {}",
            other.as_str()
        )),
    }
}

fn project_spec_substrate_kind(spec: &ProjectSpec) -> Option<SubstrateKind> {
    match spec.substrate.trim() {
        "static_web" => Some(SubstrateKind::StaticWeb),
        "python_cli" | "rust_cli" | "cli" => Some(SubstrateKind::Cli),
        "webview" => Some(SubstrateKind::Webview),
        "native_window" => Some(SubstrateKind::NativeWindow),
        "workspace" => Some(SubstrateKind::Workspace),
        _ => None,
    }
}

fn project_spec_substrate_kind_ref(spec: &ProjectSpec) -> Option<SubstrateKind> {
    project_spec_substrate_kind(spec)
}

fn project_spec_substrate_label(spec: &ProjectSpec) -> Option<&str> {
    match spec.substrate.trim() {
        "static_web" => Some("static_web"),
        "python_cli" | "rust_cli" | "cli" => Some("cli"),
        "webview" => Some("webview"),
        "native_window" => Some("native_window"),
        "workspace" => Some("workspace"),
        _ => None,
    }
}

fn parse_substrate_kind_label(value: &str) -> Option<SubstrateKind> {
    match value.trim() {
        "static_web" => Some(SubstrateKind::StaticWeb),
        "python_cli" | "rust_cli" | "cli" => Some(SubstrateKind::Cli),
        "webview" => Some(SubstrateKind::Webview),
        "native_window" => Some(SubstrateKind::NativeWindow),
        "workspace" => Some(SubstrateKind::Workspace),
        _ => None,
    }
}

fn execution_outcome_next_action(
    kind: &str,
    outcome_class: &str,
    acceptance_status: Option<&str>,
) -> MechanicalNextAction {
    match outcome_class {
        "full_success" => MechanicalNextAction {
            action_id: "retain_verified_state".into(),
            recommended_next_step:
                "keep the verified artifact state as the new baseline and continue from this grounded result"
                    .into(),
            rationale: vec![
                format!("execution outcome for `{kind}` classified as `full_success`"),
                "the host verified the current bounded result, so no repair reroute is required"
                    .into(),
            ],
        },
        "partial_success" => {
            let step = if matches!(kind, "patch_prepare" | "patch_skip") {
                "continue with the bounded follow-up patch route instead of treating the prepared substrate as final completion"
            } else if matches!(acceptance_status, Some("failed" | "partial")) {
                "inspect the verification receipts and continue with a bounded follow-up rather than treating the artifact as complete"
            } else {
                "continue with the next bounded follow-up step the receipts point to; the current result is usable evidence, not final completion"
            };
            MechanicalNextAction {
                action_id: "continue_with_bounded_followup".into(),
                recommended_next_step: step.into(),
                rationale: vec![
                    format!("execution outcome for `{kind}` classified as `partial_success`"),
                    "the host distinguishes usable progress from full completion and keeps continuation explicit".into(),
                ],
            }
        }
        "degraded_next_attempt" => MechanicalNextAction {
            action_id: "continue_from_degraded_attempt".into(),
            recommended_next_step:
                "continue from the degraded substrate attempt without presenting it as equivalent to the original hard requirement"
                    .into(),
            rationale: vec![
                format!("execution outcome for `{kind}` classified as `degraded_next_attempt`"),
                "the host should preserve the artifact as a bounded next attempt while surfacing that it is not a clean full success".into(),
            ],
        },
        "requirement_not_met" => MechanicalNextAction {
            action_id: "surface_requirement_gap_honestly".into(),
            recommended_next_step:
                "surface the unmet hard requirement explicitly and choose a new bounded attempt only if the requirement can be preserved honestly"
                    .into(),
            rationale: vec![
                format!("execution outcome for `{kind}` classified as `requirement_not_met`"),
                "the current artifact cannot be represented as satisfying the user’s hard requirement".into(),
            ],
        },
        _ => MechanicalNextAction {
            action_id: "inspect_execution_receipts".into(),
            recommended_next_step:
                "inspect the execution receipts and decide the next bounded move from the host-owned evidence"
                    .into(),
            rationale: vec![format!(
                "execution outcome for `{kind}` did not match a narrower explicit posture"
            )],
        },
    }
}

fn with_execution_outcome_posture(mut result: HostExecutionResult) -> HostExecutionResult {
    if let Some(outcome_class) = result.outcome_class.as_deref() {
        let next_action = execution_outcome_next_action(
            &result.kind,
            outcome_class,
            result.acceptance_status.as_deref(),
        );
        result.recommended_next_action = Some(next_action.action_id);
        result.recommended_next_step = next_action.recommended_next_step;
    }
    result
}

fn derive_build_plan_artifact(
    build_intent_freeze: &BuildIntentFreeze,
    request: &RequestRecord,
    plan: &RequestPlan,
    route: &chatty_factory_core::RouteDecision,
    inputs: &chatty_factory_core::BuildSeedInputs,
    _recommended_seed_id: Option<&str>,
) -> BuildPlanArtifact {
    let feature_slices = derive_build_feature_slices(request, plan, route, inputs);
    let selected_substrate_kind = route
        .selected_substrate_kind
        .clone()
        .or_else(|| plan.inferred_substrate_candidates.first().cloned());
    BuildPlanArtifact {
        build_plan_id: chatty_factory_core::timestamp_id("build-plan"),
        request_id: request.request_id.clone(),
        source_request_plan_id: plan.plan_id.clone(),
        source_build_intent_freeze_id: build_intent_freeze.freeze_id.clone(),
        project_name: inputs.project_name.clone(),
        substrate_kind: selected_substrate_kind.clone(),
        desired_surface: request.desired_surface.clone(),
        exoskeleton_target: request.exoskeleton_target.clone(),
        tool_kind: plan.inferred_tool_kind.clone(),
        interpreted_goal: plan.interpreted_goal.clone(),
        feature_slices: feature_slices.clone(),
        planned_file_operations: planned_file_operations_for_build(
            selected_substrate_kind.as_ref(),
            plan.inferred_tool_kind.as_deref(),
            &feature_slices,
        ),
        acceptance_targets: acceptance_targets_for_build_plan(plan),
        constraints: plan.constraints.clone(),
        rationale: plan.rationale.clone(),
        route_decision_reasons: route.decision_reasons.clone(),
        confidence_score: plan.confidence_score,
        confidence_band: plan.confidence_band.clone(),
        needs_llm_review: plan.needs_llm_review,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn derive_build_intent_freeze(
    request: &RequestRecord,
    plan: &RequestPlan,
    route: &chatty_factory_core::RouteDecision,
    inputs: &chatty_factory_core::BuildSeedInputs,
    recommended_seed_id: Option<&str>,
) -> BuildIntentFreeze {
    let mut hard_requirements = Vec::new();
    let mut preference_notes = Vec::new();
    let mut freeze_notes = Vec::new();

    if let Some(stack) = request.explicit_stack.as_deref() {
        hard_requirements.push(format!(
            "preserve explicit stack/toolchain request: {stack}"
        ));
    }
    if let Some(surface) = request.desired_surface.as_ref() {
        hard_requirements.push(format!(
            "preserve desired surface: {}",
            desired_surface_label(surface)
        ));
    }
    if let Some(target) = request.exoskeleton_target.as_ref() {
        hard_requirements.push(format!(
            "preserve exoskeleton target: {}",
            exoskeleton_target_label(target)
        ));
    }
    if !request.requested_capabilities.is_empty() {
        hard_requirements.push(format!(
            "attempt requested capabilities: {}",
            request.requested_capabilities.join(", ")
        ));
    }

    if let Some(tool_kind) = plan.inferred_tool_kind.as_deref() {
        preference_notes.push(format!("current bounded tool kind: {tool_kind}"));
    }
    if !plan.inferred_substrate_candidates.is_empty() {
        preference_notes.push(format!(
            "current bounded substrate candidates: {}",
            plan.inferred_substrate_candidates
                .iter()
                .map(chatty_factory_core::SubstrateKind::as_str)
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if let Some(selected_substrate_kind) = route.selected_substrate_kind.as_ref() {
        freeze_notes.push(format!(
            "selected bounded substrate: {}",
            selected_substrate_kind.as_str()
        ));
    }
    if let Some(recommended_seed_id) = recommended_seed_id {
        freeze_notes.push(format!(
            "normal routing recommendation at freeze time: {}",
            recommended_seed_id
        ));
    }
    if !plan.constraints.is_empty() {
        freeze_notes.push(format!(
            "freeze carries forward bounded constraints: {}",
            plan.constraints.join(" | ")
        ));
    }
    if !plan.escalation_reasons.is_empty() {
        freeze_notes.push(format!(
            "freeze carries forward bounded review/escalation reasons: {}",
            plan.escalation_reasons.join(" | ")
        ));
    }
    freeze_notes.push(format!(
        "freeze bound interpreted goal `{}` to project seed `{}`",
        plan.interpreted_goal, inputs.project_name
    ));

    BuildIntentFreeze {
        freeze_id: chatty_factory_core::timestamp_id("build-intent-freeze"),
        request_id: request.request_id.clone(),
        source_request_plan_id: plan.plan_id.clone(),
        mode: request.mode.clone(),
        raw_request: request.raw_request.clone(),
        project_name: inputs.project_name.clone(),
        target_substrate_kind: route.selected_substrate_kind.clone(),
        explicit_stack: request.explicit_stack.clone(),
        desired_surface: request.desired_surface.clone(),
        exoskeleton_target: request.exoskeleton_target.clone(),
        inferred_tool_kind: plan.inferred_tool_kind.clone(),
        interpreted_goal: plan.interpreted_goal.clone(),
        candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
        requested_capabilities: request.requested_capabilities.clone(),
        hard_requirements,
        preference_notes,
        ambiguity_flags: request.ambiguity_flags.clone(),
        constraint_notes: plan.constraints.clone(),
        freeze_notes,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn derive_build_feature_slices(
    request: &RequestRecord,
    plan: &RequestPlan,
    route: &chatty_factory_core::RouteDecision,
    inputs: &chatty_factory_core::BuildSeedInputs,
) -> Vec<BuildFeatureSlice> {
    let selected_substrate_kind = route
        .selected_substrate_kind
        .clone()
        .or_else(|| plan.inferred_substrate_candidates.first().cloned());
    let substrate_seed_id = format!("{}:substrate-seed", plan.plan_id);
    let substrate_label = selected_substrate_kind
        .as_ref()
        .map(SubstrateKind::as_str)
        .unwrap_or("base_substrate");
    let seed_files = substrate_contract_paths(
        selected_substrate_kind.as_ref(),
        plan.inferred_tool_kind.as_deref(),
    )
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
    let mut slices = vec![BuildFeatureSlice {
        slice_id: substrate_seed_id.clone(),
        slice_kind: "substrate_seed".into(),
        title: "substrate seed".into(),
        summary: format!(
            "seed `{}` as a stable substrate for `{}` before feature-specific build work",
            substrate_label, inputs.project_name
        ),
        why_it_exists: "establish the smallest governed substrate with contract files, acceptance baseline, and ecosystem compatibility surfaces before layering feature behavior".into(),
        requested_capabilities: request.requested_capabilities.clone(),
        planner_suggested_features: plan.planner_suggested_features.clone(),
        execution_steps: plan.execution_steps.clone(),
        acceptance_targets: acceptance_targets_for_build_plan(plan),
        files_to_create: seed_files,
        files_to_update: Vec::new(),
        expected_symbols: vec![format!("substrate:{}", substrate_label)],
        acceptance_markers: plan.planner_required_markers.clone(),
        dependencies: Vec::new(),
    }];
    let feature_target_files = default_feature_target_files(
        selected_substrate_kind.as_ref(),
        plan.inferred_tool_kind.as_deref(),
    );
    let requested_features = normalized_feature_slice_inputs(request, plan, inputs);
    for (index, feature_name) in requested_features.into_iter().enumerate() {
        slices.push(BuildFeatureSlice {
            slice_id: format!("{}:feature-{}", plan.plan_id, index + 1),
            slice_kind: "feature_layer".into(),
            title: feature_name.replace('_', " "),
            summary: format!(
                "layer requested feature `{}` onto substrate `{}` using host-reviewed file targets",
                feature_name, substrate_label
            ),
            why_it_exists: "translate user-requested behavior into a bounded feature slice that can later be reviewed, constrained, and executed without expanding legacy compatibility catalogs".into(),
            requested_capabilities: vec![feature_name.clone()],
            planner_suggested_features: plan.planner_suggested_features.clone(),
            execution_steps: vec![
                format!("refine `{}` into concrete file updates on the selected substrate seed", feature_name),
                "review anchors, ownership boundaries, and syntax-sensitive surfaces before applying code".into(),
                "sync acceptance-critical contracts after feature insertion".into(),
            ],
            acceptance_targets: acceptance_targets_for_build_plan(plan),
            files_to_create: Vec::new(),
            files_to_update: feature_target_files.clone(),
            expected_symbols: vec![format!("feature:{}", feature_name)],
            acceptance_markers: plan.planner_required_markers.clone(),
            dependencies: vec![substrate_seed_id.clone()],
        });
    }
    slices
}

fn acceptance_targets_for_build_plan(plan: &RequestPlan) -> Vec<String> {
    let mut targets = Vec::new();
    targets.extend(plan.planner_expected_outputs.clone());
    targets.extend(plan.planner_required_markers.clone());
    targets.extend(plan.planner_acceptance_checks.iter().map(|check| {
        format!(
            "{}:{}:{}",
            check.kind,
            check.target,
            check.expected.clone().unwrap_or_default()
        )
    }));
    targets.sort();
    targets.dedup();
    targets
}

fn planned_file_operations_for_build(
    substrate_kind: Option<&SubstrateKind>,
    tool_kind: Option<&str>,
    feature_slices: &[BuildFeatureSlice],
) -> Vec<PlannedFileOperation> {
    let mut paths = match (substrate_kind, tool_kind) {
        (Some(SubstrateKind::Cli), Some("rust_cli")) => vec![
            "Cargo.toml",
            "src/main.rs",
            "README.md",
            "ProjectSpec.json",
            "AcceptancePlan.json",
        ],
        (Some(SubstrateKind::Cli), Some("python_cli")) => vec![
            "main.py",
            "README.md",
            "ProjectSpec.json",
            "AcceptancePlan.json",
        ],
        _ => vec![
            "index.html",
            "app.js",
            "styles.css",
            "README.md",
            "ProjectSpec.json",
            "AcceptancePlan.json",
        ],
    };
    paths.sort();
    let mut operations = paths
        .into_iter()
        .enumerate()
        .map(|(index, path)| PlannedFileOperation {
            operation_id: format!("substrate-file-{}", index + 1),
            path: path.into(),
            operation_kind: "emit_or_refresh".into(),
            rationale:
                "legacy substrate contract file expected during deterministic build emission"
                    .into(),
            source: "substrate_contract".into(),
            content_source: "substrate_renderer".into(),
            target_anchor: None,
            ownership_boundary: "substrate_contract_boundary".into(),
            syntax_sensitive: path.ends_with(".rs")
                || path.ends_with(".py")
                || path.ends_with(".js")
                || path.ends_with(".html")
                || path.ends_with(".css"),
        })
        .collect::<Vec<_>>();

    for slice in feature_slices {
        if slice.slice_kind != "feature_layer" {
            continue;
        }
        for (index, path) in slice.files_to_update.iter().enumerate() {
            operations.push(PlannedFileOperation {
                operation_id: format!("{}:update-{}", slice.slice_id, index + 1),
                path: path.clone(),
                operation_kind: feature_operation_kind_for_path(path).into(),
                rationale: format!(
                    "feature slice `{}` would extend this file as bounded post-seed work",
                    slice.title
                ),
                source: "build_feature_slice".into(),
                content_source: "future_host_execution_helper".into(),
                target_anchor: feature_target_anchor_for_path(path).map(str::to_string),
                ownership_boundary: feature_ownership_boundary_for_path(path).into(),
                syntax_sensitive: is_syntax_sensitive_path(path),
            });
        }
        for (index, path) in slice.files_to_create.iter().enumerate() {
            if operations.iter().any(|operation| operation.path == *path) {
                continue;
            }
            operations.push(PlannedFileOperation {
                operation_id: format!("{}:create-{}", slice.slice_id, index + 1),
                path: path.clone(),
                operation_kind: "create_feature_file_candidate".into(),
                rationale: format!(
                    "feature slice `{}` may require a dedicated file beyond the seeded substrate",
                    slice.title
                ),
                source: "build_feature_slice".into(),
                content_source: "future_host_execution_helper".into(),
                target_anchor: None,
                ownership_boundary: feature_ownership_boundary_for_path(path).into(),
                syntax_sensitive: is_syntax_sensitive_path(path),
            });
        }
    }

    operations
}

fn review_build_plan_artifact(
    build_plan: &BuildPlanArtifact,
) -> (BuildPlanReview, BuildPlanArtifact) {
    let mut reviewed = build_plan.clone();
    let mut findings = Vec::new();
    let blocked_reasons = Vec::new();
    let original_feature_slice_count = reviewed.feature_slices.len();
    let original_file_operation_count = reviewed.planned_file_operations.len();
    let mut dropped_feature_slice_ids = Vec::new();
    let substrate_capabilities = seeded_substrate_capabilities(
        reviewed.substrate_kind.as_ref(),
        build_plan.tool_kind.as_deref(),
    );

    reviewed.feature_slices = reviewed
        .feature_slices
        .into_iter()
        .filter(|slice| {
            if slice.slice_kind != "feature_layer" {
                return true;
            }
            let removable = !slice.requested_capabilities.is_empty()
                && slice
                    .requested_capabilities
                    .iter()
                    .all(|capability| substrate_capabilities.iter().any(|known| known == capability));
            if removable {
                dropped_feature_slice_ids.push(slice.slice_id.clone());
                findings.push(format!(
                    "self-review removed substrate-identity feature slice `{}` because the selected substrate already provides: {}",
                    slice.slice_id,
                    slice.requested_capabilities.join(", ")
                ));
                false
            } else {
                true
            }
        })
        .collect();

    reviewed.planned_file_operations = reviewed
        .planned_file_operations
        .into_iter()
        .filter(|operation| {
            let belongs_to_dropped_slice = dropped_feature_slice_ids
                .iter()
                .any(|slice_id| operation.operation_id.starts_with(&format!("{slice_id}:")));
            !belongs_to_dropped_slice
        })
        .collect();

    let dropped_file_operation_ids = build_plan
        .planned_file_operations
        .iter()
        .filter(|operation| {
            dropped_feature_slice_ids
                .iter()
                .any(|slice_id| operation.operation_id.starts_with(&format!("{slice_id}:")))
        })
        .map(|operation| operation.operation_id.clone())
        .collect::<Vec<_>>();

    let decision = if dropped_feature_slice_ids.is_empty() {
        "proceed_with_original_plan"
    } else {
        "proceed_with_refined_plan"
    };

    let review = BuildPlanReview {
        review_id: chatty_factory_core::timestamp_id("build-plan-review"),
        request_id: build_plan.request_id.clone(),
        build_intent_freeze_id: build_plan.source_build_intent_freeze_id.clone(),
        source_build_plan_id: build_plan.build_plan_id.clone(),
        project_name: build_plan.project_name.clone(),
        substrate_kind: build_plan.substrate_kind.clone(),
        decision: decision.into(),
        original_feature_slice_count,
        reviewed_feature_slice_count: reviewed.feature_slices.len(),
        dropped_feature_slice_ids,
        original_file_operation_count,
        reviewed_file_operation_count: reviewed.planned_file_operations.len(),
        dropped_file_operation_ids,
        findings,
        blocked_reasons,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };

    (review, reviewed)
}

fn review_build_plan_constraints(
    build_plan: &BuildPlanArtifact,
    plan_review: &BuildPlanReview,
) -> BuildConstraintReviewReceipt {
    let selected_constraints = Vec::new();
    let violations = Vec::new();
    let blocked_methods = Vec::new();
    let recommended_replacements = Vec::new();
    let mut findings = Vec::new();

    if build_plan
        .feature_slices
        .iter()
        .all(|slice| slice.slice_kind == "substrate_seed")
    {
        findings.push(
            "constraint review found no remaining feature-layer work beyond the seeded substrate; the current plan is compatibility-seed only".into(),
        );
    } else if plan_review.decision == "proceed_with_refined_plan" {
        findings.push(
            "constraint review accepted the self-reviewed seeded-substrate-plus-feature plan after substrate-only feature slices were removed".into(),
        );
    } else {
        findings.push(
            "constraint review found no active forbidden build methods for the reviewed seeded-substrate-plus-feature plan".into(),
        );
    }

    BuildConstraintReviewReceipt {
        review_id: chatty_factory_core::timestamp_id("build-constraint-review"),
        request_id: build_plan.request_id.clone(),
        build_plan_id: build_plan.build_plan_id.clone(),
        project_name: build_plan.project_name.clone(),
        substrate_kind: build_plan.substrate_kind.clone(),
        tool_kind: build_plan.tool_kind.clone(),
        review_subject: "build_plan_execution".into(),
        selected_constraints,
        violations,
        blocked_methods,
        recommended_replacements,
        decision: "allow_current_plan".into(),
        findings,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn derive_build_execution_work_order(
    build_plan: &BuildPlanArtifact,
    plan_review: &BuildPlanReview,
    constraint_review: &BuildConstraintReviewReceipt,
) -> BuildExecutionWorkOrder {
    let surviving_feature_slice_ids = build_plan
        .feature_slices
        .iter()
        .filter(|slice| slice.slice_kind == "feature_layer")
        .map(|slice| slice.slice_id.clone())
        .collect::<Vec<_>>();
    let surviving_feature_capabilities = build_plan
        .feature_slices
        .iter()
        .filter(|slice| slice.slice_kind == "feature_layer")
        .flat_map(|slice| slice.requested_capabilities.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let mut findings = Vec::new();
    findings.extend(plan_review.findings.clone());
    findings.extend(constraint_review.findings.clone());
    BuildExecutionWorkOrder {
        work_order_id: chatty_factory_core::timestamp_id("build-work-order"),
        request_id: build_plan.request_id.clone(),
        build_intent_freeze_id: build_plan.source_build_intent_freeze_id.clone(),
        build_plan_id: build_plan.build_plan_id.clone(),
        build_plan_review_id: plan_review.review_id.clone(),
        build_constraint_review_id: constraint_review.review_id.clone(),
        project_name: build_plan.project_name.clone(),
        substrate_kind: build_plan.substrate_kind.clone(),
        tool_kind: build_plan.tool_kind.clone(),
        decision: if constraint_review.decision == "allow_current_plan" {
            "ready_for_future_host_execution_helpers".into()
        } else {
            constraint_review.decision.clone()
        },
        feature_slice_ids: surviving_feature_slice_ids,
        feature_capabilities: surviving_feature_capabilities,
        operations: build_plan.planned_file_operations.clone(),
        findings,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn derive_plan_task_list(
    runtime_root: &Path,
    build_plan: &BuildPlanArtifact,
    plan_review: &BuildPlanReview,
    constraint_review: &BuildConstraintReviewReceipt,
    work_order: &BuildExecutionWorkOrder,
) -> PlanTaskList {
    let feature_slice_map = build_plan
        .feature_slices
        .iter()
        .map(|slice| (slice.slice_id.clone(), slice))
        .collect::<BTreeMap<_, _>>();
    let mut tasks = Vec::new();
    let toolbar_decomposition_enabled =
        has_decomposition_rule_for_task_subtype(runtime_root, "toolbar_ui_block");
    let toolbar_label_decomposition_enabled =
        has_decomposition_rule_for_task_subtype(runtime_root, "toolbar_label_sentence");
    let metric_card_decomposition_enabled =
        has_decomposition_rule_for_task_subtype(runtime_root, "metric_card_block");
    let metric_card_context_decomposition_enabled =
        has_decomposition_rule_for_task_subtype(runtime_root, "metric_card_context_sentence");

    for slice_id in &work_order.feature_slice_ids {
        let Some(slice) = feature_slice_map.get(slice_id) else {
            continue;
        };

        let sync_operations = work_order
            .operations
            .iter()
            .filter(|operation| {
                operation.operation_id.starts_with(&format!("{slice_id}:"))
                    && matches!(
                        operation.operation_kind.as_str(),
                        "sync_contract_candidate" | "sync_docs_candidate"
                    )
            })
            .cloned()
            .collect::<Vec<_>>();
        if !sync_operations.is_empty() {
            let target_files = sync_operations
                .iter()
                .map(|operation| operation.path.clone())
                .collect::<Vec<_>>();
            let allowed_boundaries = sync_operations
                .iter()
                .map(|operation| operation.ownership_boundary.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            tasks.push(PlanTask {
                task_id: format!("{slice_id}:host-sync"),
                request_id: build_plan.request_id.clone(),
                source_build_plan_id: build_plan.build_plan_id.clone(),
                source_work_order_id: work_order.work_order_id.clone(),
                task_kind: "host_sync".into(),
                task_title: format!("sync reviewed metadata for {}", slice.title),
                task_summary: format!(
                    "host-sync contract and docs files for feature slice `{}`",
                    slice.title
                ),
                dependencies: slice.dependencies.clone(),
                target_files,
                allowed_boundaries,
                expected_symbols: slice.expected_symbols.clone(),
                expected_markers: slice.acceptance_markers.clone(),
                verification_steps: vec![
                    "project_spec_sync".into(),
                    "acceptance_plan_sync".into(),
                    "readme_sync".into(),
                ],
                replacement_guidance: None,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            });
        }

        let mechanical_operations = work_order
            .operations
            .iter()
            .filter(|operation| {
                operation.operation_id.starts_with(&format!("{slice_id}:"))
                    && operation.operation_kind == "insert_feature_block_candidate"
            })
            .cloned()
            .collect::<Vec<_>>();
        if !mechanical_operations.is_empty() {
            let target_files = mechanical_operations
                .iter()
                .map(|operation| operation.path.clone())
                .collect::<Vec<_>>();
            let allowed_boundaries = mechanical_operations
                .iter()
                .map(|operation| operation.ownership_boundary.clone())
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            tasks.push(PlanTask {
                task_id: format!("{slice_id}:host-mechanical"),
                request_id: build_plan.request_id.clone(),
                source_build_plan_id: build_plan.build_plan_id.clone(),
                source_work_order_id: work_order.work_order_id.clone(),
                task_kind: "host_mechanical".into(),
                task_title: format!("prepare bounded feature insertion for {}", slice.title),
                task_summary: format!(
                    "host-mechanical anchor-scoped insertion candidate for feature slice `{}`",
                    slice.title
                ),
                dependencies: vec![format!("{slice_id}:host-sync")],
                target_files,
                allowed_boundaries,
                expected_symbols: slice.expected_symbols.clone(),
                expected_markers: slice.acceptance_markers.clone(),
                verification_steps: vec![
                    "anchor_review".into(),
                    "syntax_boundary_check".into(),
                ],
                replacement_guidance: Some(
                    "convert this candidate into a concrete bounded helper or keep it as a model-authored microtask if the host still lacks a safe insertion method".into(),
                ),
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            });
        }

        let uses_metric_card_feature = slice
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:metric_card");
        let uses_toolbar_feature = slice
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:action_toolbar");
        if uses_metric_card_feature && metric_card_decomposition_enabled {
            for (suffix, symbol, title_hint, summary_hint) in [
                (
                    "title-literal",
                    "feature:metric_card_title_literal",
                    "author metric card title",
                    "decomposed model-authored microtask for the metric card title field",
                ),
                (
                    "value-line",
                    "feature:metric_card_value_line",
                    "author metric card value line",
                    "decomposed model-authored microtask for the metric card value field",
                ),
                (
                    "context-sentence",
                    "feature:metric_card_context_sentence",
                    "author metric card context sentence",
                    "decomposed model-authored microtask for the metric card context field",
                ),
            ] {
                if suffix == "context-sentence" && metric_card_context_decomposition_enabled {
                    continue;
                }
                tasks.push(PlanTask {
                    task_id: format!("{slice_id}:model-authored:{suffix}"),
                    request_id: build_plan.request_id.clone(),
                    source_build_plan_id: build_plan.build_plan_id.clone(),
                    source_work_order_id: work_order.work_order_id.clone(),
                    task_kind: "model_authored".into(),
                    task_title: format!("{title_hint} for {}", slice.title),
                    task_summary: format!("{summary_hint} `{}`", slice.title),
                    dependencies: vec![format!("{slice_id}:host-sync")],
                    target_files: slice.files_to_update.clone(),
                    allowed_boundaries: vec!["bounded_feature_slice_boundary".into()],
                    expected_symbols: vec![symbol.into()],
                    expected_markers: slice.acceptance_markers.clone(),
                    verification_steps: vec![
                        "json_or_parse".into(),
                        "cargo_check_or_runtime_equivalent".into(),
                        "acceptance_reverify".into(),
                    ],
                    replacement_guidance: Some(
                        "earned semantic-object field split applied: ask the model for one metric card field at a time; the host composes and renders the final card".into(),
                    ),
                    created_at: Some(chatty_factory_core::timestamp_id("created")),
                });
            }
            if metric_card_context_decomposition_enabled {
                for (suffix, symbol, title_hint, summary_hint) in [
                    (
                        "context-subject-clause",
                        "feature:metric_card_context_clause_subject",
                        "author metric card context subject clause",
                        "decomposed model-authored microtask for the subject fragment behind the metric card context sentence",
                    ),
                    (
                        "context-purpose-clause",
                        "feature:metric_card_context_clause_purpose",
                        "author metric card context purpose clause",
                        "decomposed model-authored microtask for the purpose fragment behind the metric card context sentence",
                    ),
                ] {
                    tasks.push(PlanTask {
                        task_id: format!("{slice_id}:model-authored:{suffix}"),
                        request_id: build_plan.request_id.clone(),
                        source_build_plan_id: build_plan.build_plan_id.clone(),
                        source_work_order_id: work_order.work_order_id.clone(),
                        task_kind: "model_authored".into(),
                        task_title: format!("{title_hint} for {}", slice.title),
                        task_summary: format!("{summary_hint} `{}`", slice.title),
                        dependencies: vec![format!("{slice_id}:host-sync")],
                        target_files: slice.files_to_update.clone(),
                        allowed_boundaries: vec!["bounded_feature_slice_boundary".into()],
                        expected_symbols: vec![symbol.into()],
                        expected_markers: slice.acceptance_markers.clone(),
                        verification_steps: vec![
                            "json_or_parse".into(),
                            "cargo_check_or_runtime_equivalent".into(),
                            "acceptance_reverify".into(),
                        ],
                        replacement_guidance: Some(
                            "earned sentence grammar applied: ask the model for one context fragment at a time; the host composes the final context sentence and metric card block".into(),
                        ),
                        created_at: Some(chatty_factory_core::timestamp_id("created")),
                    });
                }
            }
        } else if uses_toolbar_feature && toolbar_decomposition_enabled {
            if toolbar_label_decomposition_enabled {
                for (suffix, symbol, title_hint, summary_hint) in [
                    (
                        "clause-run-action",
                        "feature:action_toolbar_label_clause_run_action",
                        "author toolbar run-action clause",
                        "decomposed model-authored microtask for the run-action clause behind the action toolbar label",
                    ),
                    (
                        "clause-clear-action",
                        "feature:action_toolbar_label_clause_clear_action",
                        "author toolbar clear-action clause",
                        "decomposed model-authored microtask for the clear-action clause behind the action toolbar label",
                    ),
                ] {
                    tasks.push(PlanTask {
                        task_id: format!("{slice_id}:model-authored:{suffix}"),
                        request_id: build_plan.request_id.clone(),
                        source_build_plan_id: build_plan.build_plan_id.clone(),
                        source_work_order_id: work_order.work_order_id.clone(),
                        task_kind: "model_authored".into(),
                        task_title: format!("{title_hint} for {}", slice.title),
                        task_summary: format!("{summary_hint} `{}`", slice.title),
                        dependencies: vec![format!("{slice_id}:host-sync")],
                        target_files: slice.files_to_update.clone(),
                        allowed_boundaries: vec!["bounded_feature_slice_boundary".into()],
                        expected_symbols: vec![symbol.into()],
                        expected_markers: slice.acceptance_markers.clone(),
                        verification_steps: vec![
                            "json_or_parse".into(),
                            "cargo_check_or_runtime_equivalent".into(),
                            "acceptance_reverify".into(),
                        ],
                        replacement_guidance: Some(
                            "earned decomposition rule applied again: ask the model only for one clause at a time; the host composes the final toolbar sentence and Rust block".into(),
                        ),
                        created_at: Some(chatty_factory_core::timestamp_id("created")),
                    });
                }
            } else {
                tasks.push(PlanTask {
                    task_id: format!("{slice_id}:model-authored:label-sentence"),
                    request_id: build_plan.request_id.clone(),
                    source_build_plan_id: build_plan.build_plan_id.clone(),
                    source_work_order_id: work_order.work_order_id.clone(),
                    task_kind: "model_authored".into(),
                    task_title: format!("author toolbar label sentence for {}", slice.title),
                    task_summary: format!(
                        "decomposed model-authored microtask for the explanatory label behind feature slice `{}`",
                        slice.title
                    ),
                    dependencies: vec![format!("{slice_id}:host-sync")],
                    target_files: slice.files_to_update.clone(),
                    allowed_boundaries: vec!["bounded_feature_slice_boundary".into()],
                    expected_symbols: vec!["feature:action_toolbar_label_sentence".into()],
                    expected_markers: slice.acceptance_markers.clone(),
                    verification_steps: vec![
                        "json_or_parse".into(),
                        "cargo_check_or_runtime_equivalent".into(),
                        "acceptance_reverify".into(),
                    ],
                    replacement_guidance: Some(
                        "earned decomposition rule applied: ask the model only for the toolbar label sentence; the host owns literals and final Rust rendering".into(),
                    ),
                    created_at: Some(chatty_factory_core::timestamp_id("created")),
                });
            }
        } else {
            tasks.push(PlanTask {
                task_id: format!("{slice_id}:model-authored"),
                request_id: build_plan.request_id.clone(),
                source_build_plan_id: build_plan.build_plan_id.clone(),
                source_work_order_id: work_order.work_order_id.clone(),
                task_kind: "model_authored".into(),
                task_title: format!("author feature behavior for {}", slice.title),
                task_summary: format!(
                    "model-authored microtask for the actual code behavior behind feature slice `{}`",
                    slice.title
                ),
                dependencies: vec![format!("{slice_id}:host-sync")],
                target_files: slice.files_to_update.clone(),
                allowed_boundaries: vec!["bounded_feature_slice_boundary".into()],
                expected_symbols: slice.expected_symbols.clone(),
                expected_markers: slice.acceptance_markers.clone(),
                verification_steps: vec![
                    "syntax_or_parse".into(),
                    "cargo_check_or_runtime_equivalent".into(),
                    "acceptance_reverify".into(),
                ],
                replacement_guidance: Some(
                    "keep scope to one small feature slice at a time; do not rewrite whole seeded substrate files".into(),
                ),
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            });
        }
    }

    let mut findings = Vec::new();
    findings.extend(plan_review.findings.clone());
    findings.extend(constraint_review.findings.clone());
    if metric_card_decomposition_enabled {
        findings.push(
            "applied earned decomposition rule for `metric_card_block`, replacing the broad metric card task with field-level child tasks".into(),
        );
    }
    if metric_card_context_decomposition_enabled {
        findings.push(
            "applied earned decomposition rule for `metric_card_context_sentence`, replacing the broad sentence child with clause-level context fragments".into(),
        );
    }
    if toolbar_decomposition_enabled {
        if toolbar_label_decomposition_enabled {
            findings.push(
                "applied earned decomposition rules for `toolbar_ui_block` and `toolbar_label_sentence`, replacing the broad toolbar task with clause-level child tasks".into(),
            );
        } else {
            findings.push(
                "applied earned decomposition rule for `toolbar_ui_block` and replaced the broad toolbar task with a decomposed label-sentence task".into(),
            );
        }
    }
    findings.push(format!(
        "derived {} task(s) from reviewed build work order",
        tasks.len()
    ));

    PlanTaskList {
        task_list_id: chatty_factory_core::timestamp_id("plan-task-list"),
        request_id: build_plan.request_id.clone(),
        build_plan_id: build_plan.build_plan_id.clone(),
        build_plan_review_id: plan_review.review_id.clone(),
        build_constraint_review_id: constraint_review.review_id.clone(),
        build_work_order_id: work_order.work_order_id.clone(),
        project_name: build_plan.project_name.clone(),
        substrate_kind: build_plan.substrate_kind.clone(),
        tool_kind: build_plan.tool_kind.clone(),
        tasks,
        findings,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

