#[derive(Debug, Clone, Default)]
struct TaskAttemptOutcome {
    status: String,
    touched_files: Vec<String>,
    findings: Vec<String>,
}

#[derive(Debug, Clone, Default, Deserialize)]
struct ActionToolbarSemanticDraft {
    title: String,
    label: String,
    primary_button: String,
    secondary_button: String,
}

#[derive(Debug, Clone, Default, Deserialize)]
struct ActionToolbarLabelDraft {
    label: String,
}

#[derive(Debug, Clone, Default, Deserialize)]
struct MetricCardSemanticDraft {
    title: String,
    value: String,
    context: String,
}

#[derive(Debug, Clone, Default, Deserialize, Serialize)]
struct MetricCardFieldDraft {
    value: String,
}

#[derive(Debug, Clone, Default, Deserialize, Serialize)]
struct ActionToolbarClauseDraft {
    clause: String,
}

fn derive_plan_task_execution_log(
    task_list: &PlanTaskList,
    work_order_synced_files: &[String],
    attempted_outcomes: &BTreeMap<String, TaskAttemptOutcome>,
) -> PlanTaskExecutionLog {
    let synced_file_set = work_order_synced_files
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let receipts = task_list
        .tasks
        .iter()
        .map(|task| {
            if let Some(outcome) = attempted_outcomes.get(&task.task_id) {
                return PlanTaskExecutionReceipt {
                    receipt_id: chatty_factory_core::timestamp_id("task-execution"),
                    request_id: task.request_id.clone(),
                    task_id: task.task_id.clone(),
                    task_kind: task.task_kind.clone(),
                    status: outcome.status.clone(),
                    touched_files: outcome.touched_files.clone(),
                    findings: outcome.findings.clone(),
                    created_at: Some(chatty_factory_core::timestamp_id("created")),
                };
            }
            let touched_files = task
                .target_files
                .iter()
                .filter(|path| synced_file_set.contains(*path))
                .cloned()
                .collect::<Vec<_>>();
            let (status, findings) = if task.task_kind == "host_sync" {
                if touched_files.is_empty() {
                    (
                        "no_change_needed".to_string(),
                        vec![
                            "host sync task was attempted but target files were already aligned"
                                .into(),
                        ],
                    )
                } else {
                    (
                        "executed".to_string(),
                        vec![format!(
                            "host sync task updated: {}",
                            touched_files.join(", ")
                        )],
                    )
                }
            } else {
                (
                    "pending_not_attempted".to_string(),
                    vec!["task is frozen but has not been attempted in this build slice".into()],
                )
            };
            PlanTaskExecutionReceipt {
                receipt_id: chatty_factory_core::timestamp_id("task-execution"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                task_kind: task.task_kind.clone(),
                status,
                touched_files,
                findings,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            }
        })
        .collect::<Vec<_>>();
    let decision = if receipts.iter().any(|receipt| receipt.status == "executed") {
        "host_sync_executed_with_pending_followups"
    } else {
        "no_host_task_changes_with_pending_followups"
    };
    PlanTaskExecutionLog {
        log_id: chatty_factory_core::timestamp_id("task-execution-log"),
        request_id: task_list.request_id.clone(),
        task_list_id: task_list.task_list_id.clone(),
        decision: decision.into(),
        receipts,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn persist_plan_task_execution_log(
    runtime_root: &Path,
    log: &PlanTaskExecutionLog,
) -> Result<PathBuf> {
    let path = runtime_root
        .join("task_execution_receipts")
        .join(format!("{}-task-execution.json", log.request_id));
    persist_json_pretty(&path, log)?;
    Ok(path)
}

fn derive_plan_task_verification_log(
    task_list: &PlanTaskList,
    execution_log: &PlanTaskExecutionLog,
    execution_status: &str,
) -> PlanTaskVerificationLog {
    let execution_by_task = execution_log
        .receipts
        .iter()
        .map(|receipt| (receipt.task_id.clone(), receipt))
        .collect::<BTreeMap<_, _>>();
    let receipts = task_list
        .tasks
        .iter()
        .map(|task| {
            let execution_receipt = execution_by_task.get(&task.task_id);
            let execution_status_value = execution_receipt
                .map(|receipt| receipt.status.as_str())
                .unwrap_or("pending_not_attempted");
            let (status, findings) = if matches!(execution_status_value, "executed" | "no_change_needed")
            {
                (
                    "verified_current_slice".to_string(),
                    vec![format!(
                        "verification acknowledged current build slice after `{}` task status `{}` and execution smoke `{}`",
                        task.task_kind, execution_status_value, execution_status
                    )],
                )
            } else {
                (
                    "pending_not_attempted".to_string(),
                    vec!["verification deferred because the task has not been attempted yet".into()],
                )
            };
            PlanTaskVerificationReceipt {
                receipt_id: chatty_factory_core::timestamp_id("task-verification"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                status,
                verification_steps: task.verification_steps.clone(),
                findings,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            }
        })
        .collect::<Vec<_>>();
    let decision = if receipts
        .iter()
        .any(|receipt| receipt.status == "verified_current_slice")
    {
        "current_slice_verified_with_pending_followups"
    } else {
        "verification_deferred_pending_task_attempts"
    };
    PlanTaskVerificationLog {
        log_id: chatty_factory_core::timestamp_id("task-verification-log"),
        request_id: task_list.request_id.clone(),
        task_list_id: task_list.task_list_id.clone(),
        decision: decision.into(),
        receipts,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn persist_plan_task_verification_log(
    runtime_root: &Path,
    log: &PlanTaskVerificationLog,
) -> Result<PathBuf> {
    let path = runtime_root
        .join("task_verification_receipts")
        .join(format!("{}-task-verification.json", log.request_id));
    persist_json_pretty(&path, log)?;
    Ok(path)
}

fn execute_first_host_mechanical_microtasks(
    project_dir: &Path,
    task_list: &PlanTaskList,
) -> Result<BTreeMap<String, TaskAttemptOutcome>> {
    let mut outcomes = BTreeMap::new();
    for task in &task_list.tasks {
        if task.task_kind != "host_mechanical" {
            continue;
        }
        if task
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:status_panel")
        {
            outcomes.insert(
                task.task_id.clone(),
                attempt_native_status_panel_microtask(project_dir, task)?,
            );
        } else if task
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:kanban_board")
        {
            outcomes.insert(
                task.task_id.clone(),
                attempt_static_web_kanban_board_microtask(project_dir, task)?,
            );
        }
    }
    Ok(outcomes)
}

fn attempt_native_status_panel_microtask(
    project_dir: &Path,
    task: &PlanTask,
) -> Result<TaskAttemptOutcome> {
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
    else {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical status panel task stayed pending because no Rust entrypoint target file was declared"
                    .into(),
            ],
        });
    };

    let path = project_dir.join(target_file);
    let original = fs::read_to_string(&path)?;
    let start_marker = "            // chattyfactory:feature:status_panel:start";
    let end_marker = "            // chattyfactory:feature:status_panel:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        return Ok(TaskAttemptOutcome {
            status: "no_change_needed".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical status panel task found the bounded feature block already present"
                    .into(),
            ],
        });
    }

    let anchor = "            // native_window_feature_patch_anchor";
    if !original.contains(anchor) {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical status panel task stayed pending because the native window feature anchor was not present"
                    .into(),
            ],
        });
    }

    let block = [
        "            // chattyfactory:feature:status_panel:start",
        "            ui.add_space(8.0);",
        "            ui.group(|ui| {",
        "                ui.strong(\"Status panel\");",
        "                ui.label(\"Shared room state and hosted event lanes are ready for feature-specific wiring.\");",
        "            });",
        "            // chattyfactory:feature:status_panel:end",
        "",
        "            // native_window_feature_patch_anchor",
    ]
    .join("\n");
    let updated = original.replacen(anchor, &block, 1);
    if updated == original {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical status panel task could not narrow the insertion to a single anchored update"
                    .into(),
            ],
        });
    }

    fs::write(&path, updated)?;
    Ok(TaskAttemptOutcome {
        status: "executed".into(),
        touched_files: vec![target_file.clone()],
        findings: vec![
            "host-mechanical status panel task inserted a bounded feature block at the native window starter anchor"
                .into(),
        ],
    })
}

fn attempt_static_web_kanban_board_microtask(
    project_dir: &Path,
    task: &PlanTask,
) -> Result<TaskAttemptOutcome> {
    let has_index = task.target_files.iter().any(|path| path == "index.html");
    let has_app = task.target_files.iter().any(|path| path == "app.js");
    let has_styles = task.target_files.iter().any(|path| path == "styles.css");
    if !(has_index && has_app && has_styles) {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical kanban board task stayed pending because one or more static web target files were missing"
                    .into(),
            ],
        });
    }

    let index_path = project_dir.join("index.html");
    let app_path = project_dir.join("app.js");
    let styles_path = project_dir.join("styles.css");
    let index_original = fs::read_to_string(&index_path)?;
    let app_original = fs::read_to_string(&app_path)?;
    let styles_original = fs::read_to_string(&styles_path)?;

    let index_marker = "data-feature=\"kanban-board\"";
    let app_marker = "const kanbanState = {";
    let style_marker = ".kanban-board {";
    if index_original.contains(index_marker)
        && app_original.contains(app_marker)
        && styles_original.contains(style_marker)
    {
        return Ok(TaskAttemptOutcome {
            status: "no_change_needed".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical kanban board task found the bounded feature block already present"
                    .into(),
            ],
        });
    }

    let results_anchor = "<section class=\"panel results-panel\">";
    if !index_original.contains(results_anchor) {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical kanban board task stayed pending because the static dashboard results anchor was not present"
                    .into(),
            ],
        });
    }
    let index_insert = [
        "",
        "    <!-- chattyfactory:feature:kanban_board:start -->",
        "    <section class=\"panel kanban-board\" data-feature=\"kanban-board\">",
        "      <div class=\"kanban-board__header\">",
        "        <div>",
        "          <h2>Kanban Board</h2>",
        "          <p class=\"kanban-board__summary\">Drag task cards between lanes to reshape the work queue.</p>",
        "        </div>",
        "      </div>",
        "      <div class=\"kanban-columns\">",
        "        <section class=\"kanban-column\" data-lane=\"todo\">",
        "          <h3>To do</h3>",
        "          <div class=\"kanban-column__body\" id=\"kanban-todo\"></div>",
        "        </section>",
        "        <section class=\"kanban-column\" data-lane=\"in_progress\">",
        "          <h3>In progress</h3>",
        "          <div class=\"kanban-column__body\" id=\"kanban-in-progress\"></div>",
        "        </section>",
        "        <section class=\"kanban-column\" data-lane=\"done\">",
        "          <h3>Done</h3>",
        "          <div class=\"kanban-column__body\" id=\"kanban-done\"></div>",
        "        </section>",
        "      </div>",
        "    </section>",
        "    <!-- chattyfactory:feature:kanban_board:end -->",
    ]
    .join("\n");
    let index_updated = index_original.replacen(
        results_anchor,
        &format!("{index_insert}\n{results_anchor}"),
        1,
    );

    let app_anchor = "render(\"Dashboard build loaded.\");";
    if !app_original.contains(app_anchor) {
        return Ok(TaskAttemptOutcome {
            status: "pending_not_attempted".into(),
            touched_files: Vec::new(),
            findings: vec![
                "host-mechanical kanban board task stayed pending because the static dashboard script anchor was not present"
                    .into(),
            ],
        });
    }
    let app_insert = [
        "",
        "const kanbanState = {",
        "  todo: [",
        "    { id: \"task-contract\", label: \"Freeze the request interpretation\" },",
        "    { id: \"task-plan\", label: \"Break the feature into bounded steps\" },",
        "  ],",
        "  in_progress: [",
        "    { id: \"task-ui\", label: \"Wire the patch substrate onto the dashboard\" },",
        "  ],",
        "  done: [",
        "    { id: \"task-proof\", label: \"Re-run acceptance after each bounded change\" },",
        "  ],",
        "};",
        "",
        "function renderKanbanBoard() {",
        "  const laneMap = {",
        "    todo: document.getElementById(\"kanban-todo\"),",
        "    in_progress: document.getElementById(\"kanban-in-progress\"),",
        "    done: document.getElementById(\"kanban-done\"),",
        "  };",
        "  Object.entries(laneMap).forEach(([lane, container]) => {",
        "    if (!container) {",
        "      return;",
        "    }",
        "    container.innerHTML = \"\";",
        "    container.dataset.lane = lane;",
        "    container.addEventListener(\"dragover\", (event) => {",
        "      event.preventDefault();",
        "      container.classList.add(\"kanban-column__body--active\");",
        "    });",
        "    container.addEventListener(\"dragleave\", () => {",
        "      container.classList.remove(\"kanban-column__body--active\");",
        "    });",
        "    container.addEventListener(\"drop\", (event) => {",
        "      event.preventDefault();",
        "      container.classList.remove(\"kanban-column__body--active\");",
        "      const taskId = event.dataTransfer?.getData(\"text/plain\");",
        "      if (!taskId) {",
        "        return;",
        "      }",
        "      moveKanbanCard(taskId, lane);",
        "    });",
        "    for (const card of kanbanState[lane]) {",
        "      const element = document.createElement(\"button\");",
        "      element.type = \"button\";",
        "      element.className = \"kanban-card\";",
        "      element.draggable = true;",
        "      element.textContent = card.label;",
        "      element.dataset.cardId = card.id;",
        "      element.addEventListener(\"dragstart\", (event) => {",
        "        event.dataTransfer?.setData(\"text/plain\", card.id);",
        "      });",
        "      container.appendChild(element);",
        "    }",
        "  });",
        "}",
        "",
        "function moveKanbanCard(cardId, targetLane) {",
        "  let movedCard = null;",
        "  for (const lane of Object.keys(kanbanState)) {",
        "    const index = kanbanState[lane].findIndex((card) => card.id === cardId);",
        "    if (index !== -1) {",
        "      movedCard = kanbanState[lane].splice(index, 1)[0];",
        "      break;",
        "    }",
        "  }",
        "  if (!movedCard) {",
        "    return;",
        "  }",
        "  kanbanState[targetLane].push(movedCard);",
        "  renderKanbanBoard();",
        "  render(`Kanban update: ${movedCard.label} moved to ${targetLane.replace(\"_\", \" \")}.`);",
        "}",
        "",
        "renderKanbanBoard();",
    ]
    .join("\n");
    let app_updated =
        app_original.replacen(app_anchor, &format!("{app_insert}\n\n{app_anchor}"), 1);

    let styles_updated = if styles_original.contains(style_marker) {
        styles_original.clone()
    } else {
        format!(
            "{}\n{}\n",
            styles_original.trim_end(),
            [
                ".kanban-board {",
                "  border-style: solid;",
                "}",
                "",
                ".kanban-board__summary {",
                "  color: var(--muted);",
                "  margin-top: 0.35rem;",
                "}",
                "",
                ".kanban-columns {",
                "  display: grid;",
                "  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));",
                "  gap: 1rem;",
                "  margin-top: 1rem;",
                "}",
                "",
                ".kanban-column {",
                "  background: rgba(31, 42, 44, 0.04);",
                "  border: 1px solid rgba(31, 42, 44, 0.08);",
                "  border-radius: 16px;",
                "  padding: 0.9rem;",
                "}",
                "",
                ".kanban-column__body {",
                "  min-height: 180px;",
                "  display: flex;",
                "  flex-direction: column;",
                "  gap: 0.75rem;",
                "}",
                "",
                ".kanban-column__body--active {",
                "  outline: 2px dashed rgba(198, 93, 46, 0.45);",
                "  outline-offset: 6px;",
                "}",
                "",
                ".kanban-card {",
                "  width: 100%;",
                "  text-align: left;",
                "  border-radius: 14px;",
                "  background: #355c7d;",
                "  box-shadow: 0 12px 24px rgba(31, 42, 44, 0.12);",
                "}",
            ]
            .join("\n")
        )
    };

    fs::write(&index_path, index_updated)?;
    fs::write(&app_path, app_updated)?;
    fs::write(&styles_path, styles_updated)?;
    Ok(TaskAttemptOutcome {
        status: "executed".into(),
        touched_files: vec!["index.html".into(), "app.js".into(), "styles.css".into()],
        findings: vec![
            "host-mechanical kanban board task inserted a bounded static web kanban surface with drag-and-drop behavior"
                .into(),
        ],
    })
}

fn execute_first_model_authored_microtasks(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
) -> Result<(BTreeMap<String, TaskAttemptOutcome>, Vec<PathBuf>)> {
    let mut outcomes = BTreeMap::new();
    let mut receipt_paths = Vec::new();
    for task in &task_list.tasks {
        if task.task_kind != "model_authored" {
            continue;
        }
        if task
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:action_toolbar")
        {
            let (outcome, receipt_path) = attempt_native_action_toolbar_model_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        } else if task
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:action_toolbar_label_sentence")
        {
            let (outcome, receipt_path) = attempt_native_action_toolbar_label_sentence_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        } else if task.expected_symbols.iter().any(|symbol| {
            symbol == "feature:action_toolbar_label_clause_run_action"
                || symbol == "feature:action_toolbar_label_clause_clear_action"
        }) {
            let clause_kind = if task
                .expected_symbols
                .iter()
                .any(|symbol| symbol == "feature:action_toolbar_label_clause_run_action")
            {
                "run_action"
            } else {
                "clear_action"
            };
            let (outcome, receipt_path) = attempt_native_action_toolbar_label_clause_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
                clause_kind,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        } else if task.expected_symbols.iter().any(|symbol| {
            symbol == "feature:metric_card_title_literal"
                || symbol == "feature:metric_card_value_line"
                || symbol == "feature:metric_card_context_sentence"
        }) {
            let field_kind = if task
                .expected_symbols
                .iter()
                .any(|symbol| symbol == "feature:metric_card_title_literal")
            {
                "title"
            } else if task
                .expected_symbols
                .iter()
                .any(|symbol| symbol == "feature:metric_card_value_line")
            {
                "value"
            } else {
                "context"
            };
            let (outcome, receipt_path) = attempt_native_metric_card_field_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
                field_kind,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        } else if task.expected_symbols.iter().any(|symbol| {
            symbol == "feature:metric_card_context_clause_subject"
                || symbol == "feature:metric_card_context_clause_purpose"
        }) {
            let clause_kind = if task
                .expected_symbols
                .iter()
                .any(|symbol| symbol == "feature:metric_card_context_clause_subject")
            {
                "subject"
            } else {
                "purpose"
            };
            let (outcome, receipt_path) = attempt_native_metric_card_context_clause_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
                clause_kind,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        } else if task
            .expected_symbols
            .iter()
            .any(|symbol| symbol == "feature:metric_card")
        {
            let (outcome, receipt_path) = attempt_native_metric_card_model_microtask(
                runtime_root,
                workspace_root,
                project_dir,
                task,
                task_list,
                planner,
            )?;
            outcomes.insert(task.task_id.clone(), outcome);
            receipt_paths.push(receipt_path);
            let _learning_paths = maybe_persist_model_attempt_learning_artifacts(
                runtime_root,
                task,
                task_list,
                receipt_paths
                    .last()
                    .expect("attempt receipt path just pushed"),
            )?;
        }
    }
    Ok((outcomes, receipt_paths))
}

fn attempt_native_metric_card_model_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "model-authored metric card task stayed pending because no Rust entrypoint target file was declared"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored metric card task stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:metric_card:start";
    let end_marker = "            // chattyfactory:feature:metric_card:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![
                "model-authored metric card task found the bounded feature block already present"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored metric card task found the bounded feature block already present; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) =
        build_metric_card_model_prompts(task, task_list, &target_file, &anchor_context);
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "model-authored metric card task could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "model-authored metric card task stayed pending because local generation failed; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let initial_generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let retry_search = run_bounded_retry_search(
        &config,
        &catalog,
        task,
        &system_prompt,
        &user_prompt,
        &prompt_path,
        &raw_response_dir,
        &generation_receipt_root,
        planner.requested_model.as_deref(),
        parse_metric_card_model_draft(&raw_generated).unwrap_or_default(),
        review_metric_card_model_draft(
            &parse_metric_card_model_draft(&raw_generated).unwrap_or_default(),
        ),
        generation_receipt,
        initial_generation_receipt_path,
        |raw| parse_metric_card_model_draft(raw).unwrap_or_default(),
        |draft| review_metric_card_model_draft(draft),
        |attempt_index, findings, _| match attempt_index {
            0 => Some(RetryMethodDirective {
                method_id: "strict_json_contract".into(),
                retry_user_prompt: build_metric_card_retry_prompt(&user_prompt, findings),
            }),
            1 => Some(RetryMethodDirective {
                method_id: "fieldwise_recovery_posture".into(),
                retry_user_prompt: build_metric_card_recovery_prompt(&user_prompt, findings),
            }),
            _ => None,
        },
    )?;
    let generation_receipt_path = retry_search.generation_receipt_path;
    let semantic_draft = retry_search.draft;
    let review_findings = retry_search.review_findings;
    let final_generation_receipt = retry_search.final_generation_receipt;
    if !review_findings.is_empty() {
        if should_recommend_metric_card_decomposition(&final_generation_receipt, &review_findings) {
            let decomposition_root = runtime_root.join("task_decomposition_receipts");
            let proposal_root = runtime_root.join("task_decomposition_proposals");
            let inference_root = runtime_root.join("task_decomposition_inference_receipts");
            let (proposal, mut inference, decomposition) = infer_semantic_object_field_split(
                task,
                task_list,
                &final_generation_receipt,
                &generation_receipt_path,
                &review_findings,
                "metric_card_block",
                &["title_literal", "value_line", "context_sentence"],
                "host_render_metric_card_block",
            );
            let proposal_path = persist_task_decomposition_proposal(&proposal_root, &proposal)?;
            inference.proposal_path = Some(proposal_path.display().to_string());
            let inference_path =
                persist_task_decomposition_inference_receipt(&inference_root, &inference)?;
            let decomposition_receipt_path =
                persist_task_decomposition_receipt(&decomposition_root, &decomposition)?;
            let mut findings = review_findings.clone();
            findings.push(format!(
                "adaptive decomposition recommended; see {}",
                decomposition_receipt_path.display()
            ));
            findings.push(format!(
                "generic decomposition proposal persisted: {}",
                proposal_path.display()
            ));
            findings.push(format!(
                "generic decomposition inference persisted: {}",
                inference_path.display()
            ));
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: Some(generation_receipt_path.display().to_string()),
                decomposition_receipt_path: Some(decomposition_receipt_path.display().to_string()),
                raw_response_path: final_generation_receipt.raw_response_path.clone(),
                model_path: Some(final_generation_receipt.model_path.clone()),
                status: "decomposition_recommended".into(),
                review_findings: findings,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "decomposition_recommended".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "model-authored metric card task recommended adaptive decomposition; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if retry_search.method_space_exhausted {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings: {
                let mut findings = review_findings;
                findings.push(format!(
                    "attempted retry methods: {}",
                    retry_search.attempted_methods.join(", ")
                ));
                findings.push(format!(
                    "attempted models: {}",
                    retry_search.attempted_models.join(", ")
                ));
                findings
            },
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored metric card task was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let anchor = "            // native_window_feature_patch_anchor";
    if !original.contains(anchor) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "model-authored metric card task could not find the native window feature anchor"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored metric card task stayed pending because the anchor was missing; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let rendered_block = render_metric_card_model_draft(&semantic_draft);
    let wrapped_block = format!(
        "            // chattyfactory:feature:metric_card:start\n{}\n            // chattyfactory:feature:metric_card:end\n\n            // native_window_feature_patch_anchor",
        indent_model_authored_block(&rendered_block, 12)
    );
    let updated = original.replacen(anchor, &wrapped_block, 1);
    fs::write(&target_path, updated)?;
    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: vec![
            "model-authored metric card semantic draft passed review and was rendered into the native window feature anchor"
                .into(),
        ],
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files: vec![target_file],
            findings: vec![format!(
                "model-authored metric card task inserted a bounded generated metric card block; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn attempt_native_metric_card_field_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
    field_kind: &str,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![format!(
                "decomposed metric card field task `{field_kind}` stayed pending because no Rust entrypoint target file was declared"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card field task `{field_kind}` stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:metric_card:start";
    let end_marker = "            // chattyfactory:feature:metric_card:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![format!(
                "decomposed metric card field task `{field_kind}` found the bounded feature block already present"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card field task `{field_kind}` found the bounded feature block already present; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) =
        build_metric_card_field_prompts(task, task_list, &target_file, &anchor_context, field_kind);
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "decomposed metric card field task `{field_kind}` could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "decomposed metric card field task `{field_kind}` stayed pending because local generation failed; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let initial_generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let initial_field_draft = parse_metric_card_field_draft(&raw_generated).unwrap_or_default();
    let retry_search = run_bounded_retry_search(
        &config,
        &catalog,
        task,
        &system_prompt,
        &user_prompt,
        &prompt_path,
        &raw_response_dir,
        &generation_receipt_root,
        planner.requested_model.as_deref(),
        initial_field_draft.clone(),
        review_metric_card_field_draft(&initial_field_draft, field_kind),
        generation_receipt,
        initial_generation_receipt_path,
        |raw| parse_metric_card_field_draft(raw).unwrap_or_default(),
        |draft| review_metric_card_field_draft(draft, field_kind),
        |attempt_index, findings, _| match attempt_index {
            0 => Some(RetryMethodDirective {
                method_id: format!("{field_kind}_strict_json_contract"),
                retry_user_prompt: build_metric_card_field_retry_prompt(
                    &user_prompt,
                    findings,
                    field_kind,
                ),
            }),
            1 => Some(RetryMethodDirective {
                method_id: format!("{field_kind}_field_recovery_posture"),
                retry_user_prompt: build_metric_card_field_recovery_prompt(
                    &user_prompt,
                    findings,
                    field_kind,
                ),
            }),
            _ => None,
        },
    )?;
    let generation_receipt_path = retry_search.generation_receipt_path;
    let mut field_draft = retry_search.draft;
    let mut review_findings = retry_search.review_findings;
    let final_generation_receipt = retry_search.final_generation_receipt;
    if !review_findings.is_empty() {
        if let Some(recovered_draft) =
            recover_single_field_draft_from_reasoning_spill(&final_generation_receipt)
        {
            let recovered_findings = review_metric_card_field_draft(&recovered_draft, field_kind);
            if recovered_findings.is_empty() {
                field_draft = recovered_draft;
                review_findings.clear();
            } else {
                review_findings = recovered_findings
                    .into_iter()
                    .map(|finding| format!("recovered review: {finding}"))
                    .collect::<Vec<_>>();
            }
        }
    }
    if !review_findings.is_empty() {
        if field_kind == "context"
            && should_recommend_metric_card_context_decomposition(
                &final_generation_receipt,
                &review_findings,
            )
        {
            let proposal_root = runtime_root.join("task_decomposition_proposals");
            let inference_root = runtime_root.join("task_decomposition_inference_receipts");
            let decomposition_root = runtime_root.join("task_decomposition_receipts");
            let (proposal, mut inference, decomposition) = infer_semantic_sentence_clause_split(
                task,
                task_list,
                &final_generation_receipt,
                &generation_receipt_path,
                &review_findings,
                "metric_card_context_sentence",
                &[
                    "metric_card_context_clause_subject",
                    "metric_card_context_clause_purpose",
                ],
                "host_compose_metric_card_context_sentence",
            );
            let proposal_path = persist_task_decomposition_proposal(&proposal_root, &proposal)?;
            inference.proposal_path = Some(proposal_path.display().to_string());
            let inference_path =
                persist_task_decomposition_inference_receipt(&inference_root, &inference)?;
            let decomposition_receipt_path =
                persist_task_decomposition_receipt(&decomposition_root, &decomposition)?;
            let mut findings = review_findings.clone();
            findings.push(format!(
                "adaptive decomposition recommended; see {}",
                decomposition_receipt_path.display()
            ));
            findings.push(format!(
                "generic decomposition proposal persisted: {}",
                proposal_path.display()
            ));
            findings.push(format!(
                "generic decomposition inference persisted: {}",
                inference_path.display()
            ));
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: Some(generation_receipt_path.display().to_string()),
                decomposition_receipt_path: Some(decomposition_receipt_path.display().to_string()),
                raw_response_path: final_generation_receipt.raw_response_path.clone(),
                model_path: Some(final_generation_receipt.model_path.clone()),
                status: "decomposition_recommended".into(),
                review_findings: findings,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "decomposition_recommended".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "decomposed metric card field task `{field_kind}` recommended adaptive decomposition; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if retry_search.method_space_exhausted {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings: {
                let mut findings = review_findings;
                findings.push(format!(
                    "attempted retry methods: {}",
                    retry_search.attempted_methods.join(", ")
                ));
                findings.push(format!(
                    "attempted models: {}",
                    retry_search.attempted_models.join(", ")
                ));
                findings
            },
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card field task `{field_kind}` was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let field_dir = runtime_root
        .join("model_task_metric_card_drafts")
        .join(sanitize_filename(&task_list.request_id));
    fs::create_dir_all(&field_dir)?;
    let field_path = field_dir.join(format!(
        "{}-{}.json",
        sanitize_filename(&task_list.project_name),
        field_kind
    ));
    persist_json_pretty(&field_path, &field_draft)?;

    let mut touched_files = Vec::new();
    let mut findings = vec![format!(
        "decomposed metric card field task `{field_kind}` persisted a reviewed field draft"
    )];
    if let Some(metric_card_draft) =
        try_compose_metric_card_from_field_drafts(&field_dir, &task_list.project_name)
    {
        let anchor = "            // native_window_feature_patch_anchor";
        if original.contains(anchor) {
            let rendered_block = render_metric_card_model_draft(&metric_card_draft);
            let wrapped_block = format!(
                "            // chattyfactory:feature:metric_card:start\n{}\n            // chattyfactory:feature:metric_card:end\n\n            // native_window_feature_patch_anchor",
                indent_model_authored_block(&rendered_block, 12)
            );
            let updated = original.replacen(anchor, &wrapped_block, 1);
            fs::write(&target_path, updated)?;
            touched_files.push(target_file.clone());
            findings.push(
                "host composed the final metric card semantic draft from decomposed field drafts and rendered the metric card block".into(),
            );
        }
    }

    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: findings.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files,
            findings: vec![format!(
                "decomposed metric card field task `{field_kind}` executed; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn attempt_native_metric_card_context_clause_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
    clause_kind: &str,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![format!(
                "decomposed metric card context clause task `{clause_kind}` stayed pending because no Rust entrypoint target file was declared"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card context clause task `{clause_kind}` stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:metric_card:start";
    let end_marker = "            // chattyfactory:feature:metric_card:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![format!(
                "decomposed metric card context clause task `{clause_kind}` found the bounded feature block already present"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card context clause task `{clause_kind}` found the bounded feature block already present; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) = build_metric_card_context_clause_prompts(
        task,
        task_list,
        &target_file,
        &anchor_context,
        clause_kind,
    );
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "decomposed metric card context clause task `{clause_kind}` could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "decomposed metric card context clause task `{clause_kind}` stayed pending because local generation failed; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let mut generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let mut clause_draft = parse_metric_card_field_draft(&raw_generated).unwrap_or_default();
    let mut review_findings = review_metric_card_context_clause_draft(&clause_draft, clause_kind);
    let mut final_generation_receipt = generation_receipt;
    if !review_findings.is_empty() {
        let retry_search = run_bounded_retry_search(
            &config,
            &catalog,
            task,
            &system_prompt,
            &user_prompt,
            &prompt_path,
            &raw_response_dir,
            &generation_receipt_root,
            planner.requested_model.as_deref(),
            clause_draft.clone(),
            review_findings,
            final_generation_receipt,
            generation_receipt_path.clone(),
            |raw| parse_metric_card_field_draft(raw).unwrap_or_default(),
            |draft| review_metric_card_context_clause_draft(draft, clause_kind),
            |attempt_index, findings, _| match attempt_index {
                0 => Some(RetryMethodDirective {
                    method_id: format!("{clause_kind}_strict_json_contract"),
                    retry_user_prompt: build_metric_card_context_clause_retry_prompt(
                        &user_prompt,
                        findings,
                        clause_kind,
                    ),
                }),
                1 => Some(RetryMethodDirective {
                    method_id: format!("{clause_kind}_clause_recovery_posture"),
                    retry_user_prompt: build_metric_card_context_clause_recovery_prompt(
                        &user_prompt,
                        findings,
                        clause_kind,
                    ),
                }),
                _ => None,
            },
        )?;
        clause_draft = retry_search.draft;
        review_findings = retry_search.review_findings;
        generation_receipt_path = retry_search.generation_receipt_path;
        final_generation_receipt = retry_search.final_generation_receipt;
        if retry_search.method_space_exhausted {
            review_findings.push(format!(
                "attempted retry methods: {}",
                retry_search.attempted_methods.join(", ")
            ));
            review_findings.push(format!(
                "attempted models: {}",
                retry_search.attempted_models.join(", ")
            ));
        }
    }
    if !review_findings.is_empty() {
        if let Some(recovered_draft) =
            recover_single_field_draft_from_reasoning_spill(&final_generation_receipt)
        {
            let recovered_findings =
                review_metric_card_context_clause_draft(&recovered_draft, clause_kind);
            if recovered_findings.is_empty() {
                clause_draft = recovered_draft;
                review_findings.clear();
            } else {
                review_findings = recovered_findings
                    .into_iter()
                    .map(|finding| format!("recovered review: {finding}"))
                    .collect::<Vec<_>>();
            }
        }
    }
    if !review_findings.is_empty() {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if review_findings
                .iter()
                .any(|finding| finding.contains("attempted retry methods:"))
            {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed metric card context clause task `{clause_kind}` was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let clause_dir = runtime_root
        .join("model_task_metric_card_context_clauses")
        .join(sanitize_filename(&task_list.request_id));
    fs::create_dir_all(&clause_dir)?;
    let clause_path = clause_dir.join(format!(
        "{}-{}.json",
        sanitize_filename(&task_list.project_name),
        clause_kind
    ));
    persist_json_pretty(&clause_path, &clause_draft)?;

    let mut touched_files = Vec::new();
    let mut findings = vec![format!(
        "decomposed metric card context clause task `{clause_kind}` persisted a reviewed clause draft"
    )];
    if let Some(context_value) =
        try_compose_metric_card_context_from_clause_drafts(&clause_dir, &task_list.project_name)
    {
        let field_dir = runtime_root
            .join("model_task_metric_card_drafts")
            .join(sanitize_filename(&task_list.request_id));
        fs::create_dir_all(&field_dir)?;
        let context_field_path = field_dir.join(format!(
            "{}-context.json",
            sanitize_filename(&task_list.project_name)
        ));
        persist_json_pretty(
            &context_field_path,
            &MetricCardFieldDraft {
                value: context_value,
            },
        )?;
        if let Some(metric_card_draft) =
            try_compose_metric_card_from_field_drafts(&field_dir, &task_list.project_name)
        {
            let anchor = "            // native_window_feature_patch_anchor";
            if original.contains(anchor) {
                let rendered_block = render_metric_card_model_draft(&metric_card_draft);
                let wrapped_block = format!(
                    "            // chattyfactory:feature:metric_card:start\n{}\n            // chattyfactory:feature:metric_card:end\n\n            // native_window_feature_patch_anchor",
                    indent_model_authored_block(&rendered_block, 12)
                );
                let updated = original.replacen(anchor, &wrapped_block, 1);
                fs::write(&target_path, updated)?;
                touched_files.push(target_file.clone());
                findings.push(
                    "host composed the final metric card context sentence from clause drafts and rendered the metric card block".into(),
                );
            }
        }
    }

    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: findings.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files,
            findings: vec![format!(
                "decomposed metric card context clause task `{clause_kind}` executed; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn attempt_native_action_toolbar_model_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "model-authored task stayed pending because no Rust entrypoint target file was declared"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored action toolbar task stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:action_toolbar:start";
    let end_marker = "            // chattyfactory:feature:action_toolbar:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![
                "model-authored action toolbar task found the bounded feature block already present"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![
                    format!(
                        "model-authored action toolbar task found the bounded feature block already present; see {}",
                        receipt_path.display()
                    ),
                ],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) =
        build_action_toolbar_model_prompts(task, task_list, &target_file, &anchor_context);
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "model-authored action toolbar task could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![
                        format!(
                            "model-authored action toolbar task stayed pending because local generation failed; see {}",
                            receipt_path.display()
                        ),
                    ],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let initial_generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let initial_semantic_draft =
        parse_action_toolbar_model_draft(&raw_generated).unwrap_or_default();
    let retry_search = run_bounded_retry_search(
        &config,
        &catalog,
        task,
        &system_prompt,
        &user_prompt,
        &prompt_path,
        &raw_response_dir,
        &generation_receipt_root,
        planner.requested_model.as_deref(),
        initial_semantic_draft.clone(),
        review_action_toolbar_model_draft(&initial_semantic_draft),
        generation_receipt,
        initial_generation_receipt_path,
        |raw| parse_action_toolbar_model_draft(raw).unwrap_or_default(),
        |draft| review_action_toolbar_model_draft(draft),
        |attempt_index, findings, _| match attempt_index {
            0 => Some(RetryMethodDirective {
                method_id: "strict_json_contract".into(),
                retry_user_prompt: build_action_toolbar_retry_prompt(&user_prompt, findings),
            }),
            1 => Some(RetryMethodDirective {
                method_id: "fieldwise_recovery_posture".into(),
                retry_user_prompt: build_action_toolbar_recovery_prompt(&user_prompt, findings),
            }),
            _ => None,
        },
    )?;
    let generation_receipt_path = retry_search.generation_receipt_path;
    let semantic_draft = retry_search.draft;
    let review_findings = retry_search.review_findings;
    let final_generation_receipt = retry_search.final_generation_receipt;
    if !review_findings.is_empty() {
        if should_recommend_action_toolbar_decomposition(
            &final_generation_receipt,
            &review_findings,
        ) {
            let decomposition_root = runtime_root.join("task_decomposition_receipts");
            let decomposition = build_action_toolbar_decomposition_receipt(
                task,
                task_list,
                &final_generation_receipt,
                &generation_receipt_path,
                &review_findings,
            );
            let decomposition_receipt_path =
                persist_task_decomposition_receipt(&decomposition_root, &decomposition)?;
            let mut findings = review_findings.clone();
            findings.push(format!(
                "adaptive decomposition recommended; see {}",
                decomposition_receipt_path.display()
            ));
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: Some(generation_receipt_path.display().to_string()),
                decomposition_receipt_path: Some(decomposition_receipt_path.display().to_string()),
                raw_response_path: final_generation_receipt.raw_response_path.clone(),
                model_path: Some(final_generation_receipt.model_path.clone()),
                status: "decomposition_recommended".into(),
                review_findings: findings,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "decomposition_recommended".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "model-authored action toolbar task recommended adaptive decomposition; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if retry_search.method_space_exhausted {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings: {
                let mut findings = review_findings;
                findings.push(format!(
                    "attempted retry methods: {}",
                    retry_search.attempted_methods.join(", ")
                ));
                findings.push(format!(
                    "attempted models: {}",
                    retry_search.attempted_models.join(", ")
                ));
                findings
            },
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "model-authored action toolbar task was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let anchor = "            // native_window_feature_patch_anchor";
    if !original.contains(anchor) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "model-authored action toolbar task could not find the native window feature anchor"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![
                    format!(
                        "model-authored action toolbar task stayed pending because the anchor was missing; see {}",
                        receipt_path.display()
                    ),
                ],
            },
            receipt_path,
        ));
    }

    let rendered_block = render_action_toolbar_model_draft(&semantic_draft);
    let wrapped_block = format!(
        "            // chattyfactory:feature:action_toolbar:start\n{}\n            // chattyfactory:feature:action_toolbar:end\n\n            // native_window_feature_patch_anchor",
        indent_model_authored_block(&rendered_block, 12)
    );
    let updated = original.replacen(anchor, &wrapped_block, 1);
    fs::write(&target_path, updated)?;
    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: vec![
            "model-authored action toolbar semantic draft passed review and was rendered into the native window feature anchor"
                .into(),
        ],
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files: vec![target_file],
            findings: vec![format!(
                "model-authored action toolbar task inserted a bounded generated block; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn attempt_native_action_toolbar_label_sentence_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "decomposed toolbar label task stayed pending because no Rust entrypoint target file was declared"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar label task stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:action_toolbar:start";
    let end_marker = "            // chattyfactory:feature:action_toolbar:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![
                "decomposed toolbar label task found the bounded feature block already present"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar label task found the bounded feature block already present; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) =
        build_action_toolbar_label_sentence_prompts(task, task_list, &target_file, &anchor_context);
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "decomposed toolbar label task could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "decomposed toolbar label task stayed pending because local generation failed; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let mut generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let mut label_draft = parse_action_toolbar_label_draft(&raw_generated).unwrap_or_default();
    let mut review_findings = review_action_toolbar_label_draft(&label_draft);
    let mut final_generation_receipt = generation_receipt;
    if should_recommend_action_toolbar_label_decomposition(
        &final_generation_receipt,
        &review_findings,
    ) {
        let decomposition_root = runtime_root.join("task_decomposition_receipts");
        let decomposition = build_action_toolbar_label_decomposition_receipt(
            task,
            task_list,
            &final_generation_receipt,
            &generation_receipt_path,
            &review_findings,
        );
        let decomposition_receipt_path =
            persist_task_decomposition_receipt(&decomposition_root, &decomposition)?;
        let mut findings = review_findings.clone();
        findings.push(format!(
            "adaptive decomposition recommended; see {}",
            decomposition_receipt_path.display()
        ));
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: Some(decomposition_receipt_path.display().to_string()),
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: "decomposition_recommended".into(),
            review_findings: findings,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "decomposition_recommended".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar label task recommended adaptive decomposition; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }
    if !review_findings.is_empty() {
        let retry_search = run_bounded_retry_search(
            &config,
            &catalog,
            task,
            &system_prompt,
            &user_prompt,
            &prompt_path,
            &raw_response_dir,
            &generation_receipt_root,
            planner.requested_model.as_deref(),
            label_draft.clone(),
            review_findings,
            final_generation_receipt,
            generation_receipt_path.clone(),
            |raw| parse_action_toolbar_label_draft(raw).unwrap_or_default(),
            |draft| review_action_toolbar_label_draft(draft),
            |attempt_index, findings, _| match attempt_index {
                0 => Some(RetryMethodDirective {
                    method_id: "sentence_strict_json_contract".into(),
                    retry_user_prompt: build_action_toolbar_label_sentence_retry_prompt(
                        &user_prompt,
                        findings,
                    ),
                }),
                1 => Some(RetryMethodDirective {
                    method_id: "sentence_recovery_posture".into(),
                    retry_user_prompt: build_action_toolbar_label_sentence_recovery_prompt(
                        &user_prompt,
                        findings,
                    ),
                }),
                _ => None,
            },
        )?;
        label_draft = retry_search.draft;
        review_findings = retry_search.review_findings;
        generation_receipt_path = retry_search.generation_receipt_path;
        final_generation_receipt = retry_search.final_generation_receipt;
        if retry_search.method_space_exhausted {
            review_findings.push(format!(
                "attempted retry methods: {}",
                retry_search.attempted_methods.join(", ")
            ));
            review_findings.push(format!(
                "attempted models: {}",
                retry_search.attempted_models.join(", ")
            ));
        }
    }

    if !review_findings.is_empty() {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if review_findings
                .iter()
                .any(|finding| finding.contains("attempted retry methods:"))
            {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar label task was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let anchor = "            // native_window_feature_patch_anchor";
    if !original.contains(anchor) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: "pending_not_attempted".into(),
            review_findings: vec![
                "decomposed toolbar label task could not find the native window feature anchor"
                    .into(),
            ],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar label task stayed pending because the anchor was missing; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let rendered_block = render_action_toolbar_model_draft(&ActionToolbarSemanticDraft {
        title: "Action toolbar".into(),
        label: label_draft.label.trim().to_string(),
        primary_button: "Run action".into(),
        secondary_button: "Clear".into(),
    });
    let wrapped_block = format!(
        "            // chattyfactory:feature:action_toolbar:start\n{}\n            // chattyfactory:feature:action_toolbar:end\n\n            // native_window_feature_patch_anchor",
        indent_model_authored_block(&rendered_block, 12)
    );
    let updated = original.replacen(anchor, &wrapped_block, 1);
    fs::write(&target_path, updated)?;
    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: vec![
            "decomposed toolbar label task passed review and the host rendered the full toolbar block with fixed literals".into(),
        ],
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files: vec![target_file],
            findings: vec![format!(
                "decomposed toolbar label task inserted a bounded rendered toolbar block; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn attempt_native_action_toolbar_label_clause_microtask(
    runtime_root: &Path,
    workspace_root: &Path,
    project_dir: &Path,
    task: &PlanTask,
    task_list: &PlanTaskList,
    planner: &HostPlannerOptions,
    clause_kind: &str,
) -> Result<(TaskAttemptOutcome, PathBuf)> {
    let prompt_root = runtime_root.join("model_task_prompts");
    let prompt_path = prompt_root.join(format!("{}-prompt.md", sanitize_filename(&task.task_id)));
    let receipt_root = runtime_root.join("model_task_attempts");
    let Some(target_file) = task
        .target_files
        .iter()
        .find(|path| path.ends_with("src/main.rs"))
        .cloned()
    else {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: None,
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "pending_not_attempted".into(),
            review_findings: vec![format!(
                "decomposed toolbar clause task `{clause_kind}` stayed pending because no Rust entrypoint target file was declared"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "pending_not_attempted".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar clause task `{clause_kind}` stayed pending; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    };

    let target_path = project_dir.join(&target_file);
    let original = fs::read_to_string(&target_path)?;
    let start_marker = "            // chattyfactory:feature:action_toolbar:start";
    let end_marker = "            // chattyfactory:feature:action_toolbar:end";
    if original.contains(start_marker) && original.contains(end_marker) {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: None,
            decomposition_receipt_path: None,
            raw_response_path: None,
            model_path: None,
            status: "no_change_needed".into(),
            review_findings: vec![format!(
                "decomposed toolbar clause task `{clause_kind}` found the bounded feature block already present"
            )],
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "no_change_needed".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar clause task `{clause_kind}` found the bounded feature block already present; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let prompt_markers = [
        "            // native_window_feature_patch_anchor",
        "            // bridge_status_panel_anchor",
        "            // ready_toggle_anchor",
    ];
    let mut anchor_context = String::new();
    for line in original.lines() {
        if prompt_markers.iter().any(|marker| line.contains(marker)) {
            anchor_context.push_str(line);
            anchor_context.push('\n');
        }
    }
    let (system_prompt, user_prompt) = build_action_toolbar_label_clause_prompts(
        task,
        task_list,
        &target_file,
        &anchor_context,
        clause_kind,
    );
    fs::create_dir_all(&prompt_root)?;
    fs::write(
        &prompt_path,
        format!("# System\n{}\n\n# User\n{}\n", system_prompt, user_prompt),
    )?;

    let models_root = workspace_root.join("models");
    let discovery = discover_runtime(runtime_root, &models_root)?;
    let catalog = build_runtime_model_catalog(&models_root)?;
    let mut config = default_runtime_config(runtime_root, &models_root)?;
    config.default_model_path = resolve_model_choice(
        planner.requested_model.as_deref(),
        &catalog,
        discovery.preferred_model_path.as_deref(),
    );
    if let Some(port) = planner.requested_port {
        config.port = port;
    }
    persist_json_pretty(&runtime_root.join("runtime_config.json"), &config)?;

    let raw_response_dir = runtime_root.join("model_task_raw_responses");
    let (raw_generated, generation_receipt) = match run_local_text_generation(
        &config,
        &task.request_id,
        &task.task_id,
        &system_prompt,
        &user_prompt,
        &raw_response_dir,
        planner.requested_model.as_deref(),
    ) {
        Ok(value) => value,
        Err(error) => {
            let receipt = PlanTaskModelAttemptReceipt {
                attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
                request_id: task.request_id.clone(),
                task_id: task.task_id.clone(),
                project_name: task_list.project_name.clone(),
                target_file: Some(target_file.clone()),
                prompt_path: prompt_path.display().to_string(),
                generation_receipt_path: None,
                decomposition_receipt_path: None,
                raw_response_path: None,
                model_path: config.default_model_path.clone(),
                status: "pending_not_attempted".into(),
                review_findings: vec![format!(
                    "decomposed toolbar clause task `{clause_kind}` could not run local text generation: {error}"
                )],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
            return Ok((
                TaskAttemptOutcome {
                    status: "pending_not_attempted".into(),
                    touched_files: Vec::new(),
                    findings: vec![format!(
                        "decomposed toolbar clause task `{clause_kind}` stayed pending because local generation failed; see {}",
                        receipt_path.display()
                    )],
                },
                receipt_path,
            ));
        }
    };

    let generation_receipt_root = runtime_root.join("model_task_generation_receipts");
    let generation_receipt_path =
        persist_model_task_generation_receipt(&generation_receipt_root, &generation_receipt)?;
    let mut clause_draft = parse_action_toolbar_clause_draft(&raw_generated).unwrap_or_default();
    let mut review_findings = review_action_toolbar_clause_draft(&clause_draft, clause_kind);
    let mut final_generation_receipt = generation_receipt;
    let mut generation_receipt_path = generation_receipt_path;
    if !review_findings.is_empty() {
        let retry_search = run_bounded_retry_search(
            &config,
            &catalog,
            task,
            &system_prompt,
            &user_prompt,
            &prompt_path,
            &raw_response_dir,
            &generation_receipt_root,
            planner.requested_model.as_deref(),
            clause_draft.clone(),
            review_findings,
            final_generation_receipt,
            generation_receipt_path.clone(),
            |raw| parse_action_toolbar_clause_draft(raw).unwrap_or_default(),
            |draft| review_action_toolbar_clause_draft(draft, clause_kind),
            |attempt_index, findings, _| match attempt_index {
                0 => Some(RetryMethodDirective {
                    method_id: format!("{clause_kind}_strict_json_contract"),
                    retry_user_prompt: build_action_toolbar_label_clause_retry_prompt(
                        &user_prompt,
                        findings,
                        clause_kind,
                    ),
                }),
                1 => Some(RetryMethodDirective {
                    method_id: format!("{clause_kind}_clause_recovery_posture"),
                    retry_user_prompt: build_action_toolbar_label_clause_recovery_prompt(
                        &user_prompt,
                        findings,
                        clause_kind,
                    ),
                }),
                _ => None,
            },
        )?;
        clause_draft = retry_search.draft;
        review_findings = retry_search.review_findings;
        generation_receipt_path = retry_search.generation_receipt_path;
        final_generation_receipt = retry_search.final_generation_receipt;
        if retry_search.method_space_exhausted {
            review_findings.push(format!(
                "attempted retry methods: {}",
                retry_search.attempted_methods.join(", ")
            ));
            review_findings.push(format!(
                "attempted models: {}",
                retry_search.attempted_models.join(", ")
            ));
        }
    }
    if !review_findings.is_empty() {
        let receipt = PlanTaskModelAttemptReceipt {
            attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
            request_id: task.request_id.clone(),
            task_id: task.task_id.clone(),
            project_name: task_list.project_name.clone(),
            target_file: Some(target_file.clone()),
            prompt_path: prompt_path.display().to_string(),
            generation_receipt_path: Some(generation_receipt_path.display().to_string()),
            decomposition_receipt_path: None,
            raw_response_path: final_generation_receipt.raw_response_path.clone(),
            model_path: Some(final_generation_receipt.model_path.clone()),
            status: if review_findings
                .iter()
                .any(|finding| finding.contains("attempted retry methods:"))
            {
                "method_space_exhausted".into()
            } else {
                "blocked_by_review".into()
            },
            review_findings,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
        return Ok((
            TaskAttemptOutcome {
                status: "blocked_by_review".into(),
                touched_files: Vec::new(),
                findings: vec![format!(
                    "decomposed toolbar clause task `{clause_kind}` was blocked by narrow review; see {}",
                    receipt_path.display()
                )],
            },
            receipt_path,
        ));
    }

    let clause_dir = runtime_root
        .join("model_task_clause_drafts")
        .join(sanitize_filename(&task_list.request_id));
    fs::create_dir_all(&clause_dir)?;
    let clause_path = clause_dir.join(format!(
        "{}-{}.json",
        sanitize_filename(&task_list.project_name),
        clause_kind
    ));
    persist_json_pretty(&clause_path, &clause_draft)?;

    let mut touched_files = Vec::new();
    let mut findings = vec![format!(
        "decomposed toolbar clause task `{clause_kind}` persisted a reviewed clause draft"
    )];
    if let Some(composed_label) =
        try_compose_toolbar_label_from_clause_drafts(&clause_dir, &task_list.project_name)
    {
        let anchor = "            // native_window_feature_patch_anchor";
        if original.contains(anchor) {
            let rendered_block = render_action_toolbar_model_draft(&ActionToolbarSemanticDraft {
                title: "Action toolbar".into(),
                label: composed_label,
                primary_button: "Run action".into(),
                secondary_button: "Clear".into(),
            });
            let wrapped_block = format!(
                "            // chattyfactory:feature:action_toolbar:start\n{}\n            // chattyfactory:feature:action_toolbar:end\n\n            // native_window_feature_patch_anchor",
                indent_model_authored_block(&rendered_block, 12)
            );
            let updated = original.replacen(anchor, &wrapped_block, 1);
            fs::write(&target_path, updated)?;
            touched_files.push(target_file.clone());
            findings.push(
                "host composed the final toolbar label sentence from decomposed clause drafts and rendered the toolbar block".into(),
            );
        }
    }

    let receipt = PlanTaskModelAttemptReceipt {
        attempt_id: chatty_factory_core::timestamp_id("model-task-attempt"),
        request_id: task.request_id.clone(),
        task_id: task.task_id.clone(),
        project_name: task_list.project_name.clone(),
        target_file: Some(target_file.clone()),
        prompt_path: prompt_path.display().to_string(),
        generation_receipt_path: Some(generation_receipt_path.display().to_string()),
        decomposition_receipt_path: None,
        raw_response_path: final_generation_receipt.raw_response_path.clone(),
        model_path: Some(final_generation_receipt.model_path.clone()),
        status: "executed".into(),
        review_findings: findings.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = persist_plan_task_model_attempt_receipt(&receipt_root, &receipt)?;
    Ok((
        TaskAttemptOutcome {
            status: "executed".into(),
            touched_files,
            findings: vec![format!(
                "decomposed toolbar clause task `{clause_kind}` executed; see {}",
                receipt_path.display()
            )],
        },
        receipt_path,
    ))
}

fn build_action_toolbar_model_prompts(
    task: &PlanTask,
    task_list: &PlanTaskList,
    target_file: &str,
    anchor_context: &str,
) -> (String, String) {
    let system_prompt = "Return exactly one minified JSON object and nothing else. Do not return Rust code. Do not return markdown. Do not use code fences. Do not add prose. Use exactly these keys: title, label, primary_button, secondary_button.".to_string();
    let user_prompt = format!(
        "Task id: {task_id}\nProject: {project}\nTitle: {title}\nSummary: {summary}\nTarget file: {target_file}\nExpected symbols: {expected_symbols}\nVerification intent: {verification}\nAnchor context:\n{anchor_context}\n\nReturn exactly one minified JSON object for a tiny action toolbar semantic draft. Requirements:\n- use exactly these keys: `title`, `label`, `primary_button`, `secondary_button`\n- set `title` to the exact literal `Action toolbar`\n- set `primary_button` to the exact literal `Run action`\n- set `secondary_button` to the exact literal `Clear`\n- make `label` one short explanatory sentence for the toolbar\n- no extra keys\n- no markdown\n- no prose\n- no Rust code\n- output must look like this shape exactly:\n{{\"title\":\"Action toolbar\",\"label\":\"Short explanatory label\",\"primary_button\":\"Run action\",\"secondary_button\":\"Clear\"}}",
        task_id = task.task_id,
        project = task_list.project_name,
        title = task.task_title,
        summary = task.task_summary,
        target_file = target_file,
        expected_symbols = task.expected_symbols.join(", "),
        verification = task.verification_steps.join(", "),
        anchor_context = anchor_context.trim_end(),
    );
    (system_prompt, user_prompt)
}

fn build_metric_card_model_prompts(
    task: &PlanTask,
    task_list: &PlanTaskList,
    target_file: &str,
    anchor_context: &str,
) -> (String, String) {
    let system_prompt = "Return exactly one minified JSON object and nothing else. Do not return Rust code. Do not return markdown. Do not use code fences. Do not add prose. Use exactly these keys: title, value, context.".to_string();
    let user_prompt = format!(
        "Task id: {task_id}\nProject: {project}\nTitle: {title}\nSummary: {summary}\nTarget file: {target_file}\nExpected symbols: {expected_symbols}\nVerification intent: {verification}\nAnchor context:\n{anchor_context}\n\nReturn exactly one minified JSON object for a tiny metric card semantic draft. Requirements:\n- use exactly these keys: `title`, `value`, `context`\n- `title` must be a short metric-card heading\n- `value` must be a short value line suitable for monospace display\n- `context` must be one short explanatory sentence\n- keep each field concise and useful for a real dashboard\n- do not use placeholder wording like `placeholder`, `todo`, `sample`, or `example`\n- no extra keys\n- no markdown\n- no prose\n- no Rust code\n- output must look like this shape exactly:\n{{\"title\":\"Room activity\",\"value\":\"24 active events\",\"context\":\"Shows the current shared-room activity snapshot.\"}}",
        task_id = task.task_id,
        project = task_list.project_name,
        title = task.task_title,
        summary = task.task_summary,
        target_file = target_file,
        expected_symbols = task.expected_symbols.join(", "),
        verification = task.verification_steps.join(", "),
        anchor_context = anchor_context.trim_end(),
    );
    (system_prompt, user_prompt)
}

