    pub fn approve_proposed_constraint(
        &self,
        request_id_or_path: &str,
    ) -> Result<HostActionResult> {
        let proposal_path =
            resolve_proposed_constraint_path(&self.runtime_root, request_id_or_path)?;
        let mut proposal: ProposedConstraintReceipt =
            serde_json::from_str(&fs::read_to_string(&proposal_path)?)?;
        let (proposal_origin, proposal_source_id) = proposal_origin_and_source_id(&proposal);
        proposal.status = "approved".into();
        proposal.proposed_constraint.active = true;
        persist_json_pretty(&proposal_path, &proposal)?;

        let shelf_path = self.runtime_root.join("approved_constraint_shelf.json");
        let mut shelf = load_approved_constraint_shelf(&shelf_path)?;
        if let Some(existing) = shelf.constraints.iter_mut().find(|constraint| {
            constraint.constraint_id == proposal.proposed_constraint.constraint_id
        }) {
            *existing = proposal.proposed_constraint.clone();
        } else {
            shelf.constraints.push(proposal.proposed_constraint.clone());
        }
        shelf.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&shelf_path, &shelf)?;

        let normalized_failure_class = normalized_failure_class_for_constraint_approval("approved");
        let next_action = constraint_approval_next_action(&normalized_failure_class);
        let approval = ConstraintApprovalReceipt {
            approval_id: chatty_factory_core::timestamp_id("constraint-approval"),
            request_id: proposal.request_id.clone(),
            proposal_id: proposal.proposal_id.clone(),
            proposal_origin: proposal_origin.clone(),
            proposal_source_id: proposal_source_id.clone(),
            approved_constraint_id: proposal.proposed_constraint.constraint_id.clone(),
            status: "approved".into(),
            shelf_path: shelf_path.display().to_string(),
            proposal_path: proposal_path.display().to_string(),
            rationale: proposal.rationale.clone(),
            normalized_failure_class: normalized_failure_class.clone(),
            recommended_next_action: next_action.action_id.clone(),
            recommended_next_step: next_action.recommended_next_step.clone(),
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let approval_path = self
            .runtime_root
            .join("constraint_approvals")
            .join(format!("{}-constraint-approval.json", proposal.request_id));
        persist_json_pretty(&approval_path, &approval)?;

        let mutation_normalized_failure_class =
            normalized_failure_class_for_constraint_shelf_mutation(
                "approve",
                "approved_into_shelf",
            );
        let mutation_next_action =
            constraint_shelf_mutation_next_action("approve", &mutation_normalized_failure_class);
        let mutation = ConstraintShelfMutationReceipt {
            mutation_id: chatty_factory_core::timestamp_id("constraint-shelf-mutation"),
            constraint_id: proposal.proposed_constraint.constraint_id.clone(),
            action: "approve".into(),
            proposal_origin: Some(proposal_origin.clone()),
            proposal_source_id: Some(proposal_source_id.clone()),
            shelf_path: shelf_path.display().to_string(),
            status: "approved_into_shelf".into(),
            normalized_failure_class: mutation_normalized_failure_class,
            recommended_next_action: mutation_next_action.action_id,
            recommended_next_step: mutation_next_action.recommended_next_step,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let mutation_path = self
            .runtime_root
            .join("constraint_shelf_mutations")
            .join(format!(
                "approve-{}.json",
                sanitize_filename_like(&proposal.proposed_constraint.constraint_id)
            ));
        persist_json_pretty(&mutation_path, &mutation)?;

        Ok(HostActionResult {
            summary: "Proposed constraint approved".into(),
            details: vec![
                format!("proposal={}", proposal_path.display()),
                format!("proposal_origin={proposal_origin}"),
                format!("proposal_source_id={proposal_source_id}"),
                format!(
                    "approved_constraint={}",
                    proposal.proposed_constraint.constraint_id
                ),
                format!("shelf={}", shelf_path.display()),
                format!("approval_receipt={}", approval_path.display()),
                format!("mutation_receipt={}", mutation_path.display()),
                format!("shelf_constraints={}", shelf.constraints.len()),
            ],
            browser_state: None,
            runtime_refresh: None,
            execution_result: None,
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn set_approved_constraint_active(
        &self,
        constraint_id: &str,
        active: bool,
    ) -> Result<HostActionResult> {
        let shelf_path = self.runtime_root.join("approved_constraint_shelf.json");
        let mut shelf = load_approved_constraint_shelf(&shelf_path)?;
        let Some(constraint) = shelf
            .constraints
            .iter_mut()
            .find(|constraint| constraint.constraint_id == constraint_id)
        else {
            anyhow::bail!(
                "approved constraint `{}` was not found in the shelf",
                constraint_id
            );
        };
        constraint.active = active;
        shelf.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&shelf_path, &shelf)?;

        let action = if active { "activate" } else { "deactivate" };
        let normalized_failure_class =
            normalized_failure_class_for_constraint_shelf_mutation(action, "applied");
        let next_action = constraint_shelf_mutation_next_action(action, &normalized_failure_class);
        let mutation = ConstraintShelfMutationReceipt {
            mutation_id: chatty_factory_core::timestamp_id("constraint-shelf-mutation"),
            constraint_id: constraint_id.to_string(),
            action: action.into(),
            proposal_origin: None,
            proposal_source_id: None,
            shelf_path: shelf_path.display().to_string(),
            status: "applied".into(),
            normalized_failure_class,
            recommended_next_action: next_action.action_id,
            recommended_next_step: next_action.recommended_next_step,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let mutation_path = self
            .runtime_root
            .join("constraint_shelf_mutations")
            .join(format!(
                "{}-{}.json",
                action,
                sanitize_filename_like(constraint_id)
            ));
        persist_json_pretty(&mutation_path, &mutation)?;

        Ok(HostActionResult {
            summary: format!("Approved constraint {}d", action),
            details: vec![
                format!("constraint_id={constraint_id}"),
                format!("active={}", active),
                format!("shelf={}", shelf_path.display()),
                format!("mutation_receipt={}", mutation_path.display()),
            ],
            browser_state: None,
            runtime_refresh: None,
            execution_result: None,
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn archive_unmatched_inactive_constraints(&self) -> Result<HostActionResult> {
        let shelf_path = self.runtime_root.join("approved_constraint_shelf.json");
        let mut shelf = load_approved_constraint_shelf(&shelf_path)?;
        let history_path = self.runtime_root.join("constraint_shelf_history.json");
        let mut history = load_constraint_shelf_history(&history_path)?;
        let match_counts = approved_constraint_match_counts_from_runtime(&self.runtime_root);
        let archived_constraints = shelf
            .constraints
            .iter()
            .filter(|constraint| {
                !constraint.active
                    && match_counts
                        .get(&constraint.constraint_id)
                        .copied()
                        .unwrap_or_default()
                        == 0
            })
            .cloned()
            .collect::<Vec<_>>();
        if archived_constraints.is_empty() {
            return Ok(HostActionResult {
                summary: "No unmatched inactive constraints to archive".into(),
                details: vec![format!("shelf={}", shelf_path.display())],
                browser_state: None,
                runtime_refresh: None,
                execution_result: None,
                next_attempt_result: None,
                followup_route: None,
                extension_registry: None,
            });
        }

        let archived_constraint_ids = archived_constraints
            .iter()
            .map(|constraint| constraint.constraint_id.clone())
            .collect::<Vec<_>>();
        shelf.constraints.retain(|constraint| {
            !archived_constraint_ids
                .iter()
                .any(|constraint_id| constraint_id == &constraint.constraint_id)
        });
        shelf.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&shelf_path, &shelf)?;

        for constraint in archived_constraints {
            let archived_match_count = match_counts
                .get(&constraint.constraint_id)
                .copied()
                .unwrap_or_default();
            history
                .archived_constraints
                .push(ConstraintShelfHistoryEntry {
                    constraint,
                    archived_reason: "inactive_unmatched_bulk_archive".into(),
                    archived_from_shelf_id: Some(shelf.shelf_id.clone()),
                    archived_match_count,
                    archived_at: Some(chatty_factory_core::timestamp_id("archived")),
                });
        }
        history.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&history_path, &history)?;

        let mutation_root = self.runtime_root.join("constraint_shelf_mutations");
        for constraint_id in archived_constraint_ids.iter() {
            let normalized_failure_class = normalized_failure_class_for_constraint_shelf_mutation(
                "archive",
                "removed_from_shelf",
            );
            let next_action =
                constraint_shelf_mutation_next_action("archive", &normalized_failure_class);
            let mutation = ConstraintShelfMutationReceipt {
                mutation_id: chatty_factory_core::timestamp_id("constraint-shelf-mutation"),
                constraint_id: constraint_id.clone(),
                action: "archive".into(),
                proposal_origin: None,
                proposal_source_id: None,
                shelf_path: shelf_path.display().to_string(),
                status: "removed_from_shelf".into(),
                normalized_failure_class,
                recommended_next_action: next_action.action_id,
                recommended_next_step: next_action.recommended_next_step,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let mutation_path = mutation_root.join(format!(
                "archive-{}.json",
                sanitize_filename_like(constraint_id)
            ));
            persist_json_pretty(&mutation_path, &mutation)?;
        }

        let mut details = vec![
            format!("archived_constraints={}", archived_constraint_ids.len()),
            format!("shelf={}", shelf_path.display()),
            format!("history={}", history_path.display()),
        ];
        for constraint_id in archived_constraint_ids.iter().take(8) {
            details.push(format!("archived_constraint_id={constraint_id}"));
        }
        Ok(HostActionResult {
            summary: "Archived unmatched inactive constraints".into(),
            details,
            browser_state: None,
            runtime_refresh: None,
            execution_result: None,
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn deactivate_low_value_active_constraints(&self) -> Result<HostActionResult> {
        let shelf_path = self.runtime_root.join("approved_constraint_shelf.json");
        let mut shelf = load_approved_constraint_shelf(&shelf_path)?;
        let match_counts = approved_constraint_match_counts_from_runtime(&self.runtime_root);
        let deactivated_constraint_ids = shelf
            .constraints
            .iter()
            .filter(|constraint| {
                constraint.active
                    && match_counts
                        .get(&constraint.constraint_id)
                        .copied()
                        .unwrap_or_default()
                        == 0
            })
            .map(|constraint| constraint.constraint_id.clone())
            .collect::<Vec<_>>();
        if deactivated_constraint_ids.is_empty() {
            return Ok(HostActionResult {
                summary: "No low-value active constraints to deactivate".into(),
                details: vec![format!("shelf={}", shelf_path.display())],
                browser_state: None,
                runtime_refresh: None,
                execution_result: None,
                next_attempt_result: None,
                followup_route: None,
                extension_registry: None,
            });
        }

        for constraint in shelf.constraints.iter_mut() {
            if deactivated_constraint_ids
                .iter()
                .any(|constraint_id| constraint_id == &constraint.constraint_id)
            {
                constraint.active = false;
            }
        }
        shelf.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&shelf_path, &shelf)?;

        let mutation_root = self.runtime_root.join("constraint_shelf_mutations");
        for constraint_id in deactivated_constraint_ids.iter() {
            let normalized_failure_class = normalized_failure_class_for_constraint_shelf_mutation(
                "bulk_deactivate_low_value_active",
                "deactivated",
            );
            let next_action = constraint_shelf_mutation_next_action(
                "bulk_deactivate_low_value_active",
                &normalized_failure_class,
            );
            let mutation = ConstraintShelfMutationReceipt {
                mutation_id: chatty_factory_core::timestamp_id("constraint-shelf-mutation"),
                constraint_id: constraint_id.clone(),
                action: "bulk_deactivate_low_value_active".into(),
                proposal_origin: None,
                proposal_source_id: None,
                shelf_path: shelf_path.display().to_string(),
                status: "deactivated".into(),
                normalized_failure_class,
                recommended_next_action: next_action.action_id,
                recommended_next_step: next_action.recommended_next_step,
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            };
            let mutation_path = mutation_root.join(format!(
                "bulk-deactivate-{}.json",
                sanitize_filename_like(constraint_id)
            ));
            persist_json_pretty(&mutation_path, &mutation)?;
        }

        let mut details = vec![
            format!(
                "deactivated_constraints={}",
                deactivated_constraint_ids.len()
            ),
            format!("shelf={}", shelf_path.display()),
        ];
        for constraint_id in deactivated_constraint_ids.iter().take(8) {
            details.push(format!("deactivated_constraint_id={constraint_id}"));
        }
        Ok(HostActionResult {
            summary: "Deactivated low-value active constraints".into(),
            details,
            browser_state: None,
            runtime_refresh: None,
            execution_result: None,
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn restore_constraint_from_history(&self, constraint_id: &str) -> Result<HostActionResult> {
        let shelf_path = self.runtime_root.join("approved_constraint_shelf.json");
        let history_path = self.runtime_root.join("constraint_shelf_history.json");
        let mut shelf = load_approved_constraint_shelf(&shelf_path)?;
        let mut history = load_constraint_shelf_history(&history_path)?;
        let Some(entry_index) = history
            .archived_constraints
            .iter()
            .position(|entry| entry.constraint.constraint_id == constraint_id)
        else {
            anyhow::bail!(
                "archived approved constraint `{}` was not found in shelf history",
                constraint_id
            );
        };
        let entry = history.archived_constraints.remove(entry_index);
        if let Some(existing) = shelf
            .constraints
            .iter_mut()
            .find(|constraint| constraint.constraint_id == constraint_id)
        {
            *existing = entry.constraint.clone();
        } else {
            shelf.constraints.push(entry.constraint.clone());
        }
        shelf.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&shelf_path, &shelf)?;
        history.updated_at = Some(chatty_factory_core::timestamp_id("updated"));
        persist_json_pretty(&history_path, &history)?;

        let normalized_failure_class = normalized_failure_class_for_constraint_shelf_mutation(
            "restore",
            "restored_from_history",
        );
        let next_action =
            constraint_shelf_mutation_next_action("restore", &normalized_failure_class);
        let mutation = ConstraintShelfMutationReceipt {
            mutation_id: chatty_factory_core::timestamp_id("constraint-shelf-mutation"),
            constraint_id: constraint_id.to_string(),
            action: "restore".into(),
            proposal_origin: None,
            proposal_source_id: None,
            shelf_path: shelf_path.display().to_string(),
            status: "restored_from_history".into(),
            normalized_failure_class,
            recommended_next_action: next_action.action_id,
            recommended_next_step: next_action.recommended_next_step,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let mutation_path = self
            .runtime_root
            .join("constraint_shelf_mutations")
            .join(format!(
                "restore-{}.json",
                sanitize_filename_like(constraint_id)
            ));
        persist_json_pretty(&mutation_path, &mutation)?;

        Ok(HostActionResult {
            summary: "Restored approved constraint from shelf history".into(),
            details: vec![
                format!("constraint_id={constraint_id}"),
                format!("shelf={}", shelf_path.display()),
                format!("history={}", history_path.display()),
                format!("mutation_receipt={}", mutation_path.display()),
            ],
            browser_state: None,
            runtime_refresh: None,
            execution_result: None,
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn run_project_helpers(
        &self,
        project_name: &str,
        helper_id: Option<&str>,
    ) -> Result<HostActionResult> {
        let project_dir = self.output_root.join(project_name);
        let spec = load_project_spec_with_contract_refresh(&project_dir)?;
        let request_id = chatty_factory_core::timestamp_id("helper-run");
        let mut helper_runtime_receipts = execute_and_persist_helper_runtime_state(
            &self.runtime_root,
            &request_id,
            &project_dir,
            &spec,
        )?;
        if let Some(helper_id) = helper_id {
            helper_runtime_receipts.retain(|receipt| receipt.helper_id == helper_id);
        }
        Ok(HostActionResult {
            summary: "Project helpers executed".into(),
            details: helper_runtime_receipts
                .iter()
                .map(|receipt| {
                    format!(
                        "helper={} status={} outputs={}",
                        receipt.helper_id,
                        receipt.launch_status,
                        receipt.observed_output_files.join(",")
                    )
                })
                .collect(),
            browser_state: None,
            runtime_refresh: None,
            execution_result: Some(with_execution_outcome_posture(HostExecutionResult {
                kind: "helper_run".into(),
                request_id,
                project_name: project_name.to_string(),
                build_intent_freeze_path: None,
                outcome_class: Some("full_success".into()),
                outcome_notes: Vec::new(),
                recommended_next_action: None,
                recommended_next_step: String::new(),
                substrate_kind: Some("static_web".into()),
                tool_kind: spec.tool_kind.clone(),
                patch_kind: None,
                composition_route_class: None,
                composable_route_plan_path: None,
                composition_review_receipt_path: None,
                followup_request_mode: None,
                followup_rationale: Vec::new(),
                plan_confidence_score: 100,
                plan_confidence_band: "high".into(),
                needs_llm_review: false,
                acceptance_status: None,
                route_notes: vec!["bounded_helper_runner".into()],
                file_paths: helper_runtime_receipts
                    .iter()
                    .flat_map(|receipt| receipt.observed_output_files.clone())
                    .collect(),
                patch_lanes: spec.patch_lanes.clone(),
                acceptance_recipes: spec.acceptance_recipes.clone(),
                operator_bundles: spec.operator_bundles.clone(),
                chattycog_hosting_mode: spec.chattycog_hosting_mode.clone(),
                chattycog_ui_owner: spec.chattycog_ui_owner.clone(),
                chattycog_bridge_capabilities: spec.chattycog_bridge_capabilities.clone(),
                helper_services: spec.helper_services.clone(),
                helper_runtime_receipts,
            })),
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

    pub fn helper_status(
        &self,
        project_name: &str,
        helper_id: Option<&str>,
    ) -> Result<HostActionResult> {
        let project_dir = self.output_root.join(project_name);
        let spec = load_project_spec_with_contract_refresh(&project_dir)?;
        let mut details = Vec::new();
        let mut receipts = Vec::new();
        for helper in &spec.helper_services {
            if helper_id.is_some() && helper_id != Some(helper.helper_id.as_str()) {
                continue;
            }
            let status_path = helper
                .status_paths
                .first()
                .map(|path| project_dir.join(path))
                .unwrap_or_else(|| {
                    project_dir
                        .join("bridge")
                        .join("helpers")
                        .join(&helper.helper_id)
                        .join("status.json")
                });
            let status_summary = if status_path.exists() {
                let snapshot: chatty_factory_core::HelperStatusSnapshot =
                    serde_json::from_str(&fs::read_to_string(&status_path)?)?;
                details.push(format!(
                    "helper={} status={} summary={}",
                    helper.helper_id, snapshot.status, snapshot.summary
                ));
                snapshot.status
            } else {
                details.push(format!(
                    "helper={} status=missing_status_file",
                    helper.helper_id
                ));
                "missing_status_file".into()
            };
            receipts.push(HelperRuntimeReceipt {
                receipt_id: format!("helper-status-{}", helper.helper_id),
                request_id: "status-query".into(),
                helper_id: helper.helper_id.clone(),
                helper_kind: helper.helper_kind.clone(),
                attached_project_name: Some(project_name.to_string()),
                launch_status: status_summary,
                process_id: None,
                observed_status_files: helper.status_paths.clone(),
                observed_output_files: helper.output_paths.clone(),
                observed_primitive_ids: helper
                    .primitives
                    .iter()
                    .map(|primitive| primitive.primitive_id.clone())
                    .collect(),
                notes: vec!["Status loaded from project helper artifacts.".into()],
                created_at: Some(chatty_factory_core::timestamp_id("created")),
            });
        }
        Ok(HostActionResult {
            summary: "Project helper status".into(),
            details,
            browser_state: None,
            runtime_refresh: None,
            execution_result: Some(with_execution_outcome_posture(HostExecutionResult {
                kind: "helper_status".into(),
                request_id: "helper-status".into(),
                project_name: project_name.to_string(),
                build_intent_freeze_path: None,
                outcome_class: Some("partial_success".into()),
                outcome_notes: Vec::new(),
                recommended_next_action: None,
                recommended_next_step: String::new(),
                substrate_kind: Some(spec.substrate.clone()),
                tool_kind: spec.tool_kind.clone(),
                patch_kind: None,
                composition_route_class: None,
                composable_route_plan_path: None,
                composition_review_receipt_path: None,
                followup_request_mode: None,
                followup_rationale: Vec::new(),
                plan_confidence_score: 100,
                plan_confidence_band: "high".into(),
                needs_llm_review: false,
                acceptance_status: None,
                route_notes: vec!["helper_status_query".into()],
                file_paths: Vec::new(),
                patch_lanes: spec.patch_lanes.clone(),
                acceptance_recipes: spec.acceptance_recipes.clone(),
                operator_bundles: spec.operator_bundles.clone(),
                chattycog_hosting_mode: spec.chattycog_hosting_mode.clone(),
                chattycog_ui_owner: spec.chattycog_ui_owner.clone(),
                chattycog_bridge_capabilities: spec.chattycog_bridge_capabilities.clone(),
                helper_services: spec.helper_services.clone(),
                helper_runtime_receipts: receipts,
            })),
            next_attempt_result: None,
            followup_route: None,
            extension_registry: None,
        })
    }

