fn prune_processed_contract_covered_marker_checks(checks: &mut Vec<AcceptanceCheck>) -> bool {
    let has_files_contract = checks.iter().any(|check| {
        check.kind == "helper_processed_files_surface_contract" && check.target == "index.html"
    });
    let has_preview_contract = checks.iter().any(|check| {
        check.kind == "helper_processed_preview_surface_contract" && check.target == "index.html"
    });
    let has_selection_contract = checks.iter().any(|check| {
        check.kind == "helper_processed_selection_surface_contract" && check.target == "app.js"
    });

    let before_checks = checks.len();
    checks.retain(|check| {
        if has_files_contract && check.check_id == "processed-files-fetch-marker" {
            return false;
        }
        if has_preview_contract && check.check_id == "processed-file-preview-loader-marker" {
            return false;
        }
        if has_selection_contract
            && matches!(
                check.check_id.as_str(),
                "processed-file-selection-state"
                    | "processed-file-selection-handler"
                    | "processed-file-selection-preview"
                    | "processed-file-selection-style"
            )
        {
            return false;
        }
        true
    });
    checks.len() != before_checks
}

fn prune_redundant_processed_output_checks(checks: &mut Vec<AcceptanceCheck>) -> bool {
    let has_output_contract = checks.iter().any(|check| {
        check.kind == "helper_processed_output_contract"
            && check.target == "bridge/helpers/local_inbox/summary.json"
    });
    if !has_output_contract {
        return false;
    }

    let redundant_check_ids = [
        "processed-files-helper-output",
        "processed-file-preview-source",
    ];
    let before_checks = checks.len();
    checks.retain(|check| !redundant_check_ids.contains(&check.check_id.as_str()));
    checks.len() != before_checks
}

fn sync_helper_acceptance_expectations(
    project_dir: &Path,
    primitive_plan: Option<&PrimitiveExecutionPlan>,
) -> Result<()> {
    let acceptance_path = project_dir.join("AcceptancePlan.json");
    let spec_path = project_dir.join("ProjectSpec.json");
    if !acceptance_path.exists() || !spec_path.exists() {
        return Ok(());
    }

    let mut acceptance_plan: chatty_factory_core::AcceptancePlan =
        serde_json::from_str(&fs::read_to_string(&acceptance_path)?)?;
    let mut spec: ProjectSpec = serde_json::from_str(&fs::read_to_string(&spec_path)?)?;
    let spec_snapshot = spec.clone();
    let mut changed = false;

    for check in &mut acceptance_plan.checks {
        let derived =
            derive_helper_acceptance_expected(project_dir, &spec_snapshot, check, primitive_plan)?;
        if check.expected != derived {
            check.expected = derived;
            changed = true;
        }
    }

    for check in &mut spec.acceptance_checks {
        let derived =
            derive_helper_acceptance_expected(project_dir, &spec_snapshot, check, primitive_plan)?;
        if check.expected != derived {
            check.expected = derived;
            changed = true;
        }
    }

    changed |= inject_helper_summary_derived_checks(
        project_dir,
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    )?;
    changed |= inject_helper_summary_derived_checks(
        project_dir,
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    )?;
    changed |= sync_helper_processed_output_checks(
        project_dir,
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    )?;
    changed |= sync_helper_processed_output_checks(
        project_dir,
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    )?;
    changed |= inject_helper_summary_surface_contract_check(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    );
    changed |= inject_helper_summary_surface_contract_check(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_files_surface_contract_check(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_files_surface_contract_check(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_preview_surface_contract_check(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_preview_surface_contract_check(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_selection_surface_contract_check(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_selection_surface_contract_check(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_output_contract_check(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        primitive_plan,
    );
    changed |= inject_helper_processed_output_contract_check(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        primitive_plan,
    );
    changed |= prune_redundant_helper_summary_contains_checks(
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
    );
    changed |= prune_redundant_helper_summary_contains_checks(&mut spec.acceptance_checks, None);
    changed |= prune_redundant_helper_summary_surface_checks(
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
    );
    changed |= prune_redundant_helper_summary_surface_checks(&mut spec.acceptance_checks, None);
    changed |= prune_unapplied_processed_surface_checks(
        &spec_snapshot,
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
        primitive_plan,
    );
    changed |= prune_unapplied_processed_surface_checks(
        &spec_snapshot,
        &mut spec.acceptance_checks,
        None,
        primitive_plan,
    );
    changed |= prune_redundant_processed_files_surface_checks(
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
    );
    changed |= prune_redundant_processed_files_surface_checks(&mut spec.acceptance_checks, None);
    changed |= prune_redundant_processed_preview_surface_checks(
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
    );
    changed |= prune_redundant_processed_preview_surface_checks(&mut spec.acceptance_checks, None);
    changed |= prune_redundant_processed_selection_surface_checks(
        &mut acceptance_plan.checks,
        Some(&mut acceptance_plan.required_markers),
    );
    changed |=
        prune_redundant_processed_selection_surface_checks(&mut spec.acceptance_checks, None);
    changed |= prune_processed_contract_covered_marker_checks(&mut acceptance_plan.checks);
    changed |= prune_processed_contract_covered_marker_checks(&mut spec.acceptance_checks);
    changed |= prune_redundant_processed_output_checks(&mut acceptance_plan.checks);
    changed |= prune_redundant_processed_output_checks(&mut spec.acceptance_checks);

    if changed {
        persist_json_pretty(&acceptance_path, &acceptance_plan)?;
        persist_json_pretty(&spec_path, &spec)?;
    }

    Ok(())
}

fn run_execution_safety(
    runtime_root: &Path,
    request_id: &str,
    output_root: &Path,
    project_dir: &Path,
) -> Result<String> {
    let spec_path = project_dir.join("ProjectSpec.json");
    let spec: ProjectSpec = serde_json::from_str(&fs::read_to_string(&spec_path)?)?;
    let policy = build_execution_policy(
        request_id,
        output_root,
        project_dir,
        project_spec_substrate_kind_ref(&spec).as_ref(),
        spec.tool_kind.as_deref(),
        &spec.entrypoints,
    )?;
    persist_json_pretty(
        &runtime_root
            .join("execution_policies")
            .join(format!("{}-policy.json", request_id)),
        &policy,
    )?;
    let receipt = run_execution_policy(&policy)?;
    let status = receipt.status.clone();
    persist_json_pretty(
        &runtime_root
            .join("execution_receipts")
            .join(format!("{}-execution.json", request_id)),
        &receipt,
    )?;
    Ok(status)
}

fn persist_project_grounding(
    runtime_root: &Path,
    request_id: &str,
    project_dir: &Path,
) -> Result<()> {
    let spec_path = project_dir.join("ProjectSpec.json");
    let spec: ProjectSpec = serde_json::from_str(&fs::read_to_string(&spec_path)?)?;
    let snapshot = build_project_snapshot(project_dir, &spec)?;
    let context = build_context_bundle(request_id, &spec, &snapshot);
    persist_json_pretty(
        &runtime_root
            .join("project_snapshots")
            .join(format!("{}-snapshot.json", request_id)),
        &snapshot,
    )?;
    persist_json_pretty(
        &runtime_root
            .join("context_bundles")
            .join(format!("{}-context.json", request_id)),
        &context,
    )?;
    Ok(())
}

fn run_patch_snapshot_gate(
    runtime_root: &Path,
    request_id: &str,
    project_dir: &Path,
    spec: &ProjectSpec,
) -> Result<()> {
    let snapshot = build_project_snapshot(project_dir, spec)?;
    let context = build_context_bundle(request_id, spec, &snapshot);
    let gate = gate_patch_project_snapshot(request_id, &snapshot, spec)?;
    persist_json_pretty(
        &runtime_root
            .join("project_snapshots")
            .join(format!("{}-pre-patch-snapshot.json", request_id)),
        &snapshot,
    )?;
    persist_json_pretty(
        &runtime_root
            .join("context_bundles")
            .join(format!("{}-pre-patch-context.json", request_id)),
        &context,
    )?;
    persist_json_pretty(
        &runtime_root
            .join("snapshot_gates")
            .join(format!("{}-gate.json", request_id)),
        &gate,
    )?;
    if gate.status != "passed" {
        anyhow::bail!(
            "snapshot gate failed for project `{}`; missing grounded files: {}",
            spec.project_name,
            gate.missing_paths.join(", ")
        );
    }
    Ok(())
}

fn derive_project_patch_diagnosis(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    project_dir: &Path,
    spec: &ProjectSpec,
) -> Result<ProjectPatchDiagnosis> {
    let patch_surgical_maturity = patch_surgical_maturity_for_plan(spec, plan);
    let candidate_target_files =
        candidate_target_files_for_patch_diagnosis(project_dir, spec, &request.raw_request);
    let pre_patch_artifact_hashes =
        file_hashes_for_relative_paths(project_dir, &candidate_target_files);
    let candidate_insertion_points =
        candidate_insertion_points_for_patch_diagnosis(spec, &candidate_target_files);
    let diagnosed_artifact_groups =
        diagnosed_artifact_groups_for_patch_diagnosis(spec, &candidate_target_files);
    let declared_surface_groups = declared_surface_groups_for_patch_diagnosis(spec, plan);
    let expected_anchor_markers =
        expected_anchor_markers_for_patch_diagnosis(spec, plan, &candidate_target_files);
    let present_anchor_markers =
        present_anchor_markers_for_patch_diagnosis(project_dir, &expected_anchor_markers);
    let conflicting_anchor_markers = conflicting_anchor_markers_for_patch_diagnosis(spec, plan);
    let present_conflicting_anchor_markers =
        present_anchor_markers_for_patch_diagnosis(project_dir, &conflicting_anchor_markers);
    let structural_guard_source = structural_guard_source_for_patch_diagnosis(spec, plan);
    let preserve_invariants = preserve_invariants_for_patch_diagnosis(spec);
    let declared_ownership_boundaries =
        declared_ownership_boundaries_for_patch_diagnosis(spec, plan);
    let project_structure_notes = project_structure_notes_for_patch_diagnosis(
        spec,
        &diagnosed_artifact_groups,
        &declared_surface_groups,
        &declared_ownership_boundaries,
    );
    let risk_notes = risk_notes_for_patch_diagnosis(spec, &candidate_target_files);
    let post_patch_checks = vec![
        "project spec still exists".into(),
        "acceptance plan still exists".into(),
        "execution substrate remains stable".into(),
        "contract files stay synchronized with the repaired implementation".into(),
        "at least one diagnosed target file was modified".into(),
    ];

    Ok(ProjectPatchDiagnosis {
        diagnosis_id: chatty_factory_core::timestamp_id("patch-diagnosis"),
        request_id: request.request_id.clone(),
        project_name: spec.project_name.clone(),
        tool_kind: spec.tool_kind.clone(),
        substrate: spec.substrate.clone(),
        request_summary: plan.interpreted_goal.clone(),
        entrypoints: spec.entrypoints.clone(),
        expected_files: spec.expected_files.clone(),
        candidate_target_files,
        candidate_insertion_points,
        diagnosed_artifact_groups,
        declared_surface_groups,
        patch_surgical_maturity,
        expected_anchor_markers,
        present_anchor_markers,
        structural_guard_source,
        conflicting_anchor_markers,
        present_conflicting_anchor_markers,
        preserve_invariants,
        declared_ownership_boundaries,
        project_structure_notes,
        risk_notes,
        pre_patch_artifact_hashes,
        post_patch_checks,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    })
}

fn persist_project_patch_diagnosis(
    runtime_root: &Path,
    diagnosis: &ProjectPatchDiagnosis,
) -> Result<PathBuf> {
    let path = patch_diagnosis_path(runtime_root, &diagnosis.request_id);
    persist_json_pretty(&path, diagnosis)?;
    Ok(path)
}

fn derive_patch_intent_freeze(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    spec: &ProjectSpec,
    diagnosis: &ProjectPatchDiagnosis,
) -> PatchIntentFreeze {
    let candidate_patch_kinds = if !plan.planner_suggested_patch_kinds.is_empty() {
        plan.planner_suggested_patch_kinds.clone()
    } else if let Some(patch_kind) = &plan.intended_patch_kind {
        vec![patch_kind.clone()]
    } else {
        spec.supported_patch_kinds.clone()
    };

    let mut freeze_notes = Vec::new();
    if let Some(patch_kind) = &plan.intended_patch_kind {
        freeze_notes.push(format!(
            "bind interpreted patch intent `{patch_kind}` to diagnosed project surfaces"
        ));
    }
    if !diagnosis.candidate_target_files.is_empty() {
        freeze_notes.push(format!(
            "operate only within diagnosed candidate files: {}",
            diagnosis.candidate_target_files.join(", ")
        ));
    }
    if !diagnosis.preserve_invariants.is_empty() {
        freeze_notes.push(format!(
            "preserve diagnosis invariants: {}",
            diagnosis.preserve_invariants.join("; ")
        ));
    }
    if request.mode == Some(chatty_factory_core::RequestMode::Patch) {
        freeze_notes.push("freeze prepared before patch execution on an existing project".into());
    }

    if let Some(source) = &diagnosis.structural_guard_source {
        freeze_notes.push(format!("structural guard contract sourced from {source}"));
    }
    if !diagnosis.expected_anchor_markers.is_empty() {
        freeze_notes.push(format!(
            "required anchor markers: {}",
            diagnosis.expected_anchor_markers.join(", ")
        ));
    }
    if !diagnosis.present_conflicting_anchor_markers.is_empty() {
        freeze_notes.push(format!(
            "present conflicting markers: {}",
            diagnosis.present_conflicting_anchor_markers.join(", ")
        ));
    }
    if let Some(maturity) = &diagnosis.patch_surgical_maturity {
        freeze_notes.push(format!("lane surgical maturity: {maturity}"));
    }
    let superseded_by_patch_kinds = patch_superseded_replacements_for_plan(spec, plan);
    if !superseded_by_patch_kinds.is_empty() {
        freeze_notes.push(format!(
            "historical lane replacement path: {}",
            superseded_by_patch_kinds.join(", ")
        ));
    }
    let contract_confidence_summary =
        patch_contract_confidence_summary_for_freeze(diagnosis.patch_surgical_maturity.as_deref());
    let replacement_guidance_summary = if superseded_by_patch_kinds.is_empty() {
        None
    } else {
        Some(format!(
            "historical blocker with modern replacement guidance: use {}",
            superseded_by_patch_kinds.join(", ")
        ))
    };

    PatchIntentFreeze {
        freeze_id: chatty_factory_core::timestamp_id("patch-intent-freeze"),
        request_id: request.request_id.clone(),
        project_name: spec.project_name.clone(),
        substrate: spec.substrate.clone(),
        tool_kind: spec.tool_kind.clone(),
        interpreted_goal: plan.interpreted_goal.clone(),
        intended_patch_kind: plan.intended_patch_kind.clone(),
        candidate_patch_kinds,
        diagnosis_id: diagnosis.diagnosis_id.clone(),
        diagnosed_target_files: diagnosis.candidate_target_files.clone(),
        diagnosed_insertion_points: diagnosis.candidate_insertion_points.clone(),
        declared_surface_groups: diagnosis.declared_surface_groups.clone(),
        confirmed_surface_groups: diagnosis
            .declared_surface_groups
            .iter()
            .filter(|group| diagnosis.diagnosed_artifact_groups.contains_key(*group))
            .cloned()
            .collect(),
        patch_surgical_maturity: diagnosis.patch_surgical_maturity.clone(),
        superseded_by_patch_kinds,
        structural_guard_source: diagnosis.structural_guard_source.clone(),
        required_anchor_markers: diagnosis.expected_anchor_markers.clone(),
        confirmed_anchor_markers: diagnosis.present_anchor_markers.clone(),
        conflicting_anchor_markers: diagnosis.conflicting_anchor_markers.clone(),
        present_conflicting_anchor_markers: diagnosis.present_conflicting_anchor_markers.clone(),
        preserve_invariants: diagnosis.preserve_invariants.clone(),
        declared_ownership_boundaries: diagnosis.declared_ownership_boundaries.clone(),
        risk_notes: diagnosis.risk_notes.clone(),
        contract_confidence_summary,
        replacement_guidance_summary,
        freeze_notes,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn review_patch_intent_freeze(
    project_dir: &Path,
    _spec: &ProjectSpec,
    diagnosis: &ProjectPatchDiagnosis,
    freeze: &PatchIntentFreeze,
) -> (PatchPlanReview, PatchIntentFreeze) {
    let mut reviewed_freeze = freeze.clone();
    let mut findings = Vec::new();
    let mut blocked_reasons = Vec::new();
    let mut promoted_candidate_patch_kinds = Vec::new();
    let mut reviewed_replacement_bundle_patch_kinds = Vec::new();
    let mut reviewed_replacement_bundle_status = None;

    let original_target_files = freeze.diagnosed_target_files.clone();
    let original_insertion_points = freeze.diagnosed_insertion_points.clone();

    if !freeze.superseded_by_patch_kinds.is_empty() {
        for replacement in &freeze.superseded_by_patch_kinds {
            if !reviewed_freeze
                .candidate_patch_kinds
                .iter()
                .any(|kind| kind == replacement)
            {
                reviewed_freeze
                    .candidate_patch_kinds
                    .push(replacement.clone());
                promoted_candidate_patch_kinds.push(replacement.clone());
            }
        }
        if !promoted_candidate_patch_kinds.is_empty() {
            findings.push(format!(
                "self-review promoted modern replacement candidates into the frozen patch set: {}",
                promoted_candidate_patch_kinds.join(", ")
            ));
        }
    }

    if let Some(replacement_patch_kind) =
        redirect_replacement_patch_kind(project_dir, _spec, freeze)
    {
        if reviewed_freeze.intended_patch_kind.as_deref() != Some(replacement_patch_kind.as_str()) {
            findings.push(format!(
                "self-review redirected the surgical plan from `{}` to modern replacement `{}`",
                freeze
                    .intended_patch_kind
                    .as_deref()
                    .unwrap_or("unknown_patch"),
                replacement_patch_kind
            ));
            retarget_reviewed_freeze_to_patch_kind(
                project_dir,
                _spec,
                diagnosis,
                &mut reviewed_freeze,
                &replacement_patch_kind,
            );
        }
    }

    if let Some((selected_bundle_patch_kinds, bundle_status)) =
        reviewed_replacement_patch_bundle(project_dir, _spec, freeze)
    {
        let full_bundle = freeze.superseded_by_patch_kinds.join(", ");
        reviewed_replacement_bundle_patch_kinds = selected_bundle_patch_kinds;
        reviewed_replacement_bundle_status = Some(bundle_status.clone());
        match bundle_status.as_str() {
            "already_present" => findings.push(format!(
                "self-review confirmed the historical patch intent is already covered by the modern replacement bundle: {full_bundle}"
            )),
            "ready_for_composition" => findings.push(format!(
                "self-review redirected the historical patch intent into a modern replacement bundle: {full_bundle}"
            )),
            _ => {}
        }
    }

    if !freeze.declared_surface_groups.is_empty() {
        let narrowed_target_files = reviewed_target_files_for_declared_surface_groups(
            diagnosis,
            &freeze.declared_surface_groups,
        );
        if !narrowed_target_files.is_empty()
            && narrowed_target_files != reviewed_freeze.diagnosed_target_files
        {
            let dropped_target_files = reviewed_freeze
                .diagnosed_target_files
                .iter()
                .filter(|path| !narrowed_target_files.iter().any(|kept| kept == *path))
                .cloned()
                .collect::<Vec<_>>();
            reviewed_freeze.diagnosed_target_files = narrowed_target_files.clone();
            reviewed_freeze.diagnosed_insertion_points = reviewed_insertion_points_for_target_files(
                &reviewed_freeze.diagnosed_insertion_points,
                &narrowed_target_files,
            );
            findings.push(format!(
                "self-review narrowed the surgical file set to the declared patch surface groups: {}",
                freeze.declared_surface_groups.join(", ")
            ));
            if !dropped_target_files.is_empty() {
                findings.push(format!(
                    "self-review removed out-of-surface target files from the patch plan: {}",
                    dropped_target_files.join(", ")
                ));
            }
        }
    }

    if reviewed_freeze.diagnosed_target_files.is_empty() {
        blocked_reasons.push(
            "self-review eliminated every candidate target file while narrowing the plan to the declared patch surface contract"
                .into(),
        );
    }

    if !freeze.declared_surface_groups.is_empty()
        && reviewed_freeze.confirmed_surface_groups.is_empty()
    {
        blocked_reasons.push(
            "self-review could not confirm any declared patch surface groups, so the plan should not proceed unchanged"
                .into(),
        );
    }

    let decision = if !blocked_reasons.is_empty() {
        "blocked_pending_replan"
    } else if promoted_candidate_patch_kinds.is_empty()
        && reviewed_replacement_bundle_patch_kinds.is_empty()
        && reviewed_freeze.diagnosed_target_files == original_target_files
        && reviewed_freeze.diagnosed_insertion_points == original_insertion_points
    {
        "proceed_with_original_plan"
    } else {
        "proceed_with_refined_plan"
    };

    reviewed_freeze
        .freeze_notes
        .push(format!("self-review decision: {decision}"));
    for finding in &findings {
        reviewed_freeze
            .freeze_notes
            .push(format!("self-review finding: {finding}"));
    }
    for reason in &blocked_reasons {
        reviewed_freeze
            .freeze_notes
            .push(format!("self-review blocked reason: {reason}"));
    }
    let normalized_failure_class =
        normalized_failure_class_for_patch_plan_review(decision, &blocked_reasons);
    let next_action = patch_plan_review_next_action(decision, &normalized_failure_class);

    let review = PatchPlanReview {
        review_id: chatty_factory_core::timestamp_id("patch-plan-review"),
        request_id: freeze.request_id.clone(),
        project_name: freeze.project_name.clone(),
        diagnosis_id: diagnosis.diagnosis_id.clone(),
        freeze_id: freeze.freeze_id.clone(),
        original_intended_patch_kind: freeze.intended_patch_kind.clone(),
        reviewed_intended_patch_kind: reviewed_freeze.intended_patch_kind.clone(),
        decision: decision.into(),
        promoted_candidate_patch_kinds,
        original_target_files,
        reviewed_target_files: reviewed_freeze.diagnosed_target_files.clone(),
        dropped_target_files: freeze
            .diagnosed_target_files
            .iter()
            .filter(|path| {
                !reviewed_freeze
                    .diagnosed_target_files
                    .iter()
                    .any(|kept| kept == *path)
            })
            .cloned()
            .collect(),
        original_insertion_points,
        reviewed_insertion_points: reviewed_freeze.diagnosed_insertion_points.clone(),
        recommended_replacement_patch_kinds: freeze.superseded_by_patch_kinds.clone(),
        reviewed_replacement_bundle_patch_kinds,
        reviewed_replacement_bundle_status,
        normalized_failure_class,
        recommended_next_action: next_action.action_id.clone(),
        recommended_next_step: next_action.recommended_next_step.clone(),
        findings: {
            let mut findings = findings;
            findings.push(format!("mechanical next action: {}", next_action.action_id));
            findings.push(format!(
                "mechanical next step: {}",
                next_action.recommended_next_step
            ));
            findings.extend(next_action.rationale.clone());
            findings
        },
        blocked_reasons,
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };

    (review, reviewed_freeze)
}

fn derive_patch_implementation_constraints(
    project_dir: &Path,
    spec: &ProjectSpec,
    freeze: &PatchIntentFreeze,
) -> Vec<ImplementationConstraint> {
    let mut constraints = Vec::new();
    let Some(patch_kind) = freeze.intended_patch_kind.as_deref() else {
        return constraints;
    };
    let missing_required_markers =
        missing_required_anchor_markers(project_dir, &freeze.required_anchor_markers);
    let constraint_origin = freeze
        .structural_guard_source
        .clone()
        .unwrap_or_else(|| "patch_structural_guard".into());

    if !freeze.present_conflicting_anchor_markers.is_empty() {
        constraints.push(ImplementationConstraint {
            constraint_id: chatty_factory_core::timestamp_id("implementation-constraint"),
            constraint_scope: "family".into(),
            constraint_origin: constraint_origin.clone(),
            substrate_kind: project_spec_substrate_kind_ref(spec),
            tool_kind: spec.tool_kind.clone(),
            language_id: Some(spec.substrate.clone()),
            constraint_kind: "stale_structural_shape".into(),
            forbidden_method_summary: format!(
                "do not execute patch lane `{patch_kind}` through its stale legacy structural shape"
            ),
            forbidden_markers: freeze.present_conflicting_anchor_markers.clone(),
            required_markers: freeze.required_anchor_markers.clone(),
            forbidden_surface_groups: freeze.declared_surface_groups.clone(),
            violation_reason_template: format!(
                "patch lane `{patch_kind}` conflicts with evolved structural markers and should not run through its legacy method shape"
            ),
            replacement_guidance: freeze.replacement_guidance_summary.clone(),
            severity: "block".into(),
            active: true,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        });
    }

    if !missing_required_markers.is_empty() {
        constraints.push(ImplementationConstraint {
            constraint_id: chatty_factory_core::timestamp_id("implementation-constraint"),
            constraint_scope: "family".into(),
            constraint_origin,
            substrate_kind: project_spec_substrate_kind_ref(spec),
            tool_kind: spec.tool_kind.clone(),
            language_id: Some(spec.substrate.clone()),
            constraint_kind: "missing_required_legacy_anchor".into(),
            forbidden_method_summary: format!(
                "do not execute patch lane `{patch_kind}` when its required legacy anchors are missing"
            ),
            forbidden_markers: Vec::new(),
            required_markers: freeze.required_anchor_markers.clone(),
            forbidden_surface_groups: freeze.declared_surface_groups.clone(),
            violation_reason_template: format!(
                "patch lane `{patch_kind}` requires legacy anchors that are missing in the current project shape"
            ),
            replacement_guidance: freeze.replacement_guidance_summary.clone(),
            severity: "block".into(),
            active: true,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        });
    }

    constraints
}

fn missing_required_anchor_markers(project_dir: &Path, required_markers: &[String]) -> Vec<String> {
    if required_markers.is_empty() {
        return Vec::new();
    }
    let present = present_anchor_markers_for_patch_diagnosis(project_dir, required_markers);
    required_markers
        .iter()
        .filter(|marker| {
            !present
                .iter()
                .any(|present_marker| present_marker == *marker)
        })
        .cloned()
        .collect()
}

fn review_patch_implementation_constraints(
    project_dir: &Path,
    spec: &ProjectSpec,
    freeze: &PatchIntentFreeze,
    plan_review: &PatchPlanReview,
) -> ConstraintReviewReceipt {
    let selected_constraints = derive_patch_implementation_constraints(project_dir, spec, freeze);
    let mut violations = Vec::new();
    let mut blocked_methods = Vec::new();

    for constraint in &selected_constraints {
        let matched_markers = if constraint.forbidden_markers.is_empty() {
            Vec::new()
        } else {
            present_anchor_markers_for_patch_diagnosis(project_dir, &constraint.forbidden_markers)
        };
        let missing_required_markers =
            missing_required_anchor_markers(project_dir, &constraint.required_markers);
        if matched_markers.is_empty() && missing_required_markers.is_empty() {
            continue;
        }
        blocked_methods.push(constraint.forbidden_method_summary.clone());
        violations.push(ConstraintViolation {
            constraint_id: constraint.constraint_id.clone(),
            constraint_kind: constraint.constraint_kind.clone(),
            scope: constraint.constraint_scope.clone(),
            matched_markers,
            missing_required_markers,
            violated_surface_groups: constraint.forbidden_surface_groups.clone(),
            reason: constraint.violation_reason_template.clone(),
            replacement_guidance: constraint.replacement_guidance.clone(),
        });
    }

    let mut surviving_patch_kinds = Vec::new();
    if let Some(reviewed_patch_kind) = plan_review.reviewed_intended_patch_kind.clone() {
        surviving_patch_kinds.push(reviewed_patch_kind);
    }

    let surviving_composition_patch_kinds =
        plan_review.reviewed_replacement_bundle_patch_kinds.clone();
    let mut recommended_replacements = freeze.superseded_by_patch_kinds.clone();
    if recommended_replacements.is_empty() {
        recommended_replacements = plan_review.recommended_replacement_patch_kinds.clone();
    }

    let mut findings = Vec::new();
    let decision = if violations.is_empty() {
        findings.push("constraint review found no active forbidden implementation methods for the reviewed patch plan".into());
        "allow_current_plan"
    } else if plan_review.reviewed_replacement_bundle_status.as_deref() == Some("already_present") {
        findings.push("constraint review accepted the modern replacement bundle as already present, so execution should skip the historical method".into());
        "allow_bundle_already_present_skip"
    } else if !surviving_composition_patch_kinds.is_empty() {
        findings.push(format!(
            "constraint review preserved only the modern replacement bundle execution set: {}",
            surviving_composition_patch_kinds.join(", ")
        ));
        "allow_composed_replacement_bundle"
    } else if freeze.intended_patch_kind != plan_review.reviewed_intended_patch_kind
        && plan_review.reviewed_intended_patch_kind.is_some()
    {
        if let Some(reviewed_patch_kind) = plan_review.reviewed_intended_patch_kind.as_deref() {
            findings.push(format!(
                "constraint review rejected the original method and preserved the refined patch kind `{reviewed_patch_kind}`"
            ));
        }
        "allow_refined_patch_kind"
    } else {
        findings.push("constraint review found forbidden implementation methods and no surviving refined execution path".into());
        "block_execution"
    };
    let normalized_failure_class =
        normalized_failure_class_for_patch_constraint_review(decision, &violations);
    let next_action = patch_constraint_review_next_action(decision, &normalized_failure_class);

    ConstraintReviewReceipt {
        review_id: chatty_factory_core::timestamp_id("constraint-review"),
        request_id: freeze.request_id.clone(),
        project_name: freeze.project_name.clone(),
        substrate_kind: project_spec_substrate_kind_ref(spec),
        tool_kind: spec.tool_kind.clone(),
        review_subject: freeze
            .intended_patch_kind
            .clone()
            .unwrap_or_else(|| "patch_execution".into()),
        original_intended_patch_kind: freeze.intended_patch_kind.clone(),
        reviewed_intended_patch_kind: plan_review.reviewed_intended_patch_kind.clone(),
        selected_constraints,
        violations,
        surviving_patch_kinds,
        surviving_composition_patch_kinds,
        blocked_methods,
        recommended_replacements,
        normalized_failure_class,
        recommended_next_action: next_action.action_id.clone(),
        recommended_next_step: next_action.recommended_next_step.clone(),
        decision: decision.into(),
        findings: {
            findings.push(format!("mechanical next action: {}", next_action.action_id));
            findings.push(format!(
                "mechanical next step: {}",
                next_action.recommended_next_step
            ));
            findings.extend(next_action.rationale.clone());
            findings
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn constraint_review_block_reason(review: &ConstraintReviewReceipt) -> Option<String> {
    if review.decision != "block_execution" {
        return None;
    }
    let first_violation = review.violations.first()?;
    let mut reason = format!(
        "constraint review blocked execution: {}",
        first_violation.reason
    );
    if let Some(guidance) = &first_violation.replacement_guidance {
        reason.push_str(&format!("; {guidance}"));
    }
    Some(reason)
}

fn reviewed_target_files_for_declared_surface_groups(
    diagnosis: &ProjectPatchDiagnosis,
    declared_surface_groups: &[String],
) -> Vec<String> {
    let mut allowed = BTreeSet::new();
    for group_name in declared_surface_groups {
        if let Some(paths) = diagnosis.diagnosed_artifact_groups.get(group_name) {
            for path in paths {
                allowed.insert(path.clone());
            }
        }
    }
    diagnosis
        .candidate_target_files
        .iter()
        .filter(|path| allowed.contains(*path))
        .cloned()
        .collect()
}

fn reviewed_insertion_points_for_target_files(
    insertion_points: &[String],
    target_files: &[String],
) -> Vec<String> {
    insertion_points
        .iter()
        .filter(|point| {
            target_files.iter().any(|file| {
                point == &file.as_str()
                    || point.starts_with(&format!("{file} ->"))
                    || point.starts_with(&format!("{file}:"))
            })
        })
        .cloned()
        .collect()
}

fn redirect_replacement_patch_kind(
    project_dir: &Path,
    spec: &ProjectSpec,
    freeze: &PatchIntentFreeze,
) -> Option<String> {
    if freeze.superseded_by_patch_kinds.len() != 1 {
        return None;
    }
    if freeze.present_conflicting_anchor_markers.is_empty() {
        return None;
    }
    let replacement_patch_kind = freeze.superseded_by_patch_kinds.first()?.clone();
    let lane = spec
        .patch_lanes
        .iter()
        .find(|lane| lane.patch_kind == replacement_patch_kind)?;
    let readiness = lane.effective_preflight_readiness.as_str();
    if readiness != "ready" && readiness != "already_present" {
        return None;
    }
    let replacement_required_markers = patch_required_anchor_markers(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        &replacement_patch_kind,
    );
    if !replacement_required_markers.is_empty() {
        let present =
            present_anchor_markers_for_patch_diagnosis(project_dir, &replacement_required_markers);
        if !replacement_required_markers.iter().all(|marker| {
            present
                .iter()
                .any(|present_marker| present_marker == marker)
        }) {
            return None;
        }
    }
    Some(replacement_patch_kind)
}

fn reviewed_replacement_patch_bundle(
    project_dir: &Path,
    spec: &ProjectSpec,
    freeze: &PatchIntentFreeze,
) -> Option<(Vec<String>, String)> {
    if freeze.superseded_by_patch_kinds.len() < 2 {
        return None;
    }
    let original_patch_kind = freeze.intended_patch_kind.as_deref()?;
    let original_lane = spec
        .patch_lanes
        .iter()
        .find(|lane| lane.patch_kind == original_patch_kind)?;
    if original_lane.effective_preflight_readiness != "structurally_blocked"
        && freeze.present_conflicting_anchor_markers.is_empty()
    {
        return None;
    }

    let mut executable_bundle_patch_kinds = Vec::new();
    let mut all_already_present = true;
    for replacement_patch_kind in &freeze.superseded_by_patch_kinds {
        let lane = spec
            .patch_lanes
            .iter()
            .find(|lane| lane.patch_kind == *replacement_patch_kind)?;
        let readiness = lane.effective_preflight_readiness.as_str();
        if readiness != "ready" && readiness != "already_present" {
            return None;
        }
        let replacement_required_markers = patch_required_anchor_markers(
            project_spec_substrate_label(spec),
            spec.tool_kind.as_deref(),
            replacement_patch_kind,
        );
        if !replacement_required_markers.is_empty() {
            let present = present_anchor_markers_for_patch_diagnosis(
                project_dir,
                &replacement_required_markers,
            );
            if !replacement_required_markers.iter().all(|marker| {
                present
                    .iter()
                    .any(|present_marker| present_marker == marker)
            }) {
                return None;
            }
        }
        if readiness == "ready" {
            all_already_present = false;
            executable_bundle_patch_kinds.push(replacement_patch_kind.clone());
        }
    }

    if all_already_present {
        Some((Vec::new(), "already_present".into()))
    } else if executable_bundle_patch_kinds.is_empty() {
        None
    } else {
        Some((
            executable_bundle_patch_kinds,
            "ready_for_composition".into(),
        ))
    }
}

fn retarget_reviewed_freeze_to_patch_kind(
    project_dir: &Path,
    spec: &ProjectSpec,
    diagnosis: &ProjectPatchDiagnosis,
    freeze: &mut PatchIntentFreeze,
    patch_kind: &str,
) {
    freeze.intended_patch_kind = Some(patch_kind.to_string());

    let declared_surface_groups = patch_expected_artifact_groups(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    );
    if !declared_surface_groups.is_empty() {
        freeze.declared_surface_groups = declared_surface_groups;
    }
    freeze.confirmed_surface_groups = freeze
        .declared_surface_groups
        .iter()
        .filter(|group| diagnosis.diagnosed_artifact_groups.contains_key(*group))
        .cloned()
        .collect();

    let required_anchor_markers = patch_required_anchor_markers(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    );
    freeze.required_anchor_markers = required_anchor_markers.clone();
    freeze.confirmed_anchor_markers =
        present_anchor_markers_for_patch_diagnosis(project_dir, &required_anchor_markers);

    let conflicting_anchor_markers = patch_conflicting_anchor_markers(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    );
    freeze.conflicting_anchor_markers = conflicting_anchor_markers.clone();
    freeze.present_conflicting_anchor_markers =
        present_anchor_markers_for_patch_diagnosis(project_dir, &conflicting_anchor_markers);

    freeze.declared_ownership_boundaries = patch_ownership_boundaries(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    );
    freeze.patch_surgical_maturity = patch_surgical_maturity_for_kind(spec, patch_kind);
    freeze.structural_guard_source = structural_guard_source_for_patch_kind(spec, patch_kind);
    freeze.contract_confidence_summary =
        patch_contract_confidence_summary_for_freeze(freeze.patch_surgical_maturity.as_deref());
}

fn patch_superseded_replacements_for_plan(
    spec: &ProjectSpec,
    plan: &chatty_factory_core::RequestPlan,
) -> Vec<String> {
    let Some(patch_kind) = plan.intended_patch_kind.as_deref() else {
        return Vec::new();
    };
    spec.patch_lanes
        .iter()
        .find(|lane| lane.patch_kind == patch_kind)
        .map(|lane| lane.superseded_by_patch_kinds.clone())
        .unwrap_or_default()
}

fn patch_surgical_maturity_for_plan(
    spec: &ProjectSpec,
    plan: &chatty_factory_core::RequestPlan,
) -> Option<String> {
    let patch_kind = plan.intended_patch_kind.as_deref()?;
    let project_spec_maturity = spec
        .patch_lanes
        .iter()
        .find(|lane| lane.patch_kind == patch_kind)
        .map(|lane| lane.surgical_maturity.clone())
        .filter(|maturity| !maturity.trim().is_empty());
    if project_spec_maturity.is_some() {
        return project_spec_maturity;
    }
    chatty_factory_families::patch_surgical_maturity(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    )
}

fn patch_surgical_maturity_for_kind(spec: &ProjectSpec, patch_kind: &str) -> Option<String> {
    let project_spec_maturity = spec
        .patch_lanes
        .iter()
        .find(|lane| lane.patch_kind == patch_kind)
        .map(|lane| lane.surgical_maturity.clone())
        .filter(|maturity| !maturity.trim().is_empty());
    if project_spec_maturity.is_some() {
        return project_spec_maturity;
    }
    chatty_factory_families::patch_surgical_maturity(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    )
}

fn structural_guard_source_for_patch_kind(spec: &ProjectSpec, patch_kind: &str) -> Option<String> {
    let has_required = !patch_required_anchor_markers(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    )
    .is_empty();
    let has_conflicting = !patch_conflicting_anchor_markers(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    )
    .is_empty();
    let has_surface_groups = !patch_expected_artifact_groups(
        project_spec_substrate_label(spec),
        spec.tool_kind.as_deref(),
        patch_kind,
    )
    .is_empty();
    if has_required || has_conflicting || has_surface_groups {
        Some(format!(
            "patch_recipe_structural_guard:{}:{}",
            project_spec_substrate_label(spec).unwrap_or("unknown_substrate"),
            patch_kind
        ))
    } else {
        None
    }
}

