fn derive_build_next_attempt_failure_mode(
    summary: &str,
    request: &RequestRecord,
    plan: &RequestPlan,
) -> (&'static str, &'static str, FailureClass, &'static str) {
    if plan.inferred_substrate_candidates.is_empty() {
        (
            "no_deterministic_substrate_match",
            "do not force a nearest deterministic substrate when no bounded substrate candidate survives request interpretation",
            FailureClass::UnsupportedFamilyCapability,
            "deterministic_build_routing",
        )
    } else if plan.needs_llm_review {
        (
            "clarification_required_before_deterministic_build",
            "do not commit a deterministic build while interpreted goal or planner review remains unresolved",
            FailureClass::RouteSelectionMismatch,
            "deterministic_build_clarification",
        )
    } else if matches!(request.mode, Some(RequestMode::NewBuild))
        && summary.contains("Bounded composition review did not approve")
    {
        (
            "bounded_build_composition_review_denied",
            "do not execute a host-composed build work-order when bounded composition review rejected the layer set",
            FailureClass::StructuredCodeGenerationMismatch,
            "bounded_build_composition",
        )
    } else {
        (
            "deterministic_build_next_attempt_required",
            "do not pretend the current deterministic build route can satisfy this request without additional structure",
            FailureClass::BuildFailure,
            "deterministic_build_next_attempt",
        )
    }
}

fn derive_build_verification_receipt(
    runtime_root: &Path,
    request: &RequestRecord,
    plan: &RequestPlan,
    build_spec: &NextAttemptBuildSpec,
    reasons: &[String],
    summary: &str,
) -> BuildVerificationReceipt {
    let (failure_mode, blocked_method, failure_class, review_subject) =
        derive_build_next_attempt_failure_mode(summary, request, plan);
    let normalized_failure_class =
        normalized_failure_class_for_build_failure(&failure_class, failure_mode, summary);
    let next_action = select_mechanical_next_action(
        &normalized_failure_class,
        Some("build_failure_signature"),
        0,
        false,
    );
    let approved_constraints = matching_approved_build_constraints(
        runtime_root,
        review_subject,
        None,
        build_spec.suggested_tool_kind.as_deref(),
        failure_mode,
    );
    let mut findings = vec![summary.to_string()];
    if !build_spec.missing_base_build_primitive_classes.is_empty() {
        findings.push(format!(
            "missing family build primitive classes: {}",
            build_spec.missing_base_build_primitive_classes.join(", ")
        ));
    }
    if !build_spec.missing_patch_primitive_classes.is_empty() {
        findings.push(format!(
            "missing patch primitive classes: {}",
            build_spec.missing_patch_primitive_classes.join(", ")
        ));
    }
    if !build_spec.missing_helper_primitive_kinds.is_empty() {
        findings.push(format!(
            "missing helper primitive kinds: {}",
            build_spec.missing_helper_primitive_kinds.join(", ")
        ));
    }
    if !build_spec.recommended_next_step.trim().is_empty() {
        findings.push(format!(
            "recommended next step: {}",
            build_spec.recommended_next_step
        ));
    }
    findings.push(format!("mechanical next action: {}", next_action.action_id));
    findings.push(format!(
        "replacement guidance: {}",
        next_action.recommended_next_step
    ));
    findings.extend(next_action.rationale.clone());
    if !approved_constraints.is_empty() {
        findings.push(format!(
            "approved shelf already contains matching build constraints: {}",
            approved_constraints
                .iter()
                .map(|constraint| constraint.constraint_id.clone())
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    BuildVerificationReceipt {
        verification_id: chatty_factory_core::timestamp_id("build-verification"),
        request_id: request.request_id.clone(),
        review_subject: review_subject.to_string(),
        interpreted_goal: plan.interpreted_goal.clone(),
        candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
        suggested_substrate_kind: build_spec.suggested_substrate_kind.clone(),
        suggested_tool_kind: build_spec.suggested_tool_kind.clone(),
        next_attempt_kind: build_spec.next_attempt_kind.clone(),
        funnel_stage: build_spec.funnel_stage.clone(),
        next_attempt_mechanics: build_spec.next_attempt_mechanics.clone(),
        promoted_constraint_summaries: build_spec.promoted_constraint_summaries.clone(),
        failure_class: failure_class.clone(),
        normalized_failure_class,
        recommended_next_action: next_action.action_id,
        failure_mode: failure_mode.to_string(),
        matched_approved_constraint_ids: approved_constraints
            .iter()
            .map(|constraint| constraint.constraint_id.clone())
            .collect(),
        matched_approved_constraint_summaries: approved_constraints
            .iter()
            .map(|constraint| constraint.forbidden_method_summary.clone())
            .collect(),
        reasons: reasons.to_vec(),
        blocked_methods: vec![blocked_method.to_string()],
        findings,
        recommended_next_step: next_action.recommended_next_step,
        decision: if approved_constraints.is_empty() {
            "next_attempt_required".into()
        } else {
            "next_attempt_required_with_approved_constraint".into()
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}


fn is_soft_build_review_reason(reason: &str) -> bool {
    reason == "surface_unclear"
        || reason == "surface is not explicit in the request"
        || reason == "request_requires_helper_or_service_lane"
        || reason.starts_with("unsupported_explicit_stack:")
        || reason.starts_with("explicit stack `")
        || reason
            == "request asks for service/backend capabilities that do not have a bounded deterministic substrate yet"
}

fn should_continue_build_with_soft_review(plan: &RequestPlan) -> bool {
    if !matches!(plan.mode, Some(RequestMode::NewBuild)) {
        return false;
    }
    if !plan.needs_llm_review {
        return false;
    }
    if plan.inferred_substrate_candidates.is_empty() || plan.inferred_tool_kind.is_none() {
        return false;
    }
    if plan.constraints.is_empty() && plan.escalation_reasons.is_empty() {
        return false;
    }
    plan.constraints
        .iter()
        .all(|reason| is_soft_build_review_reason(reason))
        && plan
            .escalation_reasons
            .iter()
            .all(|reason| is_soft_build_review_reason(reason))
}

fn is_soft_patch_review_reason(reason: &str) -> bool {
    reason == "follow-up request did not match a known patch lane"
        || reason == "follow-up request asks for improvement without matching a concrete patch lane"
}

fn should_continue_patch_with_soft_review(plan: &RequestPlan, spec: &ProjectSpec) -> bool {
    if !matches!(plan.mode, Some(RequestMode::Patch)) {
        return false;
    }
    if !plan.needs_llm_review {
        return false;
    }
    if plan.inferred_substrate_candidates.is_empty() {
        return false;
    }
    if spec.supported_patch_kinds.is_empty() {
        return false;
    }
    if plan.intended_patch_kind.is_some() {
        return false;
    }
    if plan.escalation_reasons.is_empty() {
        return false;
    }
    plan.constraints.is_empty()
        && plan
            .escalation_reasons
            .iter()
            .all(|reason| is_soft_patch_review_reason(reason))
}

fn proposal_origin_and_source_id(proposal: &ProposedConstraintReceipt) -> (String, String) {
    if proposal.proposed_constraint.constraint_origin == "triangulated_task_failure" {
        (
            "triangulated_task_failure".into(),
            proposal.source_verification_id.clone(),
        )
    } else {
        (
            "build_verification_failure".into(),
            proposal.source_verification_id.clone(),
        )
    }
}

#[derive(Debug, Clone)]
struct BuildVerificationXray {
    task_shape: String,
    task_subtype: String,
    lineage_key: String,
    failure_class: String,
    trigger_class: Option<String>,
    attempt_method: String,
    narrow_usage_pattern: Vec<String>,
    findings: Vec<String>,
    recommended_constraint_summary: String,
}

fn extract_rust_error_codes(lines: &[String]) -> Vec<String> {
    let mut codes = Vec::new();
    for line in lines {
        let mut remaining = line.as_str();
        while let Some(index) = remaining.find("error[E") {
            let suffix = &remaining[index + "error[".len()..];
            if let Some(end) = suffix.find(']') {
                let code = &suffix[..end];
                if code.starts_with('E') && code.len() == 5 {
                    codes.push(code.to_string());
                }
                remaining = &suffix[end + 1..];
            } else {
                break;
            }
        }
    }
    codes.sort();
    codes.dedup();
    codes
}

fn extract_first_build_source_anchor(lines: &[String]) -> Option<String> {
    for line in lines {
        let trimmed = line.trim();
        if let Some(anchor) = trimmed.strip_prefix("--> ") {
            return Some(anchor.to_string());
        }
    }
    None
}

fn derive_build_verification_xray(
    verification: &BuildVerificationReceipt,
) -> BuildVerificationXray {
    let substrate = verification
        .suggested_substrate_kind
        .as_ref()
        .map(SubstrateKind::as_str)
        .unwrap_or("unknown_substrate");
    let tool = verification
        .suggested_tool_kind
        .as_deref()
        .unwrap_or("unknown_tool");
    let review_subject = verification.review_subject.as_str();
    let failure_mode = verification.failure_mode.as_str();
    let rust_error_codes = extract_rust_error_codes(&verification.reasons);
    let source_anchor = extract_first_build_source_anchor(&verification.reasons);
    let reason_blob = verification.reasons.join("\n").to_ascii_lowercase();
    let mut task_subtype = format!("{review_subject}:{failure_mode}");
    let mut findings = Vec::new();

    if !rust_error_codes.is_empty() {
        findings.push(format!("rust error codes: {}", rust_error_codes.join(", ")));
    }
    if let Some(anchor) = &source_anchor {
        findings.push(format!("source anchor: {anchor}"));
    }

    if failure_mode == "cargo_check_failed_after_build"
        && rust_error_codes
            .iter()
            .any(|code| code == "E0500" || code == "E0501")
        && reason_blob.contains("ui.columns")
    {
        task_subtype = "post_build_compile_contract:rust_borrow_conflict_in_columns_closure".into();
        findings.push(
            "xray narrowed the compile failure to a borrow conflict caused by using the outer egui ui handle inside a columns closure".into(),
        );
    } else if failure_mode == "cargo_check_failed_after_build"
        && rust_error_codes
            .iter()
            .any(|code| code == "E0500" || code == "E0501")
    {
        task_subtype = "post_build_compile_contract:rust_borrow_conflict".into();
        findings.push(
            "xray narrowed the compile failure to a Rust borrow conflict in emitted UI code".into(),
        );
    } else if failure_mode == "cargo_check_failed_after_build" && !rust_error_codes.is_empty() {
        task_subtype = format!(
            "post_build_compile_contract:rust_compile_error_codes:{}",
            rust_error_codes.join("+").to_ascii_lowercase()
        );
        findings.push(
            "xray narrowed the compile failure to a repeatable Rust compiler error-code pattern"
                .into(),
        );
    }

    let lineage_key = format!(
        "build-verification:{}:{}:{}:{}",
        substrate,
        tool,
        review_subject,
        sanitize_filename_like(&task_subtype)
    );
    let mut narrow_usage_pattern = vec![
        format!("substrate_kind={substrate}"),
        format!("tool_kind={tool}"),
        format!("review_subject={review_subject}"),
        format!("failure_mode={failure_mode}"),
        format!("task_subtype={task_subtype}"),
    ];
    if !rust_error_codes.is_empty() {
        narrow_usage_pattern.push(format!("rust_error_codes={}", rust_error_codes.join(",")));
    }
    if let Some(anchor) = &source_anchor {
        narrow_usage_pattern.push(format!("source_anchor={anchor}"));
    }

    let recommended_constraint_summary = if task_subtype
        == "post_build_compile_contract:rust_borrow_conflict_in_columns_closure"
    {
        "avoid emitting feature blocks against the outer egui `ui` handle from inside `ui.columns(...)` closures; repeated builds converge on a Rust borrow conflict in that exact posture".into()
    } else if task_subtype == "post_build_compile_contract:rust_borrow_conflict" {
        "avoid retrying the same emitted Rust UI ownership pattern without changing closure-local borrow posture; repeated builds converge on borrow-conflict compile failure".into()
    } else {
        format!(
                "avoid retrying the same generated build posture for `{}` under `{}` without changing method; repeated verification converges on the same narrow blocker",
                review_subject, failure_mode
            )
    };

    BuildVerificationXray {
        task_shape: "build_verification_failure".into(),
        task_subtype,
        lineage_key,
        failure_class: verification.normalized_failure_class.clone(),
        trigger_class: Some(review_subject.to_string()),
        attempt_method: format!("generated_build:{}:{}", substrate, tool),
        narrow_usage_pattern,
        findings,
        recommended_constraint_summary,
    }
}

fn derive_proposed_constraint_from_build_promotion_candidate(
    candidate: &ConstraintPromotionCandidate,
    verification: &BuildVerificationReceipt,
) -> ProposedConstraintReceipt {
    let subtype = candidate
        .task_subtype
        .clone()
        .unwrap_or_else(|| "unknown_build_failure_subtype".into());
    let failure_class_slug = sanitize_filename_like(&candidate.failure_class);
    ProposedConstraintReceipt {
        proposal_id: chatty_factory_core::timestamp_id("constraint-proposal"),
        request_id: candidate.request_id.clone(),
        source_verification_id: candidate.triangulation_session_id.clone(),
        status: "proposed_unapproved".into(),
        rationale: {
            let mut rationale = candidate.findings.clone();
            rationale.extend(candidate.narrow_usage_pattern.clone());
            rationale.push(format!(
                "confidence posture: {}",
                candidate.confidence_posture
            ));
            rationale
        },
        proposed_constraint: ImplementationConstraint {
            constraint_id: format!(
                "triangulated-build-constraint:{}:{}:{}",
                sanitize_filename_like(&verification.review_subject),
                sanitize_filename_like(&subtype),
                failure_class_slug
            ),
            constraint_scope: format!(
                "triangulated_build_failure:{}",
                verification.review_subject
            ),
            constraint_origin: "triangulated_task_failure".into(),
            substrate_kind: verification.suggested_substrate_kind.clone(),
            tool_kind: verification.suggested_tool_kind.clone(),
            language_id: Some("rust".into()),
            constraint_kind: candidate.failure_class.clone(),
            forbidden_method_summary: candidate.recommended_constraint_summary.clone(),
            forbidden_markers: Vec::new(),
            required_markers: Vec::new(),
            forbidden_surface_groups: Vec::new(),
            violation_reason_template: candidate
                .findings
                .first()
                .cloned()
                .unwrap_or_else(|| {
                    "repeated build-verification triangulation converged on the same narrow blocker"
                        .into()
                }),
            replacement_guidance: Some(
                "change emitted method or helper posture before retrying the exact same narrowed build pattern; the current usage pattern keeps failing verification".into(),
            ),
            severity: "error".into(),
            active: false,
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    }
}

fn record_build_verification_triangulation(
    runtime_root: &Path,
    request: &RequestRecord,
    verification: &BuildVerificationReceipt,
    verification_path: &Path,
) -> Result<(
    Vec<PathBuf>,
    Option<ProposedConstraintReceipt>,
    Option<PathBuf>,
)> {
    let xray = derive_build_verification_xray(verification);
    let vault_root = runtime_root.join("failure_vault");
    let prior_entries = load_failure_vault_entries_for_lineage(&vault_root, &xray.lineage_key);
    let session_id = format!(
        "triangulation-{}",
        sanitize_filename(&format!("{}-{}", request.request_id, xray.lineage_key))
    );
    let mut paths = Vec::new();
    let floor_root = runtime_root.join("atomization_floor_decisions");
    let floor_decision = AtomizationFloorDecision {
        decision_id: chatty_factory_core::timestamp_id("atomization-floor"),
        request_id: request.request_id.clone(),
        task_id: format!("build-verification:{}", verification.verification_id),
        project_name: request
            .active_project
            .clone()
            .unwrap_or_else(|| "generated_build".into()),
        task_shape: Some(xray.task_shape.clone()),
        task_subtype: Some(xray.task_subtype.clone()),
        current_granularity: "build_failure_signature".into(),
        decision: "at_floor".into(),
        alternate_methods: vec![
            "retry_generation_with_changed_ui_ownership_posture".into(),
            "retry_generation_with_anchor_locality_shift".into(),
            "retry_generation_after_xray_signature_review".into(),
        ],
        findings: xray.findings.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let floor_path = persist_atomization_floor_decision(&floor_root, &floor_decision)?;
    paths.push(floor_path.clone());

    let prior_same_failure_count = prior_entries
        .iter()
        .filter(|entry| {
            entry.failure_class == xray.failure_class && entry.status == "provisional_open"
        })
        .count();
    let mut distinct_attempt_methods = prior_entries
        .iter()
        .filter(|entry| {
            entry.failure_class == xray.failure_class && entry.status == "provisional_open"
        })
        .filter_map(|entry| entry.attempt_method.clone())
        .collect::<std::collections::BTreeSet<_>>();
    distinct_attempt_methods.insert(xray.attempt_method.clone());
    let next_action = select_mechanical_next_action(
        &xray.failure_class,
        Some("build_failure_signature"),
        prior_same_failure_count,
        distinct_attempt_methods.len() >= 2,
    );

    let vault_entry = FailureVaultEntry {
        vault_entry_id: chatty_factory_core::timestamp_id("failure-vault"),
        request_id: request.request_id.clone(),
        task_id: format!("build-verification:{}", verification.verification_id),
        project_name: request
            .active_project
            .clone()
            .unwrap_or_else(|| "generated_build".into()),
        task_shape: Some(xray.task_shape.clone()),
        task_subtype: Some(xray.task_subtype.clone()),
        task_kind: "build_verification".into(),
        failure_class: xray.failure_class.clone(),
        trigger_class: xray.trigger_class.clone(),
        triangulation_session_id: session_id.clone(),
        atomization_floor_decision_path: Some(floor_path.display().to_string()),
        attempt_method: Some(xray.attempt_method.clone()),
        source_attempt_receipt_path: verification_path.display().to_string(),
        source_decomposition_receipt_path: None,
        status: "provisional_open".into(),
        decomposition_depth: 0,
        narrow_usage_pattern: xray.narrow_usage_pattern.clone(),
        findings: {
            let mut findings = xray.findings.clone();
            findings.push(format!("mechanical next action: {}", next_action.action_id));
            findings.push(format!(
                "mechanical next step: {}",
                next_action.recommended_next_step
            ));
            findings.extend(next_action.rationale.clone());
            findings
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let vault_path = persist_failure_vault_entry(&vault_root, &vault_entry)?;
    paths.push(vault_path.clone());

    let triangulation_root = runtime_root.join("triangulation_sessions");
    let alternate_method_evidence_present = distinct_attempt_methods.len() >= 2;
    let session = TriangulationSession {
        session_id: session_id.clone(),
        request_id: request.request_id.clone(),
        project_name: vault_entry.project_name.clone(),
        task_shape: Some(xray.task_shape.clone()),
        task_subtype: Some(xray.task_subtype.clone()),
        task_lineage_key: xray.lineage_key.clone(),
        status: "provisional_open".into(),
        convergence_posture: if prior_same_failure_count >= 1 && alternate_method_evidence_present {
            "repeated_convergent_failure".into()
        } else if prior_same_failure_count >= 1 {
            "repeated_same_method_needs_alternate_retry".into()
        } else {
            "single_observation".into()
        },
        atomization_floor_decision_path: Some(floor_path.display().to_string()),
        successful_alternate_method: false,
        attempts: vec![TriangulationAttempt {
            attempt_id: verification.verification_id.clone(),
            task_id: vault_entry.task_id.clone(),
            task_subtype: Some(xray.task_subtype.clone()),
            attempt_method: xray.attempt_method.clone(),
            outcome: verification.failure_mode.clone(),
            failure_class: Some(xray.failure_class.clone()),
            source_attempt_receipt_path: Some(verification_path.display().to_string()),
            source_decomposition_receipt_path: None,
        }],
        findings: {
            let mut findings = xray.findings.clone();
            findings.push(format!(
                "same-failure observations for lineage so far: {}",
                prior_same_failure_count
            ));
            findings.push(format!(
                "distinct attempt methods observed so far: {}",
                distinct_attempt_methods.len()
            ));
            findings.push(format!("mechanical next action: {}", next_action.action_id));
            findings.push(format!(
                "mechanical next step: {}",
                next_action.recommended_next_step
            ));
            findings.extend(next_action.rationale.clone());
            if prior_same_failure_count >= 1 && !alternate_method_evidence_present {
                findings.push(
                    "promotion is intentionally blocked until the same narrow failure has been observed under a changed retry method or posture".into(),
                );
            }
            findings
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let triangulation_path = persist_triangulation_session(&triangulation_root, &session)?;
    paths.push(triangulation_path.clone());

    let mut proposal = None;
    let mut proposal_path = None;
    if prior_same_failure_count >= 1 && alternate_method_evidence_present {
        let promotion_root = runtime_root.join("constraint_promotion_candidates");
        let candidate = ConstraintPromotionCandidate {
            candidate_id: chatty_factory_core::timestamp_id("constraint-promotion"),
            request_id: request.request_id.clone(),
            triangulation_session_id: session_id,
            project_name: vault_entry.project_name.clone(),
            task_shape: Some(xray.task_shape.clone()),
            task_subtype: Some(xray.task_subtype.clone()),
            failure_class: xray.failure_class.clone(),
            trigger_class: xray.trigger_class.clone(),
            confidence_posture: "triangulated_build_verification_repeated_failure".into(),
            status: "proposed_for_review".into(),
            matched_constraint_principles: vec![
                "do_not_promote_one_off_failures".into(),
                "classify_failure_before_proceeding".into(),
                "retry_with_alternate_method_before_promotion".into(),
            ],
            narrow_usage_pattern: xray.narrow_usage_pattern.clone(),
            evidence_receipt_paths: vec![
                verification_path.display().to_string(),
                vault_path.display().to_string(),
                triangulation_path.display().to_string(),
            ],
            findings: {
                let mut findings = xray.findings.clone();
                findings.push(
                    "promotion candidate was created only after repeated convergent build-verification failures on the same narrow signature".into(),
                );
                findings
            },
            recommended_constraint_summary: xray.recommended_constraint_summary.clone(),
            created_at: Some(chatty_factory_core::timestamp_id("created")),
        };
        let promotion_path = persist_constraint_promotion_candidate(&promotion_root, &candidate)?;
        paths.push(promotion_path);
        let proposed_constraint =
            derive_proposed_constraint_from_build_promotion_candidate(&candidate, verification);
        let persisted_proposal_path =
            persist_trianguated_proposed_constraint_receipt(runtime_root, &proposed_constraint)?;
        paths.push(persisted_proposal_path.clone());
        proposal = Some(proposed_constraint);
        proposal_path = Some(persisted_proposal_path);
    }

    let summary_path = refresh_triangulation_loop_summary(runtime_root)?;
    paths.push(summary_path);
    Ok((paths, proposal, proposal_path))
}

fn persist_build_verification_receipt(
    runtime_root: &Path,
    receipt: &BuildVerificationReceipt,
) -> Result<PathBuf> {
    let path = runtime_root
        .join("build_verification_receipts")
        .join(format!("{}-build-verification.json", receipt.request_id));
    persist_json_pretty(&path, receipt)?;
    Ok(path)
}

fn resolve_proposed_constraint_path(
    runtime_root: &Path,
    request_id_or_path: &str,
) -> Result<PathBuf> {
    let candidate = PathBuf::from(request_id_or_path);
    if candidate.exists() {
        return Ok(candidate);
    }
    let path = runtime_root
        .join("proposed_constraint_receipts")
        .join(format!("{request_id_or_path}-proposed-constraint.json"));
    if path.exists() {
        Ok(path)
    } else {
        anyhow::bail!(
            "proposed constraint receipt `{}` was not found as a direct path or runtime receipt id",
            request_id_or_path
        )
    }
}

fn load_approved_constraint_shelf(path: &Path) -> Result<ApprovedConstraintShelf> {
    if path.exists() {
        Ok(serde_json::from_str(&fs::read_to_string(path)?)?)
    } else {
        Ok(ApprovedConstraintShelf {
            shelf_id: "approved-negative-constraint-shelf".into(),
            constraints: Vec::new(),
            updated_at: Some(chatty_factory_core::timestamp_id("created")),
        })
    }
}

fn load_constraint_shelf_history(path: &Path) -> Result<ConstraintShelfHistory> {
    if path.exists() {
        Ok(serde_json::from_str(&fs::read_to_string(path)?)?)
    } else {
        Ok(ConstraintShelfHistory {
            history_id: "approved-negative-constraint-shelf-history".into(),
            archived_constraints: Vec::new(),
            updated_at: Some(chatty_factory_core::timestamp_id("created")),
        })
    }
}

fn sanitize_filename_like(value: &str) -> String {
    value
        .chars()
        .map(|ch| match ch {
            'a'..='z' | 'A'..='Z' | '0'..='9' | '-' | '_' => ch,
            _ => '_',
        })
        .collect()
}

fn load_active_approved_constraints(runtime_root: &Path) -> Result<Vec<ImplementationConstraint>> {
    let shelf =
        load_approved_constraint_shelf(&runtime_root.join("approved_constraint_shelf.json"))?;
    Ok(shelf
        .constraints
        .into_iter()
        .filter(|constraint| constraint.active)
        .collect())
}

fn matches_optional_str(expected: Option<&str>, actual: Option<&str>) -> bool {
    match expected {
        Some(expected) => actual == Some(expected),
        None => true,
    }
}

fn matches_optional_substrate(
    expected: Option<&SubstrateKind>,
    actual: Option<&SubstrateKind>,
) -> bool {
    match expected {
        Some(expected) => actual == Some(expected),
        None => true,
    }
}

fn matching_approved_build_constraints(
    runtime_root: &Path,
    review_subject: &str,
    substrate_kind: Option<&SubstrateKind>,
    tool_kind: Option<&str>,
    failure_mode: &str,
) -> Vec<ImplementationConstraint> {
    load_active_approved_constraints(runtime_root)
        .unwrap_or_default()
        .into_iter()
        .filter(|constraint| constraint.constraint_scope == review_subject)
        .filter(|constraint| constraint.constraint_kind == failure_mode)
        .filter(|constraint| {
            matches_optional_substrate(constraint.substrate_kind.as_ref(), substrate_kind)
        })
        .filter(|constraint| matches_optional_str(constraint.tool_kind.as_deref(), tool_kind))
        .collect()
}

fn approved_constraint_match_counts_from_runtime(runtime_root: &Path) -> BTreeMap<String, usize> {
    let receipts_root = runtime_root.join("build_verification_receipts");
    let Ok(entries) = fs::read_dir(receipts_root) else {
        return BTreeMap::new();
    };
    let mut counts = BTreeMap::new();
    for entry in entries.flatten() {
        let path = entry.path();
        let Some(extension) = path.extension().and_then(|value| value.to_str()) else {
            continue;
        };
        if extension != "json" {
            continue;
        }
        let Ok(contents) = fs::read_to_string(&path) else {
            continue;
        };
        let Ok(receipt) = serde_json::from_str::<BuildVerificationReceipt>(&contents) else {
            continue;
        };
        for constraint_id in receipt.matched_approved_constraint_ids {
            *counts.entry(constraint_id).or_insert(0) += 1;
        }
    }
    counts
}

fn load_existing_build_verification_receipt(
    runtime_root: &Path,
    request_id: &str,
) -> Option<(BuildVerificationReceipt, PathBuf)> {
    let path = runtime_root
        .join("build_verification_receipts")
        .join(format!("{request_id}-build-verification.json"));
    let contents = fs::read_to_string(&path).ok()?;
    let receipt = serde_json::from_str::<BuildVerificationReceipt>(&contents).ok()?;
    Some((receipt, path))
}

fn load_existing_proposed_constraint_receipt(
    runtime_root: &Path,
    request_id: &str,
) -> Option<(ProposedConstraintReceipt, PathBuf)> {
    let path = runtime_root
        .join("proposed_constraint_receipts")
        .join(format!("{request_id}-proposed-constraint.json"));
    let contents = fs::read_to_string(&path).ok()?;
    let receipt = serde_json::from_str::<ProposedConstraintReceipt>(&contents).ok()?;
    Some((receipt, path))
}

fn load_proposed_constraint_receipt_for_source_verification(
    runtime_root: &Path,
    source_verification_id: &str,
) -> Option<(ProposedConstraintReceipt, PathBuf)> {
    let root = runtime_root.join("proposed_constraint_receipts");
    let paths = fs::read_dir(root).ok()?;
    for entry in paths.flatten() {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let contents = fs::read_to_string(&path).ok()?;
        let receipt = serde_json::from_str::<ProposedConstraintReceipt>(&contents).ok()?;
        if receipt.source_verification_id == source_verification_id {
            return Some((receipt, path));
        }
    }
    None
}

fn persist_post_build_failure_learning(
    runtime_root: &Path,
    request: &RequestRecord,
    plan: &RequestPlan,
    project_name: &str,
    substrate_kind: Option<SubstrateKind>,
    tool_kind: Option<&str>,
    next_attempt_kind: &str,
    failure_mode: &str,
    blocked_method: &str,
    summary: &str,
) -> Result<(
    BuildVerificationReceipt,
    PathBuf,
    Option<ProposedConstraintReceipt>,
    Option<PathBuf>,
)> {
    let failure_class = classify_failure(summary);
    let (review_subject, specific_failure_mode, specific_blocked_method) =
        derive_post_build_failure_details(failure_mode, blocked_method, summary);
    let normalized_failure_class =
        normalized_failure_class_for_build_failure(&failure_class, &specific_failure_mode, summary);
    let next_action = select_mechanical_next_action(
        &normalized_failure_class,
        Some("build_failure_signature"),
        0,
        false,
    );
    let approved_constraints = matching_approved_build_constraints(
        runtime_root,
        &review_subject,
        substrate_kind.as_ref(),
        tool_kind,
        &specific_failure_mode,
    );
    let verification = BuildVerificationReceipt {
        verification_id: chatty_factory_core::timestamp_id("build-verification"),
        request_id: request.request_id.clone(),
        review_subject: review_subject.to_string(),
        interpreted_goal: plan.interpreted_goal.clone(),
        candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
        suggested_substrate_kind: substrate_kind.clone(),
        suggested_tool_kind: tool_kind.map(str::to_string),
        next_attempt_kind: next_attempt_kind.to_string(),
        funnel_stage: "post_build_failure_classification".into(),
        next_attempt_mechanics: vec![
            "fail_honestly_against_the_frozen_intent".into(),
            "classify_post_build_failure_before_any_retry".into(),
            "promote_constraints_from_post_build_receipts".into(),
            "retry_with_a_specific_mechanical_delta_instead_of_substituting_artifact_shape".into(),
            "compare_against_prior_verification_receipts_before_changing_method_or_model".into(),
        ],
        promoted_constraint_summaries: plan.constraints.clone(),
        failure_class: failure_class.clone(),
        normalized_failure_class,
        recommended_next_action: next_action.action_id.clone(),
        failure_mode: specific_failure_mode.to_string(),
        matched_approved_constraint_ids: approved_constraints
            .iter()
            .map(|constraint| constraint.constraint_id.clone())
            .collect(),
        matched_approved_constraint_summaries: approved_constraints
            .iter()
            .map(|constraint| constraint.forbidden_method_summary.clone())
            .collect(),
        reasons: vec![summary.to_string()],
        blocked_methods: vec![specific_blocked_method.to_string()],
        findings: {
            let mut findings = vec![
                format!("project_name={project_name}"),
                format!(
                    "substrate_kind={}",
                    substrate_kind
                        .as_ref()
                        .map(chatty_factory_core::SubstrateKind::as_str)
                        .unwrap_or("unknown_substrate")
                ),
                "built artifacts exist but host verification did not approve them".into(),
                format!(
                    "mechanical next step: {}",
                    next_action.recommended_next_step
                ),
            ];
            findings.extend(next_action.rationale.clone());
            if !approved_constraints.is_empty() {
                findings.push(format!(
                    "approved shelf already contains matching build constraints: {}",
                    approved_constraints
                        .iter()
                        .map(|constraint| constraint.constraint_id.clone())
                        .collect::<Vec<_>>()
                        .join(", ")
                ));
            }
            findings
        },
        recommended_next_step: next_action.recommended_next_step,
        decision: if approved_constraints.is_empty() {
            "next_attempt_required_after_build_verification".into()
        } else {
            "next_attempt_required_after_build_verification_with_approved_constraint".into()
        },
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let verification_path = persist_build_verification_receipt(runtime_root, &verification)?;
    let (_triangulation_paths, proposed_constraint, proposed_constraint_path) =
        record_build_verification_triangulation(
            runtime_root,
            request,
            &verification,
            &verification_path,
        )?;
    Ok((
        verification,
        verification_path,
        proposed_constraint,
        proposed_constraint_path,
    ))
}

fn derive_post_build_failure_details(
    broad_failure_mode: &str,
    default_blocked_method: &str,
    summary: &str,
) -> (String, String, String) {
    let lower = summary.to_ascii_lowercase();
    if lower.contains("missing main.py")
        || lower.contains("missing main.rs")
        || lower.contains("missing index.html")
        || lower.contains("missing src/main.rs")
    {
        (
            "post_build_entrypoint_contract".into(),
            "missing_entrypoint_after_build".into(),
            "do not mark a generated build as shippable when its primary entrypoint is missing after build-seed emission".into(),
        )
    } else if lower.contains("chattycog module contract failed")
        || lower.contains("chattycog visual load contract failed")
        || lower.contains("chattycog bridge contract failed")
    {
        (
            "post_build_chattycog_contract".into(),
            "chattycog_contract_failed_after_build".into(),
            "do not ship a chattycog build when module, bridge, or visual-load contract artifacts are incomplete or inconsistent".into(),
        )
    } else if lower.contains("helper summary surface contract failed")
        || lower.contains("helper processed")
        || lower.contains("helper service spec")
        || lower.contains("helper status snapshot")
        || lower.contains("helper summary snapshot")
    {
        (
            "post_build_helper_contract".into(),
            "helper_contract_failed_after_build".into(),
            "do not ship a generated helper-backed build when helper contracts or surfaced helper artifacts fail verification".into(),
        )
    } else if lower.contains("cargo check failed") {
        (
            "post_build_compile_contract".into(),
            "cargo_check_failed_after_build".into(),
            "do not accept a generated rust build when cargo check fails after build-seed emission"
                .into(),
        )
    } else if lower.contains("cargo run failed") {
        (
            "post_build_execution_smoke".into(),
            "cargo_run_failed_after_build".into(),
            "do not ship a generated rust build when cargo run fails during execution smoke".into(),
        )
    } else if lower.contains("unable to execute python command")
        || lower.contains("not found in python output")
    {
        (
            "post_build_execution_smoke".into(),
            "python_execution_failed_after_build".into(),
            "do not ship a generated python build when the primary python execution path fails during verification".into(),
        )
    } else {
        let review_subject = if broad_failure_mode == "execution_smoke_failed_after_build" {
            "post_build_execution_smoke"
        } else {
            "post_build_verification"
        };
        (
            review_subject.into(),
            broad_failure_mode.to_string(),
            default_blocked_method.to_string(),
        )
    }
}

fn emit_next_attempt_result(
    runtime_root: &Path,
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    active_spec: Option<&ProjectSpec>,
    summary: &str,
) -> Result<HostActionResult> {
    let next_attempt_shape = derive_chattycog_next_attempt_shape(request, plan);
    let composition_route_class =
        derive_composition_route_class(request, plan, active_spec, Some(&next_attempt_shape), false);
    let composable_route_plan = derive_composable_route_plan(
        request,
        plan,
        active_spec,
        None,
        composition_route_class.clone(),
        &[],
    );
    let composable_route_plan_path =
        persist_composable_route_plan(runtime_root, &composable_route_plan)?;
    let mut reasons = dedup_strings(plan.escalation_reasons.clone());
    let constraints = dedup_strings(plan.constraints.clone());
    let promoted_constraint_summaries = constraints.clone();
    let extension_shape =
        derive_next_attempt_extension_shape(request, plan, active_spec, &next_attempt_shape);
    let funnel_stage = next_attempt_funnel_stage(request, plan, &next_attempt_shape);
    let next_attempt_mechanics =
        next_attempt_mechanics_list(request, plan, &next_attempt_shape);
    let comparison_seed_recommendation = if extension_shape.extension_kind == "proof_harness_bundle" {
        closest_built_in_comparison_seed(
            &NextAttemptBuildSpec {
                next_attempt_spec_id: String::new(),
                request_id: request.request_id.clone(),
                mode: request.mode.clone(),
                composition_route_class: Some(composition_route_class.clone()),
                interpreted_goal: plan.interpreted_goal.clone(),
                candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
                next_attempt_kind: extension_shape.extension_kind.clone(),
                funnel_stage: funnel_stage.clone(),
                next_attempt_mechanics: next_attempt_mechanics.clone(),
                promoted_constraint_summaries: promoted_constraint_summaries.clone(),
                host_shape_substitution_forbidden: true,
                suggested_substrate_kind: extension_shape.suggested_substrate_kind.clone(),
                suggested_tool_kind: extension_shape.suggested_tool_kind.clone(),
                suggested_patch_kind: extension_shape.suggested_patch_kind.clone(),
                suggested_bridge_capabilities: extension_shape
                    .suggested_bridge_capabilities
                    .clone(),
                suggested_hosting_mode: extension_shape.suggested_hosting_mode.clone(),
                requested_capabilities: request.requested_capabilities.clone(),
                constraints: constraints.clone(),
                missing_base_build_primitive_classes: extension_shape
                    .missing_base_build_primitive_classes
                    .clone(),
                missing_patch_primitive_classes: extension_shape
                    .missing_patch_primitive_classes
                    .clone(),
                missing_helper_primitive_kinds: extension_shape
                    .missing_helper_primitive_kinds
                    .clone(),
                suggested_artifacts: extension_shape.suggested_artifacts.clone(),
                acceptance_targets: extension_shape.acceptance_targets.clone(),
                implementation_notes: extension_shape.implementation_notes.clone(),
                comparison_seed_template_id: None,
                comparison_seed_bundle_id: None,
                attempt_bundle_path: None,
                recommended_next_action: String::new(),
                recommended_next_step: String::new(),
                created_at: None,
            },
        )
        .map(|(template, bundle)| (template.template_id, bundle.bundle_id))
    } else {
        None
    };
    let clarification = ClarificationRequest {
        clarification_id: chatty_factory_core::timestamp_id("clarification"),
        request_id: request.request_id.clone(),
        mode: request.mode.clone(),
        question: next_attempt_question(request, plan, active_spec, &next_attempt_shape),
        reasons: reasons.clone(),
        candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let clarification_path = runtime_root
        .join("clarifications")
        .join(format!("{}-clarification.json", request.request_id));
    persist_json_pretty(&clarification_path, &clarification)?;
    let next_attempt_action =
        next_attempt_recommended_action(request, plan, &next_attempt_shape);

    let build_spec = NextAttemptBuildSpec {
        next_attempt_spec_id: chatty_factory_core::timestamp_id("next-attempt-build-spec"),
        request_id: request.request_id.clone(),
        mode: request.mode.clone(),
        composition_route_class: Some(composition_route_class.clone()),
        interpreted_goal: plan.interpreted_goal.clone(),
        candidate_substrate_kinds: plan.inferred_substrate_candidates.clone(),
        next_attempt_kind: extension_shape.extension_kind.clone(),
        funnel_stage: funnel_stage.clone(),
        next_attempt_mechanics: next_attempt_mechanics.clone(),
        promoted_constraint_summaries: promoted_constraint_summaries.clone(),
        host_shape_substitution_forbidden: true,
        suggested_substrate_kind: extension_shape.suggested_substrate_kind.clone(),
        suggested_tool_kind: extension_shape.suggested_tool_kind.clone(),
        suggested_patch_kind: extension_shape.suggested_patch_kind.clone(),
        suggested_bridge_capabilities: extension_shape.suggested_bridge_capabilities.clone(),
        suggested_hosting_mode: extension_shape.suggested_hosting_mode.clone(),
        requested_capabilities: request.requested_capabilities.clone(),
        constraints: constraints.clone(),
        missing_base_build_primitive_classes: extension_shape
            .missing_base_build_primitive_classes
            .clone(),
        missing_patch_primitive_classes: extension_shape.missing_patch_primitive_classes.clone(),
        missing_helper_primitive_kinds: extension_shape.missing_helper_primitive_kinds.clone(),
        suggested_artifacts: extension_shape.suggested_artifacts.clone(),
        acceptance_targets: extension_shape.acceptance_targets.clone(),
        implementation_notes: extension_shape.implementation_notes.clone(),
        comparison_seed_template_id: comparison_seed_recommendation
            .as_ref()
            .map(|(template_id, _)| template_id.clone()),
        comparison_seed_bundle_id: comparison_seed_recommendation
            .as_ref()
            .map(|(_, bundle_id)| bundle_id.clone()),
        attempt_bundle_path: None,
        recommended_next_action: next_attempt_action.action_id.clone(),
        recommended_next_step: next_attempt_action.recommended_next_step.clone(),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let pending_registry_path = runtime_root
        .parent()
        .map(|root| root.join("operator_registry").join("pending_lanes.json"))
        .unwrap_or_else(|| PathBuf::from("operator_registry").join("pending_lanes.json"));
    let pending_matches = match_pending_extensions(
        &load_pending_extension_registry(&pending_registry_path)?,
        &build_spec,
    );
    if !pending_matches.is_empty() {
        reasons.push("matching pending deterministic lane already exists with the same unresolved layer profile".into());
        reasons = dedup_strings(reasons);
    }
    let attempt_bundle_path =
        persist_next_attempt_bundle(runtime_root, request, plan, active_spec, &build_spec)?;
    let mut build_spec = build_spec;
    build_spec.attempt_bundle_path = Some(attempt_bundle_path.display().to_string());
    if !pending_matches.is_empty() {
        build_spec.recommended_next_action = "continue_pending_attempt_implementation".into();
        build_spec.recommended_next_step =
            "continue implementing the matching pending deterministic attempt with the same unresolved layer profile, or promote it from pending to executable registry code".into();
    }
    let build_spec_path = runtime_root
        .join("next_attempt_build_specs")
        .join(format!("{}-next-attempt-build-spec.json", request.request_id));
    persist_json_pretty(&build_spec_path, &build_spec)?;

    let planner_handoff = derive_planner_handoff(request, plan, active_spec);
    let planner_handoff_path = runtime_root
        .join("planner_handoffs")
        .join(format!("{}.json", planner_handoff.handoff_id));
    persist_json_pretty(&planner_handoff_path, &planner_handoff)?;

    let receipt = NextAttemptReceipt {
        next_attempt_receipt_id: chatty_factory_core::timestamp_id("next-attempt-plan"),
        request_id: request.request_id.clone(),
        mode: request.mode.clone(),
        status: "next_attempt_required".into(),
        reasons: reasons.clone(),
        funnel_stage: funnel_stage.clone(),
        next_attempt_mechanics: next_attempt_mechanics.clone(),
        evidence_receipt_paths: vec![
            clarification_path.display().to_string(),
            build_spec_path.display().to_string(),
            planner_handoff_path.display().to_string(),
            composable_route_plan_path.display().to_string(),
            attempt_bundle_path.display().to_string(),
        ],
        clarification_path: Some(clarification_path.display().to_string()),
        build_spec_path: Some(build_spec_path.display().to_string()),
        planner_handoff_path: Some(planner_handoff_path.display().to_string()),
        attempt_bundle_path: Some(attempt_bundle_path.display().to_string()),
        created_at: Some(chatty_factory_core::timestamp_id("created")),
    };
    let receipt_path = runtime_root
        .join("next_attempt_receipts")
        .join(format!("{}-next-attempt.json", request.request_id));
    persist_json_pretty(&receipt_path, &receipt)?;

    let (
        build_verification,
        build_verification_path,
        proposed_constraint,
        proposed_constraint_path,
    ) = if matches!(request.mode, Some(RequestMode::NewBuild)) {
        if let Some((verification, verification_path)) =
            load_existing_build_verification_receipt(runtime_root, &request.request_id)
        {
            let proposed = load_proposed_constraint_receipt_for_source_verification(
                runtime_root,
                &verification.verification_id,
            )
            .or_else(|| {
                load_existing_proposed_constraint_receipt(runtime_root, &request.request_id)
            });
            (
                Some(verification),
                Some(verification_path),
                proposed.as_ref().map(|(receipt, _)| receipt.clone()),
                proposed.map(|(_, path)| path),
            )
        } else {
            let verification = derive_build_verification_receipt(
                runtime_root,
                request,
                plan,
                &build_spec,
                &reasons,
                summary,
            );
            let verification_path =
                persist_build_verification_receipt(runtime_root, &verification)?;
            let (_triangulation_paths, proposed_constraint, proposed_constraint_path) =
                record_build_verification_triangulation(
                    runtime_root,
                    request,
                    &verification,
                    &verification_path,
                )?;
            (
                Some(verification),
                Some(verification_path),
                proposed_constraint,
                proposed_constraint_path,
            )
        }
    } else {
        (None, None, None, None)
    };

    let mut details = vec![
        format!("clarification={}", clarification_path.display()),
        format!("next_attempt_build_spec={}", build_spec_path.display()),
        format!("planner_handoff={}", planner_handoff_path.display()),
        format!(
            "composable_route_plan={}",
            composable_route_plan_path.display()
        ),
        format!("next_attempt_receipt={}", receipt_path.display()),
    ];
    if let Some(path) = &build_verification_path {
        details.push(format!("build_verification={}", path.display()));
    }
    if let Some(path) = &proposed_constraint_path {
        details.push(format!("proposed_constraint={}", path.display()));
    }
    let (outcome_class, outcome_notes) = classify_next_attempt_outcome(request, plan, summary);

    Ok(HostActionResult {
        summary: summary.into(),
        details,
        browser_state: None,
        runtime_refresh: None,
        execution_result: None,
        next_attempt_result: Some(HostNextAttemptResult {
            request_id: request.request_id.clone(),
            mode: request.mode.as_ref().map(|mode| match mode {
                chatty_factory_core::RequestMode::NewBuild => "new_build".to_string(),
                chatty_factory_core::RequestMode::Patch => "patch".to_string(),
            }),
            outcome_class: Some(outcome_class),
            outcome_notes,
            composition_route_class: Some(composition_route_class_label(&composition_route_class)),
            composable_route_plan_path: Some(composable_route_plan_path.display().to_string()),
            composition_review_receipt_path: None,
            question: clarification.question,
            interpreted_goal: plan.interpreted_goal.clone(),
            reasons,
            funnel_stage,
            next_attempt_mechanics,
            evidence_receipt_paths: {
                let mut paths = vec![
                    clarification_path.display().to_string(),
                    build_spec_path.display().to_string(),
                    planner_handoff_path.display().to_string(),
                    composable_route_plan_path.display().to_string(),
                    attempt_bundle_path.display().to_string(),
                ];
                if let Some(path) = &build_verification_path {
                    paths.push(path.display().to_string());
                }
                if let Some(path) = &proposed_constraint_path {
                    paths.push(path.display().to_string());
                }
                paths
            },
            host_shape_substitution_forbidden: true,
            candidate_substrate_kinds: plan
                .inferred_substrate_candidates
                .iter()
                .map(|kind| kind.as_str().to_string())
                .collect(),
            requested_capabilities: request.requested_capabilities.clone(),
            constraints,
            next_attempt_kind: build_spec.next_attempt_kind.clone(),
            suggested_substrate_kind: build_spec
                .suggested_substrate_kind
                .as_ref()
                .map(|kind| kind.as_str().to_string()),
            suggested_tool_kind: build_spec.suggested_tool_kind.clone(),
            suggested_patch_kind: build_spec.suggested_patch_kind.clone(),
            suggested_bridge_capabilities: build_spec.suggested_bridge_capabilities.clone(),
            suggested_hosting_mode: build_spec.suggested_hosting_mode.clone(),
            suggested_artifacts: build_spec.suggested_artifacts.clone(),
            missing_base_build_primitive_classes: build_spec
                .missing_base_build_primitive_classes
                .clone(),
            missing_patch_primitive_classes: build_spec.missing_patch_primitive_classes.clone(),
            missing_helper_primitive_kinds: build_spec.missing_helper_primitive_kinds.clone(),
            acceptance_targets: build_spec.acceptance_targets.clone(),
            implementation_notes: build_spec.implementation_notes.clone(),
            comparison_seed_template_id: build_spec.comparison_seed_template_id.clone(),
            comparison_seed_bundle_id: build_spec.comparison_seed_bundle_id.clone(),
            recommended_next_action: Some(build_spec.recommended_next_action.clone()),
            recommended_next_step: build_spec.recommended_next_step,
            pending_attempt_ids: pending_matches
                .iter()
                .map(|entry| entry.entry_id.clone())
                .collect(),
            pending_attempt_bundle_roots: pending_matches
                .iter()
                .map(|entry| entry.attempt_bundle_root.clone())
                .collect(),
            chattycog_requested_hosting_mode: next_attempt_shape.requested_hosting_mode,
            chattycog_valid_hosting_modes: next_attempt_shape.valid_hosting_modes,
            chattycog_requested_bridge_capabilities: next_attempt_shape.requested_bridge_capabilities,
            chattycog_supported_bridge_capabilities: next_attempt_shape.supported_bridge_capabilities,
            clarification_path: Some(clarification_path.display().to_string()),
            build_spec_path: Some(build_spec_path.display().to_string()),
            planner_handoff_path: Some(planner_handoff_path.display().to_string()),
            attempt_bundle_path: Some(attempt_bundle_path.display().to_string()),
            build_failure_class: build_verification
                .as_ref()
                .map(|verification| verification.normalized_failure_class.clone()),
            build_failure_mode: build_verification
                .as_ref()
                .map(|verification| verification.failure_mode.clone()),
            matched_approved_constraint_ids: build_verification
                .as_ref()
                .map(|verification| verification.matched_approved_constraint_ids.clone())
                .unwrap_or_default(),
            matched_approved_constraint_summaries: build_verification
                .as_ref()
                .map(|verification| verification.matched_approved_constraint_summaries.clone())
                .unwrap_or_default(),
            build_verification_path: build_verification_path
                .as_ref()
                .map(|path| path.display().to_string()),
            proposed_constraint_path: proposed_constraint_path
                .as_ref()
                .map(|path| path.display().to_string()),
            proposed_constraint_summary: proposed_constraint
                .as_ref()
                .map(|receipt| receipt.proposed_constraint.forbidden_method_summary.clone()),
            proposed_constraint_replacement_guidance: proposed_constraint
                .as_ref()
                .and_then(|receipt| receipt.proposed_constraint.replacement_guidance.clone()),
            receipt_path: Some(receipt_path.display().to_string()),
        }),
        followup_route: None,
        extension_registry: None,
    })
}

fn next_attempt_funnel_stage(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> String {
    if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
        "retry_under_frozen_patch_intent".into()
    } else if plan.needs_llm_review {
        "classify_and_retry_under_promoted_constraints".into()
    } else if chattycog_shape.has_hosting_conflict
        || chattycog_shape.exceeds_current_contract
        || !chattycog_shape.unsupported_bridge_capabilities.is_empty()
    {
        "decompose_and_retry_with_narrower_hosting_constraints".into()
    } else {
        "classify_and_retry_under_frozen_build_intent".into()
    }
}

fn next_attempt_mechanics_list(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> Vec<String> {
    let mut mechanics = vec![
        "fail_honestly_against_the_frozen_intent".into(),
        "classify_failure_before_any_retry".into(),
        "retry_with_a_mechanical_delta_derived_from_evidence".into(),
    ];
    if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
        mechanics.push("preserve_the_active_project_and_change_only_the_patch_attempt_method".into());
    } else {
        mechanics.push("preserve_the_requested_artifact_intent_and_do_not_substitute_shape".into());
    }
    if !plan.constraints.is_empty() || !plan.escalation_reasons.is_empty() {
        mechanics.push("promote_constraints_from_receipts_before_the_next_attempt".into());
    }
    mechanics.push("decompose_smaller_if_the_same_attempt_shape_keeps_failing".into());
    mechanics.push("triangulate_against_failure_library_and_prior_receipts".into());
    mechanics.push("compare_against_prior_receipts_before_changing_method_or_model".into());
    if chattycog_shape.has_hosting_conflict
        || chattycog_shape.exceeds_current_contract
        || !chattycog_shape.unsupported_bridge_capabilities.is_empty()
    {
        mechanics.push("narrow_the_hosting_or_bridge_attempt_without_inventing_a_replacement_artifact".into());
    }
    mechanics.push("alter_method_or_toolchain_only_if_receipts_justify_it".into());
    mechanics.push("change_model_only_if_the_failure_pattern_points_to_model_limitation".into());
    mechanics
}

#[derive(Debug, Clone, Default)]
struct NextAttemptExtensionShape {
    extension_kind: String,
    suggested_substrate_kind: Option<chatty_factory_core::SubstrateKind>,
    suggested_tool_kind: Option<String>,
    suggested_patch_kind: Option<String>,
    suggested_bridge_capabilities: Vec<String>,
    suggested_hosting_mode: Option<String>,
    missing_base_build_primitive_classes: Vec<String>,
    missing_patch_primitive_classes: Vec<String>,
    missing_helper_primitive_kinds: Vec<String>,
    suggested_artifacts: Vec<String>,
    acceptance_targets: Vec<String>,
    implementation_notes: Vec<String>,
}

fn derive_next_attempt_extension_shape(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    active_spec: Option<&ProjectSpec>,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> NextAttemptExtensionShape {
    let requested_hosting_mode = chattycog_shape.requested_hosting_mode.clone();
    let suggested_substrate_kind = if let Some(spec) = active_spec {
        project_spec_substrate_kind(spec)
    } else if let Some(mode) = requested_hosting_mode.as_deref() {
        match mode {
            "hosted_webview" => Some(chatty_factory_core::SubstrateKind::Webview),
            "hosted_native_window" => Some(chatty_factory_core::SubstrateKind::NativeWindow),
            _ => plan.inferred_substrate_candidates.first().cloned(),
        }
    } else {
        plan.inferred_substrate_candidates.first().cloned()
    };
    let suggested_tool_kind = active_spec
        .and_then(|spec| spec.tool_kind.clone())
        .or_else(|| plan.inferred_tool_kind.clone());
    let (
        missing_base_build_primitive_classes,
        missing_patch_primitive_classes,
        missing_helper_primitive_kinds,
    ) = derive_missing_composition_layers(
        request,
        suggested_substrate_kind.as_ref(),
        suggested_tool_kind.as_deref(),
        active_spec,
    );
    let suggested_patch_kind =
        if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
            plan.intended_patch_kind
                .clone()
                .or_else(|| Some("new_patch_lane".to_string()))
        } else {
            None
        };

    if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
        let extension_kind = classify_extension_kind(
            request.mode.as_ref(),
            &[],
            &missing_base_build_primitive_classes,
            &missing_patch_primitive_classes,
            &missing_helper_primitive_kinds,
            false,
            false,
        );
        return NextAttemptExtensionShape {
            extension_kind,
            suggested_substrate_kind,
            suggested_tool_kind,
            suggested_patch_kind,
            suggested_bridge_capabilities: Vec::new(),
            suggested_hosting_mode: requested_hosting_mode,
            missing_base_build_primitive_classes,
            missing_patch_primitive_classes,
            missing_helper_primitive_kinds,
            suggested_artifacts: vec![
                "PATCH_RECIPE_STUB.json".into(),
                "ACCEPTANCE_STUB.json".into(),
                "README.md".into(),
            ],
            acceptance_targets: vec![
                "patch_acceptance_passes".into(),
                "project_contract_refreshes".into(),
            ],
            implementation_notes: vec![
                "Implement a deterministic patch lane instead of routing this request through freeform planner output.".into(),
                "Prefer a registry-backed patch recipe keyed by substrate and tool facts.".into(),
                "Record missing primitive coverage in terms of substrate-build classes, patch classes, and helper kinds.".into(),
            ],
        };
    }

    if !chattycog_shape.unsupported_bridge_capabilities.is_empty() {
        let extension_kind = classify_extension_kind(
            request.mode.as_ref(),
            &chattycog_shape.unsupported_bridge_capabilities,
            &missing_base_build_primitive_classes,
            &missing_patch_primitive_classes,
            &missing_helper_primitive_kinds,
            true,
            false,
        );
        return NextAttemptExtensionShape {
            extension_kind,
            suggested_substrate_kind,
            suggested_tool_kind,
            suggested_patch_kind,
            suggested_bridge_capabilities: chattycog_shape
                .unsupported_bridge_capabilities
                .clone(),
            suggested_hosting_mode: requested_hosting_mode,
            missing_base_build_primitive_classes,
            missing_patch_primitive_classes,
            missing_helper_primitive_kinds,
            suggested_artifacts: vec![
                "BRIDGE_LANE_STUB.json".into(),
                "ACCEPTANCE_STUB.json".into(),
                "README.md".into(),
            ],
            acceptance_targets: vec![
                "chattycog_bridge_contract".into(),
                "chattycog_module_contract".into(),
            ],
            implementation_notes: vec![
                "Add the requested bridge capability as a deterministic emitted artifact plus validator coverage.".into(),
                "Keep the module standalone-first and expose the bridge lane through typed contract flags.".into(),
                "Document which primitive layers remain unresolved while the bridge lane is missing.".into(),
            ],
        };
    }

    if chattycog_shape.exceeds_current_contract {
        let extension_kind = classify_extension_kind(
            request.mode.as_ref(),
            &[],
            &missing_base_build_primitive_classes,
            &missing_patch_primitive_classes,
            &missing_helper_primitive_kinds,
            false,
            true,
        );
        return NextAttemptExtensionShape {
            extension_kind,
            suggested_substrate_kind,
            suggested_tool_kind,
            suggested_patch_kind,
            suggested_bridge_capabilities: Vec::new(),
            suggested_hosting_mode: requested_hosting_mode,
            missing_base_build_primitive_classes,
            missing_patch_primitive_classes,
            missing_helper_primitive_kinds,
            suggested_artifacts: vec![
                "HELPER_LANE_STUB.json".into(),
                "ACCEPTANCE_STUB.json".into(),
                "README.md".into(),
            ],
            acceptance_targets: vec![
                "hosted_module_contract_preserved".into(),
                "helper_boundary_documented".into(),
            ],
            implementation_notes: vec![
                "Split hosted ChattyCog UI concerns from helper or service concerns.".into(),
                "Model helper/runtime work as a new deterministic lane rather than stretching the current hosting contract.".into(),
                "Document which helper primitive kinds are still missing from the current substrate.".into(),
            ],
        };
    }

    NextAttemptExtensionShape {
        extension_kind: classify_extension_kind(
            request.mode.as_ref(),
            &[],
            &missing_base_build_primitive_classes,
            &missing_patch_primitive_classes,
            &missing_helper_primitive_kinds,
            false,
            false,
        ),
        suggested_substrate_kind,
        suggested_tool_kind,
        suggested_patch_kind,
        suggested_bridge_capabilities: Vec::new(),
        suggested_hosting_mode: requested_hosting_mode,
        missing_base_build_primitive_classes,
        missing_patch_primitive_classes,
        missing_helper_primitive_kinds,
        suggested_artifacts: vec![
            "BASE_BUILD_STUB.json".into(),
            "ACCEPTANCE_STUB.json".into(),
            "README.md".into(),
        ],
        acceptance_targets: vec![
            "base_build_acceptance_passes".into(),
            "project_contract_emitted".into(),
        ],
        implementation_notes: vec![
            "Define a deterministic base-build attempt instead of falling back to prompt-shaped code generation.".into(),
            "Anchor the next attempt in emitted contract data and host-owned acceptance.".into(),
            "Use the missing primitive layers to decide whether this should land as base-build, patch, helper, bridge, or a composition bundle.".into(),
        ],
    }
}

fn persist_next_attempt_bundle(
    runtime_root: &Path,
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    active_spec: Option<&ProjectSpec>,
    build_spec: &NextAttemptBuildSpec,
) -> Result<PathBuf> {
    let stub_root = runtime_root
        .join("next_attempts")
        .join(request.request_id.as_str());
    fs::create_dir_all(&stub_root)?;

    persist_json_pretty(&stub_root.join("NEXT_ATTEMPT_SPEC.json"), build_spec)?;

    let readme = format!(
        "# Next Attempt Bundle\n\nRequest: `{}`\n\nInterpreted goal: {}\n\nNext attempt kind: `{}`\n\nRecommended next step: {}\n\nSuggested substrate: `{}`\nSuggested tool kind: `{}`\nSuggested patch kind: `{}`\nSuggested hosting mode: `{}`\nComparison seed template: `{}`\nComparison seed bundle: `{}`\n\nMissing base build primitive classes:\n{}\n\nMissing patch primitive classes:\n{}\n\nMissing helper primitive kinds:\n{}\n\nAcceptance targets:\n{}\n\nImplementation notes:\n{}\n",
        request.raw_request.trim(),
        build_spec.interpreted_goal,
        build_spec.next_attempt_kind,
        build_spec.recommended_next_step,
        build_spec
            .suggested_substrate_kind
            .as_ref()
            .map(|kind| kind.as_str())
            .unwrap_or("none"),
        build_spec.suggested_tool_kind.as_deref().unwrap_or("none"),
        build_spec.suggested_patch_kind.as_deref().unwrap_or("none"),
        build_spec.suggested_hosting_mode.as_deref().unwrap_or("none"),
        build_spec
            .comparison_seed_template_id
            .as_deref()
            .unwrap_or("none"),
        build_spec
            .comparison_seed_bundle_id
            .as_deref()
            .unwrap_or("none"),
        if build_spec.missing_base_build_primitive_classes.is_empty() {
            "- none".to_string()
        } else {
            build_spec
                .missing_base_build_primitive_classes
                .iter()
                .map(|item| format!("- {item}"))
                .collect::<Vec<_>>()
                .join("\n")
        },
        if build_spec.missing_patch_primitive_classes.is_empty() {
            "- none".to_string()
        } else {
            build_spec
                .missing_patch_primitive_classes
                .iter()
                .map(|item| format!("- {item}"))
                .collect::<Vec<_>>()
                .join("\n")
        },
        if build_spec.missing_helper_primitive_kinds.is_empty() {
            "- none".to_string()
        } else {
            build_spec
                .missing_helper_primitive_kinds
                .iter()
                .map(|item| format!("- {item}"))
                .collect::<Vec<_>>()
                .join("\n")
        },
        build_spec
            .acceptance_targets
            .iter()
            .map(|item| format!("- {item}"))
            .collect::<Vec<_>>()
            .join("\n"),
        build_spec
            .implementation_notes
            .iter()
            .map(|item| format!("- {item}"))
            .collect::<Vec<_>>()
            .join("\n"),
    );
    fs::write(stub_root.join("README.md"), readme)?;

    let stub_payload = serde_json::json!({
        "request_id": request.request_id,
        "raw_request": request.raw_request,
        "interpreted_goal": plan.interpreted_goal,
        "active_project": request.active_project,
        "candidate_substrate_kinds": build_spec.candidate_substrate_kinds.iter().map(|kind| kind.as_str()).collect::<Vec<_>>(),
        "active_project_tool_kind": active_spec.and_then(|spec| spec.tool_kind.clone()),
        "suggested_substrate_kind": build_spec.suggested_substrate_kind.as_ref().map(|kind| kind.as_str()).unwrap_or("none"),
        "next_attempt_kind": build_spec.next_attempt_kind,
        "requested_capabilities": build_spec.requested_capabilities,
        "constraints": build_spec.constraints,
        "acceptance_targets": build_spec.acceptance_targets,
        "implementation_notes": build_spec.implementation_notes,
        "comparison_seed_template_id": build_spec.comparison_seed_template_id,
        "comparison_seed_bundle_id": build_spec.comparison_seed_bundle_id,
    });

    for artifact in &build_spec.suggested_artifacts {
        let artifact_path = stub_root.join(artifact);
        if artifact.ends_with(".json") {
            persist_json_pretty(&artifact_path, &stub_payload)?;
        } else if !artifact_path.exists() {
            fs::write(
                artifact_path,
                "Fill this bundle in as the deterministic next attempt is implemented.\n",
            )?;
        }
    }

    Ok(stub_root)
}

fn unresolved_attempt_layers(build_spec: &NextAttemptBuildSpec) -> Vec<&'static str> {
    if build_spec.next_attempt_kind == "proof_harness_bundle" {
        return vec!["proof_harness"];
    }
    let mut layers = Vec::new();
    if !build_spec.missing_base_build_primitive_classes.is_empty() {
        layers.push("base_build");
    }
    if !build_spec.missing_patch_primitive_classes.is_empty()
        || build_spec.next_attempt_kind == "patch_recipe"
    {
        layers.push("patch");
    }
    if !build_spec.missing_helper_primitive_kinds.is_empty()
        || build_spec.next_attempt_kind == "helper_lane"
    {
        layers.push("helper");
    }
    if !build_spec.suggested_bridge_capabilities.is_empty()
        || build_spec.next_attempt_kind == "chattycog_bridge_lane"
    {
        layers.push("bridge");
    }
    if layers.is_empty() {
        layers.push("base_build");
    }
    layers
}

fn next_attempt_question(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    active_spec: Option<&ProjectSpec>,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> String {
    if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
        let project_name = request
            .active_project
            .as_deref()
            .or_else(|| active_spec.map(|spec| spec.project_name.as_str()))
            .unwrap_or("the active project");
        format!(
            "What concrete capability or output should the patch add to {}?",
            project_name
        )
    } else if chattycog_shape.is_chattycog_request && chattycog_shape.has_hosting_conflict {
        format!(
            "Should this ChattyCog module be hosted as a webview or a native window? Valid modes: {}.",
            chattycog_shape.valid_hosting_modes.join(", ")
        )
    } else if chattycog_shape.is_chattycog_request
        && chattycog_shape.requested_hosting_mode.is_none()
        && plan.inferred_substrate_candidates.is_empty()
    {
        format!(
            "Which ChattyCog hosting mode should this module use: {}?",
            chattycog_shape.valid_hosting_modes.join(", ")
        )
    } else if chattycog_shape.is_chattycog_request && chattycog_shape.exceeds_current_contract {
        format!(
            "Which ChattyCog hosting mode should this module use, and which unsupported capability should be deferred or moved into a new deterministic lane? Valid modes: {}.",
            chattycog_shape.valid_hosting_modes.join(", ")
        )
    } else if chattycog_shape.is_chattycog_request
        && !chattycog_shape.unsupported_bridge_capabilities.is_empty()
    {
        format!(
            "Which ChattyCog bridge capabilities are actually required here? Requested unsupported lanes: {}. Currently supported lanes: {}.",
            chattycog_shape.unsupported_bridge_capabilities.join(", "),
            chattycog_shape.supported_bridge_capabilities.join(", ")
        )
    } else if plan.inferred_substrate_candidates.is_empty() {
        "What concrete substrate or stack should this build target?".into()
    } else {
        "What concrete build substrate or execution surface should the next attempt use for this request?".into()
    }
}

#[derive(Debug, Clone, Default)]
struct ChattyCogNextAttemptShape {
    is_chattycog_request: bool,
    requested_hosting_mode: Option<String>,
    valid_hosting_modes: Vec<String>,
    requested_bridge_capabilities: Vec<String>,
    supported_bridge_capabilities: Vec<String>,
    unsupported_bridge_capabilities: Vec<String>,
    has_hosting_conflict: bool,
    exceeds_current_contract: bool,
}

fn derive_chattycog_next_attempt_shape(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
) -> ChattyCogNextAttemptShape {
    let lower = request.raw_request.to_ascii_lowercase();
    let requested_modes = infer_chattycog_hosting_modes_from_text(&lower);
    let requested_hosting_mode = infer_chattycog_hosting_mode_from_text(&lower).map(str::to_string);
    let requested_bridge_capabilities = infer_chattycog_bridge_capabilities_from_text(&lower);
    let supported_bridge_capabilities = supported_chattycog_bridge_capabilities();
    let unsupported_bridge_capabilities = requested_bridge_capabilities
        .iter()
        .filter(|cap| {
            !supported_bridge_capabilities
                .iter()
                .any(|item| item == *cap)
        })
        .cloned()
        .collect::<Vec<_>>();
    let is_chattycog_request = matches!(
        request.exoskeleton_target,
        Some(chatty_factory_core::ExoskeletonTarget::ChattyCog)
    ) || request_mentions_chattycog(&lower);
    let has_hosting_conflict = requested_modes.len() > 1
        || plan
            .constraints
            .iter()
            .any(|item| item.contains("multiple ChattyCog hosting modes"));
    let exceeds_current_contract = plan.constraints.iter().any(|item| {
        item.contains(
            "requested ChattyCog module shape exceeds the current deterministic hosting contract",
        )
    });

    ChattyCogNextAttemptShape {
        is_chattycog_request,
        requested_hosting_mode,
        valid_hosting_modes: chattycog_valid_hosting_modes(),
        requested_bridge_capabilities,
        supported_bridge_capabilities,
        unsupported_bridge_capabilities,
        has_hosting_conflict,
        exceeds_current_contract,
    }
}

fn next_attempt_recommended_step(
    request: &chatty_factory_core::RequestRecord,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> String {
    if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
        "clarify the follow-up capability or add a new deterministic patch lane".into()
    } else if chattycog_shape.is_chattycog_request && chattycog_shape.has_hosting_conflict {
        "pick one ChattyCog hosting mode and rerun the request, or add a new hosted-module lane if the module must span multiple hosting contracts".into()
    } else if chattycog_shape.is_chattycog_request && chattycog_shape.exceeds_current_contract {
        "pick one supported ChattyCog hosting mode first, then move the unsupported helper/service capability into a new deterministic helper or execution lane".into()
    } else if chattycog_shape.is_chattycog_request
        && !chattycog_shape.unsupported_bridge_capabilities.is_empty()
    {
        "drop the unsupported bridge lanes from the request, or add a new deterministic ChattyCog bridge implementation lane before building this module".into()
    } else if chattycog_shape.is_chattycog_request
        && chattycog_shape.requested_hosting_mode.is_none()
    {
            "clarify whether the module should be hosted as a webview or a native window".into()
    } else {
        "clarify the target substrate or add a new deterministic base-build or composition lane".into()
    }
}

fn next_attempt_recommended_action(
    request: &chatty_factory_core::RequestRecord,
    plan: &chatty_factory_core::RequestPlan,
    chattycog_shape: &ChattyCogNextAttemptShape,
) -> MechanicalNextAction {
    let normalized_failure_class =
        if matches!(request.mode, Some(chatty_factory_core::RequestMode::Patch)) {
            "route_selection_mismatch"
        } else if plan.inferred_substrate_candidates.is_empty() {
            "unsupported_substrate_capability"
        } else if plan.needs_llm_review || chattycog_shape.requested_hosting_mode.is_none() {
            "route_selection_mismatch"
        } else if chattycog_shape.has_hosting_conflict || chattycog_shape.exceeds_current_contract {
            "task_too_broad"
        } else if !chattycog_shape.unsupported_bridge_capabilities.is_empty() {
            "unsupported_substrate_capability"
        } else {
            "verification_failure"
        };
    let mut next_action =
        select_mechanical_next_action(normalized_failure_class, Some("bundle"), 0, false);
    next_action.recommended_next_step = next_attempt_recommended_step(request, chattycog_shape);
    next_action
}

fn dedup_strings(mut items: Vec<String>) -> Vec<String> {
    items.sort();
    items.dedup();
    items
}

fn classify_extension_kind(
    request_mode: Option<&chatty_factory_core::RequestMode>,
    bridge_capabilities: &[String],
    missing_base_build_primitive_classes: &[String],
    missing_patch_primitive_classes: &[String],
    missing_helper_primitive_kinds: &[String],
    chattycog_bridge_only: bool,
    helper_only: bool,
) -> String {
    let has_base_build = !missing_base_build_primitive_classes.is_empty();
    let has_patch = !missing_patch_primitive_classes.is_empty()
        || matches!(request_mode, Some(chatty_factory_core::RequestMode::Patch));
    let has_helper = !missing_helper_primitive_kinds.is_empty();
    let has_bridge = !bridge_capabilities.is_empty() || chattycog_bridge_only;
    let layer_count = [has_base_build, has_patch, has_helper, has_bridge]
        .into_iter()
        .filter(|flag| *flag)
        .count();

    if layer_count > 1 {
        return "composition_bundle".into();
    }
    if has_bridge {
        return "chattycog_bridge_lane".into();
    }
    if helper_only || has_helper {
        return "helper_lane".into();
    }
    if has_patch {
        return "patch_recipe".into();
    }
    "base_build".into()
}

fn closest_built_in_comparison_seed(
    build_spec: &NextAttemptBuildSpec,
) -> Option<(PrimitiveProofTemplate, CapabilityComparisonBundle)> {
    let mut best: Option<(i32, PrimitiveProofTemplate, CapabilityComparisonBundle)> = None;
    let target_substrate_kinds = proof_target_substrate_kinds(build_spec);
    for template in built_in_proof_templates() {
        let Some(bundle) = built_in_capability_comparison_bundles()
            .into_iter()
            .find(|bundle| bundle.bundle_id == template.execution_recipe.comparison_bundle_id)
        else {
            continue;
        };
        let mut score = 0;
        for substrate_kind in &target_substrate_kinds {
            if template.target_substrate_kinds.contains(substrate_kind) {
                score += 5;
            }
        }
        for capability in &build_spec.requested_capabilities {
            if template.required_capability_classes.contains(capability) {
                score += 4;
            } else if template.optional_capability_classes.contains(capability) {
                score += 2;
            }
            if bundle
                .required_shared_capability_classes
                .contains(capability)
            {
                score += 4;
            } else if bundle
                .optional_shared_capability_classes
                .contains(capability)
            {
                score += 2;
            }
        }
        if build_spec
            .interpreted_goal
            .to_lowercase()
            .contains("filtered reporting")
            && template.template_id.contains("filtered_reporting")
        {
            score += 6;
        }
        if build_spec
            .interpreted_goal
            .to_lowercase()
            .contains("status reporting")
            && template.template_id.contains("status_reporting")
        {
            score += 6;
        }
        if build_spec
            .interpreted_goal
            .to_lowercase()
            .contains("summary reporting")
            && template.template_id.contains("summary_reporting")
        {
            score += 6;
        }
        if build_spec
            .interpreted_goal
            .to_lowercase()
            .contains("monitor")
            && template.template_id.contains("helper_monitoring")
        {
            score += 6;
        }
        if best
            .as_ref()
            .map(|(best_score, _, _)| score > *best_score)
            .unwrap_or(true)
        {
            best = Some((score, template, bundle));
        }
    }
    best.map(|(_, template, bundle)| (template, bundle))
}

fn proof_target_substrate_kinds(build_spec: &NextAttemptBuildSpec) -> Vec<chatty_factory_core::SubstrateKind> {
    let mut kinds = build_spec.candidate_substrate_kinds.clone();
    if let Some(kind) = build_spec.suggested_substrate_kind.clone() {
        if !kinds.contains(&kind) {
            kinds.push(kind);
        }
    }
    kinds
}

fn load_pending_extension_registry(path: &Path) -> Result<PendingExtensionRegistry> {
    if !path.exists() {
        return Ok(PendingExtensionRegistry {
            updated_at: chatty_factory_core::timestamp_id("updated"),
            entries: Vec::new(),
        });
    }
    let mut registry: PendingExtensionRegistry = serde_json::from_str(&fs::read_to_string(path)?)?;
    let mut deduped_entries: Vec<PendingExtensionEntry> = Vec::new();
    for mut entry in registry.entries.drain(..) {
        normalize_pending_extension_entry(&mut entry);
        if entry.status == "pending_implementation" {
            if let Some(existing) = deduped_entries.iter_mut().find(|existing| {
                existing.status == "pending_implementation"
                    && pending_extension_profile_matches(existing, &entry)
            }) {
                existing.extension_kind = entry.extension_kind.clone();
                existing.source_stub_path = entry.source_stub_path.clone();
                existing.attempt_bundle_root = entry.attempt_bundle_root.clone();
                existing.integrated_paths = entry.integrated_paths.clone();
                existing.requested_capabilities = entry.requested_capabilities.clone();
                existing.bridge_capabilities = entry.bridge_capabilities.clone();
                continue;
            }
        }
        deduped_entries.push(entry);
    }
    registry.entries = deduped_entries;
    Ok(registry)
}

fn normalize_pending_extension_entry(entry: &mut PendingExtensionEntry) {
    if entry.unresolved_layers.len() > 1 && entry.extension_kind != "composition_bundle" {
        entry.extension_kind = "composition_bundle".into();
    }
}

fn pending_extension_profile_matches(
    left: &PendingExtensionEntry,
    right: &PendingExtensionEntry,
) -> bool {
    left.tool_kind == right.tool_kind
        && left.patch_kind == right.patch_kind
        && left.unresolved_layers == right.unresolved_layers
        && left.missing_base_build_primitive_classes
            == right.missing_base_build_primitive_classes
        && left.missing_patch_primitive_classes == right.missing_patch_primitive_classes
        && left.missing_helper_primitive_kinds == right.missing_helper_primitive_kinds
}

fn validate_composition_bundle_artifacts(entry: &PendingExtensionEntry) -> Result<Vec<String>> {
    let mut blockers = Vec::new();
    let has_patch_layer = entry.unresolved_layers.iter().any(|layer| layer == "patch");
    let has_helper_layer = entry
        .unresolved_layers
        .iter()
        .any(|layer| layer == "helper");
    let has_bridge_layer = entry
        .unresolved_layers
        .iter()
        .any(|layer| layer == "bridge");

    let patch_recipe_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("operator_registry") && path.contains("patch_recipes"))
        .map(PathBuf::from);
    let acceptance_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("operator_registry") && path.contains("acceptance_recipes"))
        .map(PathBuf::from);
    let helper_lane_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("helper_lanes"))
        .map(PathBuf::from);
    let bridge_lane_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("bridge_lanes"))
        .map(PathBuf::from);

    if has_patch_layer {
        match patch_recipe_path {
            Some(ref path) if path.exists() => {
                let value: serde_json::Value = serde_json::from_str(&fs::read_to_string(path)?)?;
                if value
                    .get("recipe_id")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .is_empty()
                {
                    blockers.push("patch recipe artifact is missing recipe_id".into());
                }
            }
            _ => blockers.push("missing integrated patch recipe artifact".into()),
        }
        match acceptance_path {
            Some(ref path) if path.exists() => {}
            _ => blockers.push("missing integrated acceptance recipe artifact".into()),
        }
    }

    if has_helper_layer {
        match helper_lane_path {
            Some(ref path) if path.exists() => {}
            _ => blockers.push("missing integrated helper lane artifact".into()),
        }
    }

    if has_bridge_layer {
        match bridge_lane_path {
            Some(ref path) if path.exists() => {}
            _ => blockers.push("missing integrated bridge lane artifact".into()),
        }
    }

    Ok(blockers)
}

fn validate_proof_harness_bundle_artifacts(entry: &PendingExtensionEntry) -> Result<Vec<String>> {
    let mut blockers = Vec::new();
    let template_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("proof_harness") && path.contains("templates"))
        .map(PathBuf::from);
    let bundle_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("proof_harness") && path.contains("bundles"))
        .map(PathBuf::from);

    let template: Option<PrimitiveProofTemplate> = match template_path {
        Some(ref path) if path.exists() => Some(serde_json::from_str(&fs::read_to_string(path)?)?),
        _ => {
            blockers.push("missing proof template manifest".into());
            None
        }
    };
    let bundle: Option<CapabilityComparisonBundle> = match bundle_path {
        Some(ref path) if path.exists() => Some(serde_json::from_str(&fs::read_to_string(path)?)?),
        _ => {
            blockers.push("missing capability comparison bundle manifest".into());
            None
        }
    };

    if let (Some(template), Some(bundle)) = (template.as_ref(), bundle.as_ref()) {
        if template.template_id.is_empty() {
            blockers.push("proof template manifest is missing template_id".into());
        }
        if bundle.bundle_id.is_empty() {
            blockers.push("comparison bundle manifest is missing bundle_id".into());
        }
        if template.execution_recipe.comparison_bundle_id != bundle.bundle_id {
            blockers.push(format!(
                "proof template comparison bundle mismatch: expected `{}` but found `{}`",
                template.execution_recipe.comparison_bundle_id, bundle.bundle_id
            ));
        }
        blockers.extend(validate_proof_harness_contract(template, bundle));
    }

    Ok(blockers)
}

fn load_proof_harness_bundle_manifests(
    entry: &PendingExtensionEntry,
) -> Result<(PrimitiveProofTemplate, CapabilityComparisonBundle)> {
    let template_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("proof_harness") && path.contains("templates"))
        .map(PathBuf::from)
        .ok_or_else(|| anyhow::anyhow!("missing proof template manifest path"))?;
    let bundle_path = entry
        .integrated_paths
        .iter()
        .find(|path| path.contains("proof_harness") && path.contains("bundles"))
        .map(PathBuf::from)
        .ok_or_else(|| anyhow::anyhow!("missing capability comparison bundle manifest path"))?;
    let template = serde_json::from_str(&fs::read_to_string(&template_path)?)?;
    let bundle = serde_json::from_str(&fs::read_to_string(&bundle_path)?)?;
    Ok((template, bundle))
}

fn validate_proof_harness_contract(
    template: &PrimitiveProofTemplate,
    bundle: &CapabilityComparisonBundle,
) -> Vec<String> {
    let mut blockers = Vec::new();
    if template.target_substrate_kinds.is_empty() {
        blockers.push("proof template must target at least one substrate".into());
    }
    if template.required_capability_classes.is_empty() {
        blockers.push("proof template must require at least one capability class".into());
    }
    if template.execution_recipe.comparison_bundle_id.is_empty() {
        blockers.push("proof template execution recipe is missing comparison_bundle_id".into());
    }
    let mut covered_substrates = Vec::new();
    for binding in &template.execution_recipe.substrate_request_bindings {
        let Some(substrate_kind) = binding.substrate_kind.clone() else {
            blockers.push("substrate request binding is missing substrate_kind".into());
            continue;
        };
        if covered_substrates.contains(&substrate_kind) {
            blockers.push(format!(
                "duplicate substrate request binding for `{}`",
                substrate_kind.as_str()
            ));
        } else {
            covered_substrates.push(substrate_kind);
        }
    }
    for substrate_kind in &template.target_substrate_kinds {
        if !covered_substrates.contains(substrate_kind) {
            blockers.push(format!(
                "missing substrate request binding for target substrate `{}`",
                substrate_kind.as_str()
            ));
        }
    }
    for binding in &template.execution_recipe.enrichment_bindings {
        if let Some(substrate_kind) = binding.substrate_kind.as_ref() {
            if template.target_substrate_kinds.contains(substrate_kind) {
                continue;
            }
            blockers.push(format!(
                "enrichment binding references non-target substrate `{}`",
                substrate_kind.as_str()
            ));
        } else {
            blockers.push("enrichment binding is missing substrate_kind".into());
        }
    }
    if bundle.required_shared_capability_classes.is_empty() {
        blockers.push("comparison bundle must require at least one shared capability class".into());
    }
    if bundle.minimum_shared_capability_count == 0 {
        blockers.push(
            "comparison bundle minimum_shared_capability_count must be greater than zero".into(),
        );
    }
    if bundle.minimum_shared_capability_count
        > bundle.required_shared_capability_classes.len()
            + bundle.optional_shared_capability_classes.len()
    {
        blockers.push("comparison bundle minimum_shared_capability_count exceeds declared shared capability classes".into());
    }
    if bundle.policy.comparison_receipt_prefix.is_empty() {
        blockers.push("comparison bundle policy is missing comparison_receipt_prefix".into());
    }
    if bundle.policy.comparison_label.is_empty() {
        blockers.push("comparison bundle policy is missing comparison_label".into());
    }
    blockers
}

fn evaluate_proof_harness_quality(
    workspace_root: &Path,
    template: &PrimitiveProofTemplate,
    bundle: &CapabilityComparisonBundle,
    seed_template_id: Option<&str>,
    seed_bundle_id: Option<&str>,
) -> (String, Vec<String>) {
    let mut notes = Vec::new();
    let blockers = validate_proof_harness_contract(template, bundle);
    if blockers.is_empty() {
        notes.push("structurally valid proof manifest contract".into());
    } else {
        notes.extend(blockers);
        return ("needs_contract_fix".into(), notes);
    }

    let template_resolved =
        proof_template_by_id_from_root(workspace_root, &template.template_id, None).is_some();
    let bundle_resolved =
        capability_comparison_bundle_by_id_from_root(workspace_root, &bundle.bundle_id).is_some();
    if template_resolved && bundle_resolved {
        notes.push("workspace proof catalog resolves template and bundle ids".into());
    } else {
        if !template_resolved {
            notes.push(format!(
                "workspace proof catalog does not resolve template `{}`",
                template.template_id
            ));
        }
        if !bundle_resolved {
            notes.push(format!(
                "workspace proof catalog does not resolve comparison bundle `{}`",
                bundle.bundle_id
            ));
        }
        return ("catalog_unresolved".into(), notes);
    }

    if let Some(seed_template_id) = seed_template_id {
        notes.push(format!(
            "seeded from built-in template `{seed_template_id}`"
        ));
    }
    if let Some(seed_bundle_id) = seed_bundle_id {
        notes.push(format!(
            "seeded from built-in comparison bundle `{seed_bundle_id}`"
        ));
    }

    if let Some(receipt) =
        latest_proof_harness_receipt_for_template(workspace_root, &template.template_id)
    {
        notes.push(format!(
            "latest paired proof receipt: {}",
            receipt.receipt_id
        ));
        if receipt.equivalent_capability_fulfillment {
            notes.push("latest proof run passed equivalence".into());
            ("passing".into(), notes)
        } else {
            notes.push("latest proof run is runnable but not yet equivalent".into());
            ("runnable_diverged".into(), notes)
        }
    } else {
        notes.push("no paired proof receipt found yet for this template".into());
        ("catalog_resolved".into(), notes)
    }
}

fn latest_proof_harness_receipt_for_template(
    workspace_root: &Path,
    template_id: &str,
) -> Option<PrimitiveProofHarnessReceipt> {
    let root = workspace_root
        .join("runtime")
        .join("legacy_comparison_paired_proof_receipts");
    let entries = fs::read_dir(root).ok()?;
    let mut receipts = entries
        .filter_map(|entry| entry.ok().map(|entry| entry.path()))
        .filter(|path| {
            path.extension()
                .and_then(|ext| ext.to_str())
                .map(|ext| ext.eq_ignore_ascii_case("json"))
                .unwrap_or(false)
        })
        .filter_map(|path| {
            let contents = fs::read_to_string(&path).ok()?;
            let receipt = serde_json::from_str::<PrimitiveProofHarnessReceipt>(&contents).ok()?;
            if receipt.proof_template_id == template_id {
                Some(receipt)
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    receipts.sort_by(|a, b| a.receipt_id.cmp(&b.receipt_id));
    receipts.pop()
}

fn latest_passing_proof_harness_receipt_for_template(
    workspace_root: &Path,
    template_id: &str,
) -> Option<PrimitiveProofHarnessReceipt> {
    let root = workspace_root
        .join("runtime")
        .join("legacy_comparison_paired_proof_receipts");
    let entries = fs::read_dir(root).ok()?;
    let mut receipts = entries
        .filter_map(|entry| entry.ok().map(|entry| entry.path()))
        .filter(|path| {
            path.extension()
                .and_then(|ext| ext.to_str())
                .map(|ext| ext.eq_ignore_ascii_case("json"))
                .unwrap_or(false)
        })
        .filter_map(|path| {
            let contents = fs::read_to_string(&path).ok()?;
            let receipt = serde_json::from_str::<PrimitiveProofHarnessReceipt>(&contents).ok()?;
            if receipt.proof_template_id == template_id && receipt.equivalent_capability_fulfillment
            {
                Some(receipt)
            } else {
                None
            }
        })
        .collect::<Vec<_>>();
    receipts.sort_by(|a, b| a.receipt_id.cmp(&b.receipt_id));
    receipts.pop()
}

